import { useEffect } from "react";
import { X } from "lucide-react";
import { useAppStore } from "../../lib/stores/app-store";
import { Transcript } from "./Transcript";
import { Composer } from "./Composer";
import { SessionStatsPills } from "./StatsPills";
import { InlineExtensionUiRequest } from "./InlineExtensionUiRequest";
import { workspaceDisplayName } from "../workspaces/WorkspacePicker";
import { useT } from "../../lib/i18n/use-t";
import { conversationContentWidthStyle } from "./conversation-layout";
import { TelegramHistoryView } from "../telegram/TelegramHistoryView";
import { useTelegramWorkspaceActive } from "../telegram/telegram-view-store";
import { useSessionTreeSync } from "../tree/tree-data";

export function ChatPage() {
  const t = useT();
  // Keep the shared session tree warm: the inline branch navigators in the
  // transcript and the tree overlay both read from it.
  useSessionTreeSync();
  const workspace = useAppStore((s) => s.workspace);
  const session = useAppStore((s) => s.session);
  const host = useAppStore((s) => s.host);
  const packages = useAppStore((s) => s.packages);
  const authBlocked = useAppStore((s) => s.authBlocked);
  const providerConfigRevision = useAppStore((s) => s.providerConfigRevision);
  const openSettingsSection = useAppStore((s) => s.openSettingsSection);
  const setAuthBlocked = useAppStore((s) => s.setAuthBlocked);
  const conversationMinWidth = useAppStore((s) => s.desktopSettings?.conversationMinWidth);
  const conversationMaxWidth = useAppStore((s) => s.desktopSettings?.conversationMaxWidth);
  const telegramViewActive = useTelegramWorkspaceActive();

  // A login/logout/config save bumps the revision: the blockage the banner
  // describes may be resolved, so re-check by sending again.
  useEffect(() => {
    setAuthBlocked(null);
  }, [providerConfigRevision, setAuthBlocked]);

  const resourceReloadBlocked = packages?.resourceReloadRequired === true;
  const reconcileBlocked = packages?.mutation?.reconcileRequired === true;
  const packageBlocked = resourceReloadBlocked || reconcileBlocked;
  const sessionTreeNavigated = useAppStore((s) => s.sessionTreeNavigated);
  const isNewConversation = Boolean(
    session && session.messages.length === 0 && session.isIdle && !sessionTreeNavigated,
  );

  // The telegram workspace renders its own read-only history surface instead
  // of the normal chat, keeping the bridge session PC-side untouched.
  if (telegramViewActive) {
    return <TelegramHistoryView />;
  }

  if (!workspace) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center gap-2 p-8 text-center text-muted">
        <p className="text-base text-foreground">{t("chatSelectWorkspaceTitle")}</p>
        <p className="text-sm">{t("chatSelectWorkspaceHint")}</p>
      </div>
    );
  }

  if (!workspace.servicesReady) {
    return (
      <div className="flex flex-1 items-center justify-center p-8 text-muted">
        {t("chatWorkspaceServicesNotReady")}
        {host?.lastError?.message ? (
          <span className="ml-2 text-danger">{host.lastError.message}</span>
        ) : null}
      </div>
    );
  }

  return (
    <div
      className="flex min-h-0 flex-1 flex-col"
      data-chat-page
      style={conversationContentWidthStyle(conversationMinWidth, conversationMaxWidth)}
    >
      <div data-chat-content className="flex min-h-0 flex-1 flex-col">
        {authBlocked && (
          <div
            role="status"
            className="flex items-center gap-3 border-b border-warning/40 bg-warning/10 px-4 py-2 text-sm text-warning"
          >
            <span className="min-w-0 flex-1">
              {authBlocked.providerId
                ? t("chatAuthRequiredProvider", { provider: authBlocked.providerId })
                : t("chatAuthRequired")}
            </span>
            <button
              type="button"
              className="shrink-0 rounded-md border border-warning/50 px-2.5 py-1 text-xs font-medium transition-colors hover:bg-warning/15"
              onClick={() => openSettingsSection("providers")}
            >
              {t("chatAuthOpenProviders")}
            </button>
            <button
              type="button"
              aria-label={t("chatAuthDismiss")}
              className="shrink-0 rounded-md p-1 transition-colors hover:bg-warning/15"
              onClick={() => setAuthBlocked(null)}
            >
              <X size={14} />
            </button>
          </div>
        )}
        {packageBlocked && (
          <div className="border-b border-warning/40 bg-warning/10 px-4 py-2 text-sm text-warning">
            {reconcileBlocked ? t("chatPackageReconcileRequired") : t("chatPackageReloadRequired")}
          </div>
        )}
        <div aria-hidden="true" data-chat-header-fade />
        {session ? (
          isNewConversation ? (
            <>
              <InlineExtensionUiRequest />
              <Composer
                disabled={packageBlocked}
                welcomeWorkspaceName={workspaceDisplayName(workspace.cwd)}
              />
              <SessionStatsPills />
            </>
          ) : (
            <>
              <Transcript />
              <InlineExtensionUiRequest />
              <Composer disabled={packageBlocked} />
              <SessionStatsPills />
            </>
          )
        ) : (
          <div className="flex flex-1 items-center justify-center text-sm text-muted">
            {t("chatNoSession")}
          </div>
        )}
      </div>
    </div>
  );
}

import {
  lazy,
  memo,
  Suspense,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";
import {
  Activity,
  ArrowDown,
  Ban,
  Braces,
  ChevronDown,
  ChevronRight,
  ChevronUp,
  CircleAlert,
  CircleCheck,
  Copy,
  ExternalLink,
  FileText,
  FoldVertical,
  GitBranch,
  GitFork,
  Link2,
  ListTree,
  LoaderCircle,
  MessageCircleQuestion,
  PanelRightOpen,
  Play,
  Puzzle,
  RotateCcw,
  Terminal,
} from "lucide-react";
import { useAppStore } from "../../lib/stores/app-store";
import { requestFork } from "../../lib/fork-actions";
import { requestDockBrowser } from "../../lib/dock-browser";
import { openSystemUrl } from "../../lib/open-system-url";
import { isSafeExternalUrl, sanitizeAgentText } from "./markdown-utils";
import { ToolView } from "./ToolView";
import { formatDuration } from "./ToolCard";
import { formatTokenCount } from "../../lib/format-token-count";
import { useLocale, useT, type Translate } from "../../lib/i18n/use-t";
import { piWorkingVariants } from "../../lib/i18n";
import { PiMark } from "../../components/PiMark";
import { CollapsibleRegion } from "../../components/CollapsibleRegion";
import {
  buildTranscriptRows,
  computeRetryableTurns,
  executionTraceIsActive,
  findStreamingAssistantKey,
  parseUserAttachments,
  reuseStableRows,
  thinkingBlockIsLive,
  type RetryableTurn,
  type TranscriptContentBlock,
  type TranscriptBlock,
  type TranscriptRow,
} from "./transcript-model";
import { stripAttachmentReferenceBlocks } from "@piabyss/protocol";
import { BranchNavigator } from "../tree/BranchNavigator";
import { branchAlternatives, type TreeBranchPoint } from "../tree/tree-model";
import { useSessionTree } from "../tree/tree-data";
import { navigateTreeTo } from "../tree/session-tree-nav";
import { TurnJumpRail, turnRailStops } from "./TurnJumpRail";
import { formatCacheHitPercent } from "./stats-format";
import { requestGoOn, requestRetry } from "../../lib/retry-actions";
import { contextMenuTrigger, openContextMenu } from "../../lib/context-menu";
import { shouldKeepNativeContextMenu } from "../../lib/context-menu-policy";
import {
  autoMountFloor,
  createBatchSizer,
  NEAR_TOP_BOOST_VIEWPORTS,
  scheduleIdleMount,
  SCROLL_QUIET_MS,
} from "./progressive-mount";
import {
  requestTranscriptScroll,
  subscribeTranscriptScroll,
  type TranscriptScrollRequest,
} from "../../lib/transcript-navigation";
import {
  forgetTranscriptScrollPosition,
  readTranscriptScrollPosition,
  saveTranscriptScrollPosition,
} from "./transcript-scroll-memory";

const MarkdownMessage = lazy(() =>
  import("./MarkdownMessage").then((module) => ({ default: module.MarkdownMessage })),
);

function MarkdownFallback({ content, className = "" }: { content: string; className?: string }) {
  return (
    <div className={`whitespace-pre-wrap break-words text-sm leading-6 ${className}`}>
      {sanitizeAgentText(content)}
    </div>
  );
}

function LazyMarkdownMessage({
  content,
  mode = "static",
  showCaret = false,
  className,
}: {
  content: string;
  mode?: "streaming" | "static";
  showCaret?: boolean;
  className?: string;
}) {
  return (
    <Suspense fallback={<MarkdownFallback content={content} className={className} />}>
      <MarkdownMessage content={content} mode={mode} showCaret={showCaret} className={className} />
    </Suspense>
  );
}

/**
 * Rows mounted synchronously when a session opens; the idle loop in
 * progressive-mount.ts converges the rest afterwards.
 */
const INITIAL_VISIBLE_ROWS = 60;
const SHOW_EARLIER_CHUNK = 120;
/** Rows mounted above a jump target for reading context. */
const JUMP_CONTEXT_ROWS = 3;

/** Reopen a session at its remembered reading position, else at the tail. */
function initialHiddenFor(sessionId: string | null, rowCount: number): number {
  const tailHidden = Math.max(0, rowCount - INITIAL_VISIBLE_ROWS);
  if (sessionId === null) return tailHidden;
  const remembered = readTranscriptScrollPosition(sessionId);
  if (remembered === undefined) return tailHidden;
  return Math.min(remembered.hidden, Math.max(0, rowCount - 1));
}

export function Transcript() {
  const t = useT();
  const locale = useLocale();
  const session = useAppStore((state) => state.session);
  const providerNames = useAppStore((state) => state.providerNames);
  const messages = useMemo(() => session?.messages ?? [], [session?.messages]);
  // The "Pi 正在处理…" placeholder shows a playful random status per request.
  // A status is picked when a working phase begins and kept until the session
  // goes idle again. A phase begins when the session flips from idle, when the
  // session changes while working, or when this component first mounts into an
  // already-working session — a fresh conversation only mounts the Transcript
  // after its first message is already in flight (see ChatPage), so the
  // idle->working flip is never observed there. Render-phase setState (the
  // same pattern as hiddenState below) avoids a one-frame flash of the static
  // fallback on the first working frame.
  const isWorking = session?.isIdle === false;
  const [workingText, setWorkingText] = useState<string | null>(null);
  const workingPhaseRef = useRef<string | null>(null);
  const workingPhaseKey = session ? `${session.sessionId}:${locale}` : null;
  if (isWorking && workingPhaseKey !== workingPhaseRef.current) {
    const variants = piWorkingVariants(locale);
    setWorkingText(variants[Math.floor(Math.random() * variants.length)] ?? null);
    workingPhaseRef.current = workingPhaseKey;
  } else if (!isWorking && workingText !== null) {
    setWorkingText(null);
    workingPhaseRef.current = null;
  }
  const workingLabel = workingText ?? t("transcriptPiWorking");
  const prevRowsRef = useRef<TranscriptRow[] | null>(null);
  const rows = useMemo(
    () =>
      reuseStableRows(
        prevRowsRef.current,
        buildTranscriptRows(messages, {
          entries: session?.entries,
          leafId: session?.leafId,
          extensionMessageRenders: session?.extensionMessageRenders,
          turnActive: session?.isIdle === false,
          providerNames,
        }),
      ),
    [
      messages,
      session?.entries,
      session?.leafId,
      session?.extensionMessageRenders,
      session?.isIdle,
      providerNames,
    ],
  );
  prevRowsRef.current = rows;
  const sessionKey = session?.sessionId ?? null;

  // Rows cleared by a retry stay hidden for the rest of this session view so
  // the re-sent answer does not sit next to the failed one. The suppression
  // is renderer-only — the append-only SDK session still records the failed
  // entry and it reappears when the session is reopened.
  const [suppressedKeys, setSuppressedKeys] = useState<ReadonlySet<string>>(new Set());
  const suppressedSessionRef = useRef<string | null>(null);
  if (suppressedSessionRef.current !== sessionKey) {
    suppressedSessionRef.current = sessionKey;
    if (suppressedKeys.size > 0) setSuppressedKeys(new Set());
  }
  const shownRows =
    suppressedKeys.size === 0 ? rows : rows.filter((row) => !suppressedKeys.has(row.key));
  const retryableTurns = useMemo(
    () => computeRetryableTurns(rows, suppressedKeys),
    [rows, suppressedKeys],
  );
  const lastFailedAssistantKey = useMemo(() => {
    for (let index = shownRows.length - 1; index >= 0; index -= 1) {
      const row = shownRows[index];
      if (
        row.role === "assistant" &&
        (row.outcome?.status === "error" || row.outcome?.status === "aborted")
      ) {
        return row.key;
      }
    }
    return undefined;
  }, [shownRows]);

  // Inline branch navigators: sibling alternatives for the rows on the
  // current leaf path, derived from the shared session tree. User rows look
  // up by `sourceId`; assistant rows by `sourceEndId` — both match the
  // turn-chain last entry id the tree model keys by. The overlay button and
  // Ctrl+T open the full tree (SessionTreeOverlay).
  const tree = useSessionTree();
  const branchPoints = useMemo(() => {
    if (!tree.tree || !tree.leafId) return new Map<string, TreeBranchPoint>();
    return branchAlternatives(tree.tree, tree.leafId);
  }, [tree.tree, tree.leafId]);
  const branchBusy = session ? !session.isIdle : true;
  const [navigatingBranch, setNavigatingBranch] = useState<string | null>(null);
  const onBranchSelect = useCallback(
    (targetId: string) => {
      if (requestTranscriptScroll({ sourceId: targetId })) return;
      setNavigatingBranch(targetId);
      void navigateTreeTo(targetId, t).finally(() => setNavigatingBranch(null));
    },
    [t],
  );

  // Turn jump rail: user message turns for the right-edge quick jump strip —
  // the fast "back to the first / the Nth message" path for long chats.
  const railStops = useMemo(() => turnRailStops(shownRows), [shownRows]);
  const railVisible = railStops.length >= 2;
  const onRailJump = useCallback((sourceId: string) => {
    requestTranscriptScroll({ sourceId });
  }, []);

  const handleRetry = useCallback(
    (row: TranscriptRow): Promise<void> =>
      requestRetry(row).then((accepted) => {
        if (!accepted) return;
        const turn = retryableTurns.get(row.key);
        if (!turn) return;
        setSuppressedKeys((current) => {
          if (current.has(turn.assistantKey)) return current;
          const next = new Set(current);
          next.add(turn.assistantKey);
          next.add(row.key);
          return next;
        });
      }),
    [retryableTurns],
  );

  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const scrollFrameRef = useRef<number | null>(null);
  const scrollMetricsRef = useRef({ top: 0, height: 0 });
  const followingRef = useRef(true);
  const [following, setFollowing] = useState(true);

  // Persistent reading anchor: the tail spacer's viewport position, captured
  // on genuine user scrolls only. Batch compensation always corrects back to
  // this one baseline, so sub-pixel quantization loss cannot accumulate into
  // a slow directional drift across hundreds of batches.
  const tailAnchorRef = useRef<HTMLDivElement>(null);
  const readingAnchorTopRef = useRef<number | null>(null);
  const programmaticScrollTopRef = useRef<number | null>(null);

  const refreshReadingAnchor = useCallback(() => {
    const tail = tailAnchorRef.current;
    readingAnchorTopRef.current = tail ? tail.getBoundingClientRect().top : null;
  }, []);

  const cancelScheduledScroll = useCallback(() => {
    if (scrollFrameRef.current === null) return;
    cancelAnimationFrame(scrollFrameRef.current);
    scrollFrameRef.current = null;
  }, []);

  const alignToBottom = useCallback(() => {
    const element = scrollRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
    programmaticScrollTopRef.current = element.scrollTop;
    scrollMetricsRef.current = {
      top: element.scrollTop,
      height: element.scrollHeight,
    };
  }, []);

  const scheduleBottomAlignment = useCallback(() => {
    cancelScheduledScroll();
    scrollFrameRef.current = requestAnimationFrame(() => {
      scrollFrameRef.current = null;
      if (followingRef.current) alignToBottom();
    });
  }, [alignToBottom, cancelScheduledScroll]);

  const updateFollowing = useCallback((next: boolean) => {
    followingRef.current = next;
    setFollowing((current) => (current === next ? current : next));
  }, []);

  const stopFollowing = useCallback(() => {
    cancelScheduledScroll();
    updateFollowing(false);
    refreshReadingAnchor();
  }, [cancelScheduledScroll, refreshReadingAnchor, updateFollowing]);

  // Top-anchored window: `hidden` rows stay unmounted above the fold. New
  // rows stream in at the tail without disturbing what is on screen.
  // Derived-during-render so a freshly opened long session only mounts its
  // tail on first paint; idle-time batches then converge toward a fully
  // mounted transcript (see progressive-mount.ts).
  const [hiddenState, setHiddenState] = useState<{ sessionId: string | null; hidden: number }>({
    sessionId: sessionKey,
    hidden: initialHiddenFor(sessionKey, shownRows.length),
  });
  if (hiddenState.sessionId !== sessionKey) {
    // Remember (or forget) the departing session's reading position before
    // the window resets. Idempotent, so the render-phase setState pattern
    // stays safe under double-invoked renders.
    if (hiddenState.sessionId !== null) {
      if (followingRef.current) {
        forgetTranscriptScrollPosition(hiddenState.sessionId);
      } else {
        saveTranscriptScrollPosition(hiddenState.sessionId, {
          hidden: hiddenState.hidden,
          scrollTop: scrollMetricsRef.current.top,
        });
      }
    }
    setHiddenState({
      sessionId: sessionKey,
      hidden: initialHiddenFor(sessionKey, shownRows.length),
    });
  }
  const hidden = Math.min(
    hiddenState.sessionId === sessionKey ? hiddenState.hidden : 0,
    Math.max(0, shownRows.length - 1),
  );
  const visibleRows = hidden > 0 ? shownRows.slice(hidden) : shownRows;
  const expandAnchorRef = useRef<{ prevHeight: number; prevTop: number } | null>(null);
  const hiddenRef = useRef(hidden);
  hiddenRef.current = hidden;

  const mountEarlier = useCallback((count: number, floor = 0) => {
    if (hiddenRef.current <= floor) return;
    const element = scrollRef.current;
    if (element) {
      expandAnchorRef.current = {
        prevHeight: element.scrollHeight,
        prevTop: element.scrollTop,
      };
    }
    setHiddenState((current) => ({
      ...current,
      hidden: Math.max(floor, current.hidden - count),
    }));
  }, []);

  // Row-level navigation: outline/find/search request a row through the
  // transcript-navigation bus; unmounted targets mount synchronously first
  // and the centering runs from the layout effect once the row exists.
  const pendingJumpKeyRef = useRef<string | null>(null);

  const centerRow = useCallback(
    (key: string): boolean => {
      const scroller = scrollRef.current;
      if (!scroller) return false;
      const rowElement = scroller.querySelector<HTMLElement>(`[data-row-key="${CSS.escape(key)}"]`);
      if (!rowElement) return false;
      const rowRect = rowElement.getBoundingClientRect();
      const scrollerRect = scroller.getBoundingClientRect();
      scroller.scrollTop +=
        rowRect.top - scrollerRect.top - Math.max(0, (scroller.clientHeight - rowRect.height) / 2);
      programmaticScrollTopRef.current = scroller.scrollTop;
      scrollMetricsRef.current = {
        top: scroller.scrollTop,
        height: scroller.scrollHeight,
      };
      refreshReadingAnchor();
      return true;
    },
    [refreshReadingAnchor],
  );

  const scrollToRowRef = useRef<(request: TranscriptScrollRequest) => boolean>(() => false);
  scrollToRowRef.current = (request) => {
    let key = request.rowKey;
    if (key === undefined && request.sourceId) {
      const match = rows.find(
        (row) => row.sourceId === request.sourceId || row.sourceEndId === request.sourceId,
      );
      key = match?.key;
    }
    if (key === undefined) return false;
    const index = rows.findIndex((row) => row.key === key);
    if (index < 0) return false;
    stopFollowing();
    if (index < hidden) {
      pendingJumpKeyRef.current = key;
      setHiddenState((current) => ({
        ...current,
        hidden: Math.max(0, Math.min(current.hidden, index - JUMP_CONTEXT_ROWS)),
      }));
      return true;
    }
    return centerRow(key);
  };
  useEffect(() => subscribeTranscriptScroll((request) => scrollToRowRef.current(request)), []);

  // Save the reading position when the transcript unmounts (e.g. workspace
  // switches); session switches are handled by the render-phase reset above.
  const sessionKeyRef = useRef(sessionKey);
  sessionKeyRef.current = sessionKey;
  useEffect(
    () => () => {
      const departing = sessionKeyRef.current;
      if (departing === null) return;
      if (followingRef.current) {
        forgetTranscriptScrollPosition(departing);
      } else {
        saveTranscriptScrollPosition(departing, {
          hidden: hiddenRef.current,
          scrollTop: scrollMetricsRef.current.top,
        });
      }
    },
    [],
  );

  // Idle-time convergence toward a fully mounted transcript (bounded by the
  // full-mount cap). Each batch triggers this effect again through `hidden`,
  // which paces the loop one batch per idle slice. Batch size adapts to the
  // measured cost of this session's rows. Convergence only runs when its
  // scroll adjustments cannot be seen: bottom realignment carries sub-pixel
  // rounding wobble, so a focused reader pinned to the tail pauses the loop
  // until they scroll into history (or the window blurs).
  const mountFloor = autoMountFloor(rows.length);
  const isStreaming = session?.isStreaming === true;
  const batchSizerRef = useRef(createBatchSizer());
  const batchStartRef = useRef<number | null>(null);
  const lastUserScrollAtRef = useRef(0);
  const [windowFocused, setWindowFocused] = useState(() => document.hasFocus());
  useEffect(() => {
    const onFocus = () => setWindowFocused(true);
    const onBlur = () => setWindowFocused(false);
    window.addEventListener("focus", onFocus);
    window.addEventListener("blur", onBlur);
    return () => {
      window.removeEventListener("focus", onFocus);
      window.removeEventListener("blur", onBlur);
    };
  }, []);
  useEffect(() => {
    if (hidden <= mountFloor) return;
    if (isStreaming && following) return;
    if (following && windowFocused) return;
    let cancelled = false;
    let cancel: (() => void) | null = null;
    const tick = () => {
      if (cancelled) return;
      if (performance.now() - lastUserScrollAtRef.current < SCROLL_QUIET_MS) {
        cancel = scheduleIdleMount(tick);
        return;
      }
      batchStartRef.current = performance.now();
      mountEarlier(batchSizerRef.current.size(), mountFloor);
    };
    cancel = scheduleIdleMount(tick);
    return () => {
      cancelled = true;
      cancel?.();
    };
  }, [hidden, mountFloor, isStreaming, following, windowFocused, mountEarlier]);

  useLayoutEffect(() => {
    // A pending jump wins over batch compensation: the target row just
    // mounted, so center it and re-baseline instead of preserving the old
    // viewport position.
    const pendingJumpKey = pendingJumpKeyRef.current;
    if (pendingJumpKey !== null && centerRow(pendingJumpKey)) {
      pendingJumpKeyRef.current = null;
      expandAnchorRef.current = null;
      batchStartRef.current = null;
      return;
    }
    // Keep the viewport anchored on the previously-visible content after
    // older rows mount above it. While pinned to the tail, snap straight to
    // the bottom instead of delta math so convergence batches can never
    // accumulate sub-pixel drift.
    const anchor = expandAnchorRef.current;
    if (!anchor) return;
    expandAnchorRef.current = null;
    const element = scrollRef.current;
    if (!element) return;
    if (followingRef.current) {
      alignToBottom();
    } else {
      const readingTop = readingAnchorTopRef.current;
      const tail = tailAnchorRef.current;
      element.scrollTop =
        readingTop !== null && tail
          ? element.scrollTop + (tail.getBoundingClientRect().top - readingTop)
          : anchor.prevTop + (element.scrollHeight - anchor.prevHeight);
      programmaticScrollTopRef.current = element.scrollTop;
      scrollMetricsRef.current = {
        top: element.scrollTop,
        height: element.scrollHeight,
      };
    }
    // Reading scrollHeight above forced layout, so this measures the full
    // render + layout cost of the batch that just mounted.
    if (batchStartRef.current !== null) {
      batchSizerRef.current.record(performance.now() - batchStartRef.current);
      batchStartRef.current = null;
    }
  }, [hidden, alignToBottom, centerRow]);

  const lastAssistantRow = [...rows].reverse().find((row) => row.role === "assistant");
  const streamingAssistantKey = findStreamingAssistantKey(
    rows,
    messages,
    session?.isStreaming === true,
  );
  const hasRunningTool = lastAssistantRow?.blocks.some(
    (block) =>
      block.kind === "tool" && (block.tool.status === "running" || block.tool.status === "waiting"),
  );
  const tailRow = rows[rows.length - 1];
  const workingHeaderKey =
    session && !session.isIdle && tailRow?.role === "assistant" ? tailRow.key : undefined;

  useLayoutEffect(() => {
    const remembered = sessionKey !== null ? readTranscriptScrollPosition(sessionKey) : undefined;
    const element = scrollRef.current;
    if (remembered !== undefined && element) {
      // Reopen at the remembered reading position; row layout is unchanged
      // for identical content, so the saved pixel offset stays meaningful.
      updateFollowing(false);
      element.scrollTop = remembered.scrollTop;
      programmaticScrollTopRef.current = element.scrollTop;
      scrollMetricsRef.current = {
        top: element.scrollTop,
        height: element.scrollHeight,
      };
      refreshReadingAnchor();
      return;
    }
    updateFollowing(true);
    alignToBottom();
    scheduleBottomAlignment();
  }, [alignToBottom, refreshReadingAnchor, scheduleBottomAlignment, sessionKey, updateFollowing]);

  useLayoutEffect(() => {
    if (followingRef.current) scheduleBottomAlignment();
  }, [messages, scheduleBottomAlignment]);

  useLayoutEffect(() => {
    const content = contentRef.current;
    if (!content || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      if (followingRef.current) scheduleBottomAlignment();
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, [scheduleBottomAlignment]);

  useEffect(() => cancelScheduledScroll, [cancelScheduledScroll]);

  function scrollToBottom() {
    const element = scrollRef.current;
    if (!element) return;
    updateFollowing(true);
    element.scrollTo({ top: element.scrollHeight, behavior: "smooth" });
  }

  return (
    <div className="relative min-h-0 flex-1">
      <div
        ref={scrollRef}
        data-transcript-scroll
        // The turn rail's gutter: when the rail is visible, reserve 36px
        // (8px gap + ~20px rail + 8px gap) on the right so right-aligned user
        // bubbles never extend underneath it and the rail sits centered
        // between the content edge and the native scrollbar.
        className={`scrollbar-subtle h-full overflow-y-auto px-3 py-4 sm:px-6 sm:py-5 ${
          railVisible ? "pr-9 sm:pr-9" : ""
        }`}
        onWheel={(event) => {
          lastUserScrollAtRef.current = performance.now();
          if (event.deltaY < 0) stopFollowing();
        }}
        onScroll={(event) => {
          const element = event.currentTarget;
          // Genuine user scrolls move the reading anchor; echoes of our own
          // compensation (within a pixel of the last programmatic value)
          // must not, or batch corrections would re-baseline onto their own
          // quantization error and drift.
          const programmaticTop = programmaticScrollTopRef.current;
          programmaticScrollTopRef.current = null;
          if (programmaticTop === null || Math.abs(element.scrollTop - programmaticTop) >= 1) {
            lastUserScrollAtRef.current = performance.now();
            refreshReadingAnchor();
          }
          // Near-edge boost: mount the next batch synchronously when the
          // reader approaches the top of the mounted region, so fast upward
          // scrolling never has to wait for the idle loop.
          if (
            hidden > mountFloor &&
            element.scrollTop < element.clientHeight * NEAR_TOP_BOOST_VIEWPORTS
          ) {
            batchStartRef.current = performance.now();
            mountEarlier(batchSizerRef.current.size(), mountFloor);
          }
          const previous = scrollMetricsRef.current;
          const movingUp =
            element.scrollTop < previous.top && element.scrollHeight >= previous.height;
          scrollMetricsRef.current = {
            top: element.scrollTop,
            height: element.scrollHeight,
          };
          if (movingUp) {
            stopFollowing();
            return;
          }
          const distance = element.scrollHeight - element.scrollTop - element.clientHeight;
          const shouldFollow = distance < 80;
          if (!shouldFollow && scrollFrameRef.current !== null) {
            cancelScheduledScroll();
          }
          updateFollowing(shouldFollow);
        }}
      >
        <div
          ref={contentRef}
          data-transcript-content
          className="conversation-content-width mx-auto flex flex-col gap-5 sm:gap-6"
        >
          {hidden > 0 && (
            <button
              type="button"
              onClick={() => mountEarlier(SHOW_EARLIER_CHUNK)}
              className="mx-auto flex h-8 items-center rounded-full border border-border bg-surface-raised px-4 text-xs text-muted transition-colors hover:bg-surface-overlay hover:text-foreground"
            >
              {t("transcriptShowEarlier", { count: hidden })}
            </button>
          )}
          {visibleRows.map((row) => {
            const streaming = row.key === streamingAssistantKey;
            const retryableTurn = retryableTurns.get(row.key);
            const retryVisible = Boolean(
              retryableTurn && !suppressedKeys.has(retryableTurn.assistantKey),
            );
            const branchPoint =
              row.role === "user"
                ? row.sourceId
                  ? branchPoints.get(row.sourceId)
                  : undefined
                : row.sourceEndId
                  ? branchPoints.get(row.sourceEndId)
                  : undefined;
            const branchNavigator = branchPoint ? (
              <BranchNavigator
                point={branchPoint}
                disabled={branchBusy || navigatingBranch !== null}
                pending={navigatingBranch === (row.sourceId ?? row.sourceEndId)}
                onSelect={onBranchSelect}
              />
            ) : undefined;
            return (
              <div
                className="transcript-row"
                data-row-key={row.key}
                key={`${session?.sessionId ?? "session"}:${row.key}`}
                onContextMenu={(event) => {
                  if (shouldKeepNativeContextMenu(event.nativeEvent)) return;
                  event.preventDefault();
                  event.stopPropagation();
                  const selection = window.getSelection();
                  const selectedText = selection?.toString() ?? "";
                  const selectionInside = Boolean(
                    selectedText &&
                    selection?.rangeCount &&
                    selection.getRangeAt(0).intersectsNode(event.currentTarget),
                  );
                  const anchor =
                    event.target instanceof Element
                      ? event.target.closest<HTMLAnchorElement>("a[href]")
                      : null;
                  const linkUrl = anchor && isSafeExternalUrl(anchor.href) ? anchor.href : null;
                  openContextMenu({
                    x: event.clientX,
                    y: event.clientY,
                    trigger: contextMenuTrigger(event.target),
                    items: [
                      ...(linkUrl
                        ? [
                            {
                              id: "transcript.openLinkInDock",
                              label: t("menuOpenLinkInDock"),
                              icon: PanelRightOpen,
                              onSelect: () => {
                                requestDockBrowser({ url: linkUrl });
                              },
                            },
                            {
                              id: "transcript.openLinkExternal",
                              label: t("menuOpenLinkExternal"),
                              icon: ExternalLink,
                              onSelect: () => openSystemUrl(linkUrl),
                            },
                            {
                              id: "transcript.copyLink",
                              label: t("menuCopyLink"),
                              icon: Link2,
                              onSelect: () => navigator.clipboard.writeText(linkUrl),
                            },
                          ]
                        : []),
                      ...(selectionInside
                        ? [
                            {
                              id: "transcript.copySelection",
                              label: t("menuCopySelection"),
                              icon: Copy,
                              separatorBefore: Boolean(linkUrl),
                              onSelect: () => navigator.clipboard.writeText(selectedText),
                            },
                          ]
                        : []),
                      {
                        id: "transcript.copyMessage",
                        label: t("menuCopyMessage"),
                        icon: Copy,
                        separatorBefore: linkUrl ? !selectionInside : selectionInside,
                        disabled: !row.copyText,
                        onSelect: () => navigator.clipboard.writeText(row.copyText),
                      },
                    ],
                  });
                }}
              >
                <TranscriptRowView
                  row={row}
                  mode={streaming ? "streaming" : "static"}
                  showCaret={Boolean(streaming)}
                  working={row.key === workingHeaderKey}
                  workingLabel={row.key === workingHeaderKey ? workingLabel : undefined}
                  retryableTurn={retryableTurn}
                  retryVisible={retryVisible}
                  goOnVisible={row.key === lastFailedAssistantKey}
                  onRetry={handleRetry}
                  navigator={branchNavigator}
                />
              </div>
            );
          })}
          {session &&
            !session.isIdle &&
            !workingHeaderKey &&
            !streamingAssistantKey &&
            !hasRunningTool && (
              <div className="flex items-center gap-3 text-xs text-muted">
                <AssistantAvatar />
                <span>{workingLabel}</span>
              </div>
            )}
          <div ref={tailAnchorRef} className="h-1" aria-hidden="true" />
        </div>
      </div>
      {!following && (
        <button
          type="button"
          onClick={scrollToBottom}
          className="absolute bottom-3 left-1/2 flex size-8 -translate-x-1/2 items-center justify-center rounded-full border border-border bg-surface-raised text-muted shadow-md transition-colors hover:bg-surface-overlay hover:text-foreground"
          title={t("transcriptJumpLatest")}
          aria-label={t("transcriptJumpLatest")}
        >
          <ArrowDown size={15} />
        </button>
      )}
      <TurnJumpRail stops={railStops} onJump={onRailJump} viewport={scrollRef} />
    </div>
  );
}

function AssistantAvatar() {
  return <PiMark className="mt-0.5 size-7" />;
}

export function DurationLabel({
  startedAt,
  endedAt,
  active = false,
  className = "",
  decodeMs,
  decodeTokens,
  ttftMs,
  ttftSteps,
}: {
  startedAt?: number;
  endedAt?: number;
  active?: boolean;
  className?: string;
  /** Live-measured per-turn decode/ttft aggregates; a dialog row when known. */
  decodeMs?: number;
  decodeTokens?: number;
  ttftMs?: number;
  ttftSteps?: number;
}) {
  const t = useT();
  const [now, setNow] = useState(() => Date.now());
  const live = active || endedAt === undefined;
  const [open, setOpen] = useState(false);
  const anchorRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (!startedAt || !live) return;
    const timer = window.setInterval(() => setNow(Date.now()), 100);
    return () => window.clearInterval(timer);
  }, [startedAt, live]);

  if (!startedAt) return null;
  const duration = formatDuration(startedAt, active ? now : (endedAt ?? now));
  const tps =
    decodeMs !== undefined && decodeMs > 0 && decodeTokens !== undefined
      ? decodeTokens / (decodeMs / 1_000)
      : null;
  const ttft =
    ttftSteps !== undefined && ttftSteps > 0 && ttftMs !== undefined ? ttftMs / ttftSteps : null;
  const hasDialog = tps !== null || ttft !== null;
  const label = (
    <span className={`tabular-nums text-[10px] text-muted ${className}`}>{duration}</span>
  );
  if (!hasDialog) return label;
  return (
    <span ref={anchorRef} className="relative">
      <button
        type="button"
        className="rounded transition-colors hover:text-foreground"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={t("turnTimeTitle")}
        onClick={() => setOpen((current) => !current)}
      >
        {label}
      </button>
      <TurnDialog
        open={open}
        onClose={() => setOpen(false)}
        anchorRef={anchorRef}
        title={t("turnTimeTitle")}
      >
        <div className="grid grid-cols-[1fr_auto] gap-x-4 gap-y-0.5">
          <span className="text-muted">{t("turnTimeDuration")}</span>
          <span className="tabular-nums">{duration}</span>
          {tps !== null && (
            <>
              <span className="text-muted">{t("turnUsageSpeed")}</span>
              <span className="tabular-nums">
                {t("statsTokensPerSecond", { tps: Math.round(tps) })}
              </span>
            </>
          )}
          {ttft !== null && (
            <>
              <span className="text-muted">{t("statsDialogTtft")}</span>
              <span className="tabular-nums">{formatDuration(ttft)}</span>
            </>
          )}
        </div>
      </TurnDialog>
    </span>
  );
}

// Memoized: with reuseStableRows keeping row references stable, only the
// actively streaming row re-renders per animation frame.
export const TranscriptRowView = memo(function TranscriptRowView({
  row,
  mode,
  showCaret,
  working,
  workingLabel,
  retryableTurn,
  retryVisible,
  goOnVisible,
  onRetry,
  navigator,
  readOnly = false,
  userCollapsible = false,
  userExpanded = false,
  onToggleUser,
  turnFold = true,
}: {
  row: TranscriptRow;
  mode: "streaming" | "static";
  showCaret: boolean;
  working: boolean;
  workingLabel?: string;
  retryableTurn?: RetryableTurn;
  retryVisible: boolean;
  goOnVisible: boolean;
  onRetry: (row: TranscriptRow) => Promise<void>;
  /** Inline branch switcher when the row has sibling alternatives. */
  navigator?: ReactNode;
  readOnly?: boolean;
  userCollapsible?: boolean;
  userExpanded?: boolean;
  onToggleUser?: () => void;
  /**
   * Turn fold: when false the settled turn renders its process in streaming
   * order without the "N tool calls · M messages" summary. Surfaces that own
   * their own process fold (the subagents panel) turn this off so the
   * process is not folded twice.
   */
  turnFold?: boolean;
}) {
  const t = useT();
  if (row.role === "user") {
    const images = row.blocks.filter(
      (block): block is Extract<TranscriptBlock, { kind: "image" }> => block.kind === "image",
    );
    const parsed = parseUserAttachments(row.copyText);
    const collapsed = userCollapsible && !userExpanded;
    if (collapsed) {
      const summary = (parsed.text || row.copyText || "").trim().split(/\r?\n/, 1)[0] ?? "";
      return (
        <div className="group relative ml-auto w-fit max-w-[92%] sm:max-w-[78%]">
          <div className="theme-user-message rounded-xl rounded-br-md bg-surface-overlay px-3.5 py-2.5 text-sm leading-6">
            <div className="line-clamp-3 max-w-full whitespace-pre-wrap break-words">{summary}</div>
            {onToggleUser && (
              <button
                type="button"
                className="mt-1 ml-auto flex h-6 items-center gap-1 text-[10px] text-muted hover:text-foreground"
                title={t("transcriptExpandMessage")}
                aria-label={t("transcriptExpandMessage")}
                onClick={onToggleUser}
              >
                <ChevronDown size={12} />
                {t("transcriptExpandMessage")}
              </button>
            )}
          </div>
          {navigator && <div className="mt-1 flex justify-end">{navigator}</div>}
        </div>
      );
    }
    return (
      <div className="group relative ml-auto w-fit max-w-[92%] sm:max-w-[78%]">
        {images.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {images.map((image, index) => (
              <img
                key={`img:${index}`}
                src={`data:${image.mimeType};base64,${image.data}`}
                alt={t("transcriptAttachmentAlt")}
                className="max-h-48 max-w-full rounded-lg border border-border object-contain"
              />
            ))}
          </div>
        )}
        {parsed.files.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {parsed.files.map((file, index) => (
              <details
                key={`file:${index}`}
                className="max-w-full rounded-md border border-border bg-surface text-xs"
              >
                <summary className="flex h-7 cursor-pointer list-none items-center gap-1.5 px-2 text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
                  <FileText size={12} className="shrink-0" />
                  <span className="max-w-48 truncate">{file.name}</span>
                </summary>
                <pre className="max-h-64 overflow-auto whitespace-pre-wrap break-words border-t border-border px-2 py-1.5 text-[11px] leading-5">
                  {file.pathOnly ? (file.path ?? "") : file.content}
                </pre>
              </details>
            ))}
          </div>
        )}
        {parsed.documents.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {parsed.documents.map((document) => (
              <div
                key={document.id}
                className="flex h-8 max-w-full items-center gap-1.5 rounded-md border border-border bg-surface px-2 text-xs"
                title={document.name}
              >
                <FileText size={12} className="shrink-0 text-accent" />
                <span className="max-w-48 truncate">{document.name}</span>
                <span className="shrink-0 text-[10px] text-muted">
                  {document.unit === "page"
                    ? t("composerDocumentPages", { count: document.unitCount })
                    : t("composerDocumentChunks", { count: document.unitCount })}
                </span>
              </div>
            ))}
          </div>
        )}
        {parsed.text && (
          <div className="theme-user-message whitespace-pre-wrap break-words rounded-xl rounded-br-md bg-surface-overlay px-3.5 py-2.5 text-sm leading-6">
            {parsed.text}
          </div>
        )}
        <div className="mt-1 flex h-7 items-center justify-end gap-2">
          {navigator}
          {userCollapsible && userExpanded && onToggleUser && (
            <button
              type="button"
              className="ml-auto flex h-6 items-center gap-1 text-[10px] text-muted hover:text-foreground"
              title={t("transcriptCollapseMessage")}
              aria-label={t("transcriptCollapseMessage")}
              onClick={onToggleUser}
            >
              <ChevronUp size={12} />
              {t("transcriptCollapseMessage")}
            </button>
          )}
          {!readOnly && retryVisible && retryableTurn && (
            <RetryMessageButton
              className="opacity-0 group-hover:opacity-100"
              onClick={() => onRetry(row)}
            />
          )}
          <CopyMessageButton
            text={stripAttachmentReferenceBlocks(row.copyText)}
            className="opacity-0 group-hover:opacity-100"
          />
        </div>
      </div>
    );
  }

  if (row.role === "error") {
    return (
      <div className="flex items-start gap-3">
        <CircleAlert className="mt-1 size-5 shrink-0 text-danger" />
        <div className="min-w-0 flex-1 whitespace-pre-wrap break-words rounded-md border border-danger/25 bg-danger/10 px-3 py-2 text-sm text-danger">
          {row.copyText}
        </div>
      </div>
    );
  }

  if (row.role === "custom") return <ExtensionMessageRow row={row} />;
  if (row.role === "bash") return <BashExecutionRow row={row} />;
  if (row.role === "summary") return <SummaryRow row={row} />;
  if (row.role === "event") return <SessionEventRow row={row} />;

  const sections = row.sections ?? {
    ordered: row.blocks,
    initialThinking: [],
    intro: [],
    activity: row.blocks,
    final: [],
    stepCount: row.blocks.filter((block) => block.kind === "tool").length,
  };
  const lastTextBlock = [...row.blocks]
    .reverse()
    .find((block): block is Extract<TranscriptBlock, { kind: "text" }> => block.kind === "text");

  // DSH-style turn fold: once the turn settles, its whole process — every
  // intermediate message, thinking block and tool call — collapses into one
  // summary row ("N tool calls · M messages") and only the final result
  // message stays visible. While the turn is running (or the process adds
  // nothing beyond the final message) everything renders in streaming order.
  const finalBlocks: TranscriptBlock[] = sections.final.filter(
    (block) => block.kind !== "thinking",
  );
  const canFold =
    turnFold && !working && sections.stepCount > 0 && sections.ordered.length > finalBlocks.length;
  const foldBlocks = canFold
    ? sections.ordered.filter((block) => !finalBlocks.includes(block))
    : [];
  const foldToolCount = foldBlocks.filter(
    (block) => block.kind === "tool" || block.kind === "extension",
  ).length;
  const foldMessageCount = foldBlocks.filter((block) => block.kind === "text").length;

  return (
    <div className="group/assistant relative w-full">
      <div className="flex h-7 items-center gap-2">
        <AssistantAvatar />
        {working && (
          <span className="text-[11px] text-muted">{workingLabel ?? t("transcriptPiWorking")}</span>
        )}
      </div>
      <div className="mt-2 min-w-0 space-y-3">
        {canFold ? (
          <>
            <TurnProcessFold
              blocks={foldBlocks}
              toolCount={foldToolCount}
              messageCount={foldMessageCount}
            />
            {finalBlocks.map((block, index) => (
              <AssistantBlock
                key={`turn-fold-final:${index}`}
                block={block}
                mode="static"
                showCaret={false}
              />
            ))}
          </>
        ) : (
          <AssistantOrderedContent
            blocks={sections.ordered}
            mode={mode}
            showCaret={showCaret}
            lastTextBlock={lastTextBlock}
            turnActive={working}
          />
        )}
        {row.outcome && (row.outcome.status === "error" || row.outcome.status === "aborted") && (
          <AssistantOutcome outcome={row.outcome} showGoOn={goOnVisible} />
        )}
      </div>
      <div className="mt-2 flex h-7 items-center gap-2">
        <DurationLabel
          startedAt={row.startedAt}
          endedAt={row.endedAt}
          active={working}
          decodeMs={row.decodeMs}
          decodeTokens={row.decodeTokens}
          ttftMs={row.ttftMs}
          ttftSteps={row.ttftSteps}
        />
        {navigator}
        <div className="ml-auto flex items-center gap-1">
          {!readOnly && !working && row.sourceEndId && (
            <ForkFromTurnButton
              entryId={row.sourceEndId}
              className="opacity-0 group-hover/assistant:opacity-100"
            />
          )}
          <CopyMessageButton
            text={row.copyText}
            className="opacity-0 group-hover/assistant:opacity-100"
          />
          <UsageLabel
            usage={row.usage}
            models={row.models}
            startedAt={row.startedAt}
            endedAt={row.endedAt}
            decodeMs={row.decodeMs}
            decodeTokens={row.decodeTokens}
          />
        </div>
      </div>
    </div>
  );
});

/** Fork the conversation keeping history through this assistant turn. */
function ForkFromTurnButton({ entryId, className = "" }: { entryId: string; className?: string }) {
  const t = useT();
  const idle = useAppStore((s) => s.session?.isIdle ?? false);
  const [pending, setPending] = useState(false);
  return (
    <button
      type="button"
      title={t("transcriptForkHere")}
      aria-label={t("transcriptForkHere")}
      disabled={!idle || pending}
      className={`flex size-6 items-center justify-center rounded text-muted transition-opacity hover:bg-surface-overlay hover:text-foreground disabled:opacity-40 ${className}`}
      onClick={() => {
        setPending(true);
        void requestFork(entryId, { position: "at" }).finally(() => setPending(false));
      }}
    >
      {pending ? <LoaderCircle size={13} className="animate-spin" /> : <GitFork size={13} />}
    </button>
  );
}

/**
 * Re-send a failed user message. Hidden while the retry is in flight; the
 * button (and the failed bubble) disappear once the re-prompt is accepted.
 */
function RetryMessageButton({
  onClick,
  className = "",
}: {
  onClick: () => Promise<void>;
  className?: string;
}) {
  const t = useT();
  const [pending, setPending] = useState(false);
  if (pending) return null;
  return (
    <button
      type="button"
      title={t("transcriptRetryMessage")}
      aria-label={t("transcriptRetryMessage")}
      className={`flex size-6 items-center justify-center rounded text-muted transition-opacity hover:bg-surface-overlay hover:text-foreground ${className}`}
      onClick={() => {
        setPending(true);
        void (async () => {
          try {
            await onClick();
          } finally {
            setPending(false);
          }
        })();
      }}
    >
      <RotateCcw size={13} />
    </button>
  );
}

/**
 * Keep assistant content in the order emitted by Pi. Reasoning and tool calls
 * are grouped only while they are adjacent, so a provider's text/thinking/tool
 * interleaving remains visible instead of being reclassified by position.
 */
export function AssistantOrderedContent({
  blocks,
  mode,
  showCaret,
  lastTextBlock,
  turnActive,
}: {
  blocks: TranscriptBlock[];
  mode: "streaming" | "static";
  showCaret: boolean;
  lastTextBlock?: Extract<TranscriptBlock, { kind: "text" }>;
  turnActive: boolean;
}) {
  const t = useT();
  const content: ReactNode[] = [];
  let workBlocks: TranscriptBlock[] = [];
  let workIndex = 0;

  const flushWork = (traceActive = false) => {
    if (workBlocks.length === 0) return;
    const hasActivity = workBlocks.some(
      (block) => block.kind === "tool" || block.kind === "extension",
    );
    if (hasActivity) {
      content.push(
        <ExecutionTrace
          key={`ordered-trace:${workIndex}`}
          blocks={workBlocks}
          stepCount={
            workBlocks.filter((block) => block.kind === "tool" || block.kind === "extension").length
          }
          mode={mode}
          showCaret={showCaret}
          lastTextBlock={lastTextBlock}
          turnActive={traceActive}
        />,
      );
    } else {
      workBlocks.forEach((block, index) => {
        if (block.kind === "thinking") {
          // A thought only counts as live while it is the block still
          // producing tokens in the trailing group; the moment reasoning
          // stops (its own `thinking_end`) the disclosure folds itself.
          const live = thinkingBlockIsLive(
            block,
            index === workBlocks.length - 1,
            traceActive && mode === "streaming",
          );
          content.push(
            <ThinkingBlock
              key={`ordered-thinking:${workIndex}:${index}`}
              content={block.text}
              label={t("transcriptThoughtProcess")}
              defaultOpen={live}
              streaming={live}
              ended={!live}
            />,
          );
        } else {
          content.push(
            <AssistantBlock
              key={`ordered-work:${workIndex}:${index}`}
              block={block}
              mode={mode}
              showCaret={false}
            />,
          );
        }
      });
    }
    workBlocks = [];
    workIndex += 1;
  };

  blocks.forEach((block, index) => {
    if (block.kind === "thinking" || block.kind === "tool" || block.kind === "extension") {
      workBlocks.push(block);
      return;
    }
    flushWork();
    content.push(
      <AssistantBlock
        key={`ordered-block:${index}`}
        block={block}
        mode={mode}
        showCaret={showCaret && block === lastTextBlock}
      />,
    );
  });
  // Only the trailing trace can receive more adjacent tool calls. Earlier
  // trace groups are final even while the broader assistant turn is active.
  flushWork(turnActive);

  return <>{content}</>;
}

