}

/**
 * Rows mounted synchronously when a session opens; the idle loop in
 * progressive-mount.ts converges the rest afterwards.
 */
const INITIAL_VISIBLE_ROWS = 60;
const SHOW_EARLIER_CHUNK = 120;
/** Rows mounted above a jump target for reading context. */
const JUMP_CONTEXT_ROWS = 3;

/** Reopen a session at its remembered reading position, else at the tail. */
function initialHiddenFor(sessionId: string | null, rowCount: number): number {
  const tailHidden = Math.max(0, rowCount - INITIAL_VISIBLE_ROWS);
  if (sessionId === null) return tailHidden;
  const remembered = readTranscriptScrollPosition(sessionId);
  if (remembered === undefined) return tailHidden;
  return Math.min(remembered.hidden, Math.max(0, rowCount - 1));
}

export function Transcript() {
  const t = useT();
  const locale = useLocale();
  const session = useAppStore((state) => state.session);
  const providerNames = useAppStore((state) => state.providerNames);
  const messages = useMemo(() => session?.messages ?? [], [session?.messages]);
  // The "Pi 正在处理…" placeholder shows a playful random status per request.
  // A status is picked when a working phase begins and kept until the session
  // goes idle again. A phase begins when the session flips from idle, when the
  // session changes while working, or when this component first mounts into an
  // already-working session — a fresh conversation only mounts the Transcript
  // after its first message is already in flight (see ChatPage), so the
  // idle->working flip is never observed there. Render-phase setState (the
  // same pattern as hiddenState below) avoids a one-frame flash of the static
  // fallback on the first working frame.
  const isWorking = session?.isIdle === false;
  const [workingText, setWorkingText] = useState<string | null>(null);
  const workingPhaseRef = useRef<string | null>(null);
  const workingPhaseKey = session ? `${session.sessionId}:${locale}` : null;
  if (isWorking && workingPhaseKey !== workingPhaseRef.current) {
    const variants = piWorkingVariants(locale);
    setWorkingText(variants[Math.floor(Math.random() * variants.length)] ?? null);
    workingPhaseRef.current = workingPhaseKey;
  } else if (!isWorking && workingText !== null) {
    setWorkingText(null);
    workingPhaseRef.current = null;
  }
  const workingLabel = workingText ?? t("transcriptPiWorking");
  const prevRowsRef = useRef<TranscriptRow[] | null>(null);
  const rows = useMemo(
    () =>
      reuseStableRows(
        prevRowsRef.current,
        buildTranscriptRows(messages, {
          entries: session?.entries,
          leafId: session?.leafId,
          extensionMessageRenders: session?.extensionMessageRenders,
          turnActive: session?.isIdle === false,
          providerNames,
        }),
      ),
    [
      messages,
      session?.entries,
      session?.leafId,
      session?.extensionMessageRenders,
      session?.isIdle,
      providerNames,
    ],
  );
  prevRowsRef.current = rows;
  const sessionKey = session?.sessionId ?? null;

  // Rows cleared by a retry stay hidden for the rest of this session view so
  // the re-sent answer does not sit next to the failed one. The suppression
  // is renderer-only — the append-only SDK session still records the failed
  // entry and it reappears when the session is reopened.
  const [suppressedKeys, setSuppressedKeys] = useState<ReadonlySet<string>>(new Set());
  const suppressedSessionRef = useRef<string | null>(null);
  if (suppressedSessionRef.current !== sessionKey) {
    suppressedSessionRef.current = sessionKey;
    if (suppressedKeys.size > 0) setSuppressedKeys(new Set());
  }
  const shownRows =
    suppressedKeys.size === 0 ? rows : rows.filter((row) => !suppressedKeys.has(row.key));
  const retryableTurns = useMemo(
    () => computeRetryableTurns(rows, suppressedKeys),
    [rows, suppressedKeys],
  );
  const lastFailedAssistantKey = useMemo(() => {
    for (let index = shownRows.length - 1; index >= 0; index -= 1) {
      const row = shownRows[index];
      if (
        row.role === "assistant" &&
        (row.outcome?.status === "error" || row.outcome?.status === "aborted")
      ) {
        return row.key;
      }
    }
    return undefined;
  }, [shownRows]);

  // Inline branch navigators: sibling alternatives for the rows on the
  // current leaf path, derived from the shared session tree. User rows look
  // up by `sourceId`; assistant rows by `sourceEndId` — both match the
  // turn-chain last entry id the tree model keys by. The overlay button and
  // Ctrl+T open the full tree (SessionTreeOverlay).
  const tree = useSessionTree();
  const branchPoints = useMemo(() => {
    if (!tree.tree || !tree.leafId) return new Map<string, TreeBranchPoint>();
    return branchAlternatives(tree.tree, tree.leafId);
  }, [tree.tree, tree.leafId]);
  const branchBusy = session ? !session.isIdle : true;
  const [navigatingBranch, setNavigatingBranch] = useState<string | null>(null);
  const onBranchSelect = useCallback(
    (targetId: string) => {
      if (requestTranscriptScroll({ sourceId: targetId })) return;
      setNavigatingBranch(targetId);
      void navigateTreeTo(targetId, t).finally(() => setNavigatingBranch(null));
    },
    [t],
  );

  // Turn jump rail: user message turns for the right-edge quick jump strip —
  // the fast "back to the first / the Nth message" path for long chats.
  const railStops = useMemo(() => turnRailStops(shownRows), [shownRows]);
  const railVisible = railStops.length >= 2;
  const onRailJump = useCallback((sourceId: string) => {
    requestTranscriptScroll({ sourceId });
  }, []);

  const handleRetry = useCallback(
    (row: TranscriptRow): Promise<void> =>
      requestRetry(row).then((accepted) => {
        if (!accepted) return;
        const turn = retryableTurns.get(row.key);
        if (!turn) return;
        setSuppressedKeys((current) => {
          if (current.has(turn.assistantKey)) return current;
          const next = new Set(current);
          next.add(turn.assistantKey);
          next.add(row.key);
          return next;
        });
      }),
    [retryableTurns],
  );

  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const scrollFrameRef = useRef<number | null>(null);
  const scrollMetricsRef = useRef({ top: 0, height: 0 });
  const followingRef = useRef(true);
  const [following, setFollowing] = useState(true);

  // Persistent reading anchor: the tail spacer's viewport position, captured
  // on genuine user scrolls only. Batch compensation always corrects back to
  // this one baseline, so sub-pixel quantization loss cannot accumulate into
  // a slow directional drift across hundreds of batches.
  const tailAnchorRef = useRef<HTMLDivElement>(null);
  const readingAnchorTopRef = useRef<number | null>(null);
  const programmaticScrollTopRef = useRef<number | null>(null);

  const refreshReadingAnchor = useCallback(() => {
    const tail = tailAnchorRef.current;
    readingAnchorTopRef.current = tail ? tail.getBoundingClientRect().top : null;
  }, []);

  const cancelScheduledScroll = useCallback(() => {
    if (scrollFrameRef.current === null) return;
    cancelAnimationFrame(scrollFrameRef.current);
    scrollFrameRef.current = null;
  }, []);

  const alignToBottom = useCallback(() => {
    const element = scrollRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
    programmaticScrollTopRef.current = element.scrollTop;
    scrollMetricsRef.current = {
      top: element.scrollTop,
      height: element.scrollHeight,
    };
  }, []);

  const scheduleBottomAlignment = useCallback(() => {
    cancelScheduledScroll();
    scrollFrameRef.current = requestAnimationFrame(() => {
      scrollFrameRef.current = null;
      if (followingRef.current) alignToBottom();
    });
  }, [alignToBottom, cancelScheduledScroll]);

  const updateFollowing = useCallback((next: boolean) => {
    followingRef.current = next;
    setFollowing((current) => (current === next ? current : next));
  }, []);

  const stopFollowing = useCallback(() => {
    cancelScheduledScroll();
    updateFollowing(false);
    refreshReadingAnchor();
  }, [cancelScheduledScroll, refreshReadingAnchor, updateFollowing]);

  // Top-anchored window: `hidden` rows stay unmounted above the fold. New
  // rows stream in at the tail without disturbing what is on screen.
  // Derived-during-render so a freshly opened long session only mounts its
  // tail on first paint; idle-time batches then converge toward a fully
  // mounted transcript (see progressive-mount.ts).
  const [hiddenState, setHiddenState] = useState<{ sessionId: string | null; hidden: number }>({
    sessionId: sessionKey,
    hidden: initialHiddenFor(sessionKey, shownRows.length),
  });
  if (hiddenState.sessionId !== sessionKey) {
    // Remember (or forget) the departing session's reading position before
    // the window resets. Idempotent, so the render-phase setState pattern
    // stays safe under double-invoked renders.
    if (hiddenState.sessionId !== null) {
      if (followingRef.current) {
        forgetTranscriptScrollPosition(hiddenState.sessionId);
      } else {
        saveTranscriptScrollPosition(hiddenState.sessionId, {
          hidden: hiddenState.hidden,
          scrollTop: scrollMetricsRef.current.top,
        });
      }
    }
    setHiddenState({
      sessionId: sessionKey,
      hidden: initialHiddenFor(sessionKey, shownRows.length),
    });
  }
  const hidden = Math.min(
    hiddenState.sessionId === sessionKey ? hiddenState.hidden : 0,
    Math.max(0, shownRows.length - 1),
  );
  const visibleRows = hidden > 0 ? shownRows.slice(hidden) : shownRows;
  const expandAnchorRef = useRef<{ prevHeight: number; prevTop: number } | null>(null);
  const hiddenRef = useRef(hidden);
  hiddenRef.current = hidden;

  const mountEarlier = useCallback((count: number, floor = 0) => {
    if (hiddenRef.current <= floor) return;
    const element = scrollRef.current;
    if (element) {
      expandAnchorRef.current = {
        prevHeight: element.scrollHeight,
        prevTop: element.scrollTop,
      };
    }
    setHiddenState((current) => ({
      ...current,
      hidden: Math.max(floor, current.hidden - count),
    }));
  }, []);

  // Row-level navigation: outline/find/search request a row through the
  // transcript-navigation bus; unmounted targets mount synchronously first
  // and the centering runs from the layout effect once the row exists.
  const pendingJumpKeyRef = useRef<string | null>(null);

  const centerRow = useCallback(
    (key: string): boolean => {
      const scroller = scrollRef.current;
      if (!scroller) return false;
      const rowElement = scroller.querySelector<HTMLElement>(`[data-row-key="${CSS.escape(key)}"]`);
      if (!rowElement) return false;
      const rowRect = rowElement.getBoundingClientRect();
      const scrollerRect = scroller.getBoundingClientRect();
      scroller.scrollTop +=
        rowRect.top - scrollerRect.top - Math.max(0, (scroller.clientHeight - rowRect.height) / 2);
      programmaticScrollTopRef.current = scroller.scrollTop;
      scrollMetricsRef.current = {
        top: scroller.scrollTop,
        height: scroller.scrollHeight,
      };
      refreshReadingAnchor();
      return true;
    },
    [refreshReadingAnchor],
  );

  const scrollToRowRef = useRef<(request: TranscriptScrollRequest) => boolean>(() => false);
  scrollToRowRef.current = (request) => {
    let key = request.rowKey;
    if (key === undefined && request.sourceId) {
      const match = rows.find(
        (row) => row.sourceId === request.sourceId || row.sourceEndId === request.sourceId,
      );
      key = match?.key;
    }
    if (key === undefined) return false;
    const index = rows.findIndex((row) => row.key === key);
    if (index < 0) return false;
    stopFollowing();
    if (index < hidden) {
      pendingJumpKeyRef.current = key;
      setHiddenState((current) => ({
        ...current,
        hidden: Math.max(0, Math.min(current.hidden, index - JUMP_CONTEXT_ROWS)),
      }));
      return true;
    }
    return centerRow(key);
  };
  useEffect(() => subscribeTranscriptScroll((request) => scrollToRowRef.current(request)), []);

  // Save the reading position when the transcript unmounts (e.g. workspace
  // switches); session switches are handled by the render-phase reset above.
  const sessionKeyRef = useRef(sessionKey);
  sessionKeyRef.current = sessionKey;
  useEffect(
    () => () => {
      const departing = sessionKeyRef.current;
      if (departing === null) return;
      if (followingRef.current) {
        forgetTranscriptScrollPosition(departing);
      } else {
        saveTranscriptScrollPosition(departing, {
          hidden: hiddenRef.current,
          scrollTop: scrollMetricsRef.current.top,
        });
      }
    },
    [],
  );

  // Idle-time convergence toward a fully mounted transcript (bounded by the
  // full-mount cap). Each batch triggers this effect again through `hidden`,
  // which paces the loop one batch per idle slice. Batch size adapts to the
  // measured cost of this session's rows. Convergence only runs when its
  // scroll adjustments cannot be seen: bottom realignment carries sub-pixel
  // rounding wobble, so a focused reader pinned to the tail pauses the loop
  // until they scroll into history (or the window blurs).
  const mountFloor = autoMountFloor(rows.length);
  const isStreaming = session?.isStreaming === true;
  const batchSizerRef = useRef(createBatchSizer());
  const batchStartRef = useRef<number | null>(null);
  const lastUserScrollAtRef = useRef(0);
  const [windowFocused, setWindowFocused] = useState(() => document.hasFocus());
  useEffect(() => {
    const onFocus = () => setWindowFocused(true);
    const onBlur = () => setWindowFocused(false);
    window.addEventListener("focus", onFocus);
    window.addEventListener("blur", onBlur);
    return () => {
      window.removeEventListener("focus", onFocus);
      window.removeEventListener("blur", onBlur);
    };
  }, []);
  useEffect(() => {
    if (hidden <= mountFloor) return;
    if (isStreaming && following) return;
    if (following && windowFocused) return;
    let cancelled = false;
    let cancel: (() => void) | null = null;
    const tick = () => {
      if (cancelled) return;
      if (performance.now() - lastUserScrollAtRef.current < SCROLL_QUIET_MS) {
        cancel = scheduleIdleMount(tick);
        return;
      }
      batchStartRef.current = performance.now();
      mountEarlier(batchSizerRef.current.size(), mountFloor);
    };
    cancel = scheduleIdleMount(tick);
    return () => {
      cancelled = true;
      cancel?.();
    };
  }, [hidden, mountFloor, isStreaming, following, windowFocused, mountEarlier]);

  useLayoutEffect(() => {
    // A pending jump wins over batch compensation: the target row just
    // mounted, so center it and re-baseline instead of preserving the old
    // viewport position.
    const pendingJumpKey = pendingJumpKeyRef.current;
    if (pendingJumpKey !== null && centerRow(pendingJumpKey)) {
      pendingJumpKeyRef.current = null;
      expandAnchorRef.current = null;
      batchStartRef.current = null;
      return;
    }
    // Keep the viewport anchored on the previously-visible content after
    // older rows mount above it. While pinned to the tail, snap straight to
    // the bottom instead of delta math so convergence batches can never
    // accumulate sub-pixel drift.
    const anchor = expandAnchorRef.current;
    if (!anchor) return;
    expandAnchorRef.current = null;
    const element = scrollRef.current;
    if (!element) return;
    if (followingRef.current) {
      alignToBottom();
    } else {
      const readingTop = readingAnchorTopRef.current;
      const tail = tailAnchorRef.current;
      element.scrollTop =
        readingTop !== null && tail
          ? element.scrollTop + (tail.getBoundingClientRect().top - readingTop)
          : anchor.prevTop + (element.scrollHeight - anchor.prevHeight);
      programmaticScrollTopRef.current = element.scrollTop;
      scrollMetricsRef.current = {
        top: element.scrollTop,
        height: element.scrollHeight,
      };
    }
    // Reading scrollHeight above forced layout, so this measures the full
    // render + layout cost of the batch that just mounted.
    if (batchStartRef.current !== null) {
      batchSizerRef.current.record(performance.now() - batchStartRef.current);
      batchStartRef.current = null;
    }
  }, [hidden, alignToBottom, centerRow]);

  const lastAssistantRow = [...rows].reverse().find((row) => row.role === "assistant");
  const streamingAssistantKey = findStreamingAssistantKey(
    rows,
    messages,
    session?.isStreaming === true,
  );
  const hasRunningTool = lastAssistantRow?.blocks.some(
    (block) =>
      block.kind === "tool" && (block.tool.status === "running" || block.tool.status === "waiting"),
  );
  const tailRow = rows[rows.length - 1];
  const workingHeaderKey =
    session && !session.isIdle && tailRow?.role === "assistant" ? tailRow.key : undefined;

  useLayoutEffect(() => {
    const remembered = sessionKey !== null ? readTranscriptScrollPosition(sessionKey) : undefined;
    const element = scrollRef.current;
    if (remembered !== undefined && element) {
      // Reopen at the remembered reading position; row layout is unchanged
      // for identical content, so the saved pixel offset stays meaningful.
      updateFollowing(false);
      element.scrollTop = remembered.scrollTop;
      programmaticScrollTopRef.current = element.scrollTop;
      scrollMetricsRef.current = {
        top: element.scrollTop,
        height: element.scrollHeight,
      };
      refreshReadingAnchor();
      return;
    }
    updateFollowing(true);
    alignToBottom();
    scheduleBottomAlignment();
  }, [alignToBottom, refreshReadingAnchor, scheduleBottomAlignment, sessionKey, updateFollowing]);

  useLayoutEffect(() => {
    if (followingRef.current) scheduleBottomAlignment();
  }, [messages, scheduleBottomAlignment]);

  useLayoutEffect(() => {
    const content = contentRef.current;
    if (!content || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      if (followingRef.current) scheduleBottomAlignment();
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, [scheduleBottomAlignment]);

  useEffect(() => cancelScheduledScroll, [cancelScheduledScroll]);

  function scrollToBottom() {
    const element = scrollRef.current;
    if (!element) return;
    updateFollowing(true);
    element.scrollTo({ top: element.scrollHeight, behavior: "smooth" });
  }

  return (
    <div className="relative min-h-0 flex-1">
      <div
        ref={scrollRef}
        data-transcript-scroll
        // The turn rail's gutter: when the rail is visible, reserve 36px
        // (8px gap + ~20px rail + 8px gap) on the right so right-aligned user
        // bubbles never extend underneath it and the rail sits centered
        // between the content edge and the native scrollbar.
        className={`scrollbar-subtle h-full overflow-y-auto px-3 py-4 sm:px-6 sm:py-5 ${
          railVisible ? "pr-9 sm:pr-9" : ""
        }`}
        onWheel={(event) => {
          lastUserScrollAtRef.current = performance.now();
          if (event.deltaY < 0) stopFollowing();
        }}
        onScroll={(event) => {
          const element = event.currentTarget;
          // Genuine user scrolls move the reading anchor; echoes of our own
          // compensation (within a pixel of the last programmatic value)
          // must not, or batch corrections would re-baseline onto their own
          // quantization error and drift.
          const programmaticTop = programmaticScrollTopRef.current;
          programmaticScrollTopRef.current = null;
          if (programmaticTop === null || Math.abs(element.scrollTop - programmaticTop) >= 1) {
            lastUserScrollAtRef.current = performance.now();
            refreshReadingAnchor();
          }
          // Near-edge boost: mount the next batch synchronously when the
          // reader approaches the top of the mounted region, so fast upward
          // scrolling never has to wait for the idle loop.
          if (
            hidden > mountFloor &&
            element.scrollTop < element.clientHeight * NEAR_TOP_BOOST_VIEWPORTS
          ) {
            batchStartRef.current = performance.now();
            mountEarlier(batchSizerRef.current.size(), mountFloor);
          }
          const previous = scrollMetricsRef.current;
          const movingUp =
            element.scrollTop < previous.top && element.scrollHeight >= previous.height;
          scrollMetricsRef.current = {
            top: element.scrollTop,
            height: element.scrollHeight,
          };
          if (movingUp) {
            stopFollowing();
            return;
          }
          const distance = element.scrollHeight - element.scrollTop - element.clientHeight;
          const shouldFollow = distance < 80;
          if (!shouldFollow && scrollFrameRef.current !== null) {
            cancelScheduledScroll();
          }
          updateFollowing(shouldFollow);
        }}
      >
        <div
          ref={contentRef}
          data-transcript-content
          className="conversation-content-width mx-auto flex flex-col gap-5 sm:gap-6"
        >
          {hidden > 0 && (
            <button
              type="button"
              onClick={() => mountEarlier(SHOW_EARLIER_CHUNK)}
              className="mx-auto flex h-8 items-center rounded-full border border-border bg-surface-raised px-4 text-xs text-muted transition-colors hover:bg-surface-overlay hover:text-foreground"
            >
              {t("transcriptShowEarlier", { count: hidden })}
            </button>
          )}
          {visibleRows.map((row) => {
            const streaming = row.key === streamingAssistantKey;
            const retryableTurn = retryableTurns.get(row.key);
            const retryVisible = Boolean(
              retryableTurn && !suppressedKeys.has(retryableTurn.assistantKey),
            );
            const branchPoint =
              row.role === "user"
                ? row.sourceId
                  ? branchPoints.get(row.sourceId)
                  : undefined
                : row.sourceEndId
                  ? branchPoints.get(row.sourceEndId)
                  : undefined;
            const branchNavigator = branchPoint ? (
              <BranchNavigator
                point={branchPoint}
                disabled={branchBusy || navigatingBranch !== null}
                pending={navigatingBranch === (row.sourceId ?? row.sourceEndId)}
                onSelect={onBranchSelect}
              />
            ) : undefined;
            return (
              <div
                className="transcript-row"
                data-row-key={row.key}
                key={`${session?.sessionId ?? "session"}:${row.key}`}
                onContextMenu={(event) => {
                  if (shouldKeepNativeContextMenu(event.nativeEvent)) return;
                  event.preventDefault();
                  event.stopPropagation();
                  const selection = window.getSelection();
                  const selectedText = selection?.toString() ?? "";
                  const selectionInside = Boolean(
                    selectedText &&
                    selection?.rangeCount &&
                    selection.getRangeAt(0).intersectsNode(event.currentTarget),
                  );
                  const anchor =
                    event.target instanceof Element
                      ? event.target.closest<HTMLAnchorElement>("a[href]")
                      : null;
                  const linkUrl = anchor && isSafeExternalUrl(anchor.href) ? anchor.href : null;
                  openContextMenu({
                    x: event.clientX,
                    y: event.clientY,
                    trigger: contextMenuTrigger(event.target),
                    items: [
                      ...(linkUrl
                        ? [
                            {
                              id: "transcript.openLinkInDock",
                              label: t("menuOpenLinkInDock"),
                              icon: PanelRightOpen,
                              onSelect: () => {
                                requestDockBrowser({ url: linkUrl });
                              },
                            },
                            {
                              id: "transcript.openLinkExternal",
                              label: t("menuOpenLinkExternal"),
                              icon: ExternalLink,
                              onSelect: () => openSystemUrl(linkUrl),
                            },
                            {
                              id: "transcript.copyLink",
                              label: t("menuCopyLink"),
                              icon: Link2,
                              onSelect: () => navigator.clipboard.writeText(linkUrl),
                            },
                          ]
                        : []),
                      ...(selectionInside
                        ? [
                            {
                              id: "transcript.copySelection",
                              label: t("menuCopySelection"),
                              icon: Copy,
                              separatorBefore: Boolean(linkUrl),
                              onSelect: () => navigator.clipboard.writeText(selectedText),
                            },
                          ]
                        : []),
                      {
                        id: "transcript.copyMessage",
                        label: t("menuCopyMessage"),
                        icon: Copy,
                        separatorBefore: linkUrl ? !selectionInside : selectionInside,
                        disabled: !row.copyText,
                        onSelect: () => navigator.clipboard.writeText(row.copyText),
                      },
                    ],
                  });
                }}
              >
                <TranscriptRowView
                  row={row}
                  mode={streaming ? "streaming" : "static"}
                  showCaret={Boolean(streaming)}
                  working={row.key === workingHeaderKey}
                  workingLabel={row.key === workingHeaderKey ? workingLabel : undefined}
                  retryableTurn={retryableTurn}
                  retryVisible={retryVisible}
                  goOnVisible={row.key === lastFailedAssistantKey}
                  onRetry={handleRetry}
                  navigator={branchNavigator}
                />
              </div>
            );
          })}
          {session &&
            !session.isIdle &&
            !workingHeaderKey &&
            !streamingAssistantKey &&
            !hasRunningTool && (
              <div className="flex items-center gap-3 text-xs text-muted">
                <AssistantAvatar />
                <span>{workingLabel}</span>
              </div>
            )}
          <div ref={tailAnchorRef} className="h-1" aria-hidden="true" />
        </div>
      </div>
      {!following && (
        <button
          type="button"
          onClick={scrollToBottom}
          className="absolute bottom-3 left-1/2 flex size-8 -translate-x-1/2 items-center justify-center rounded-full border border-border bg-surface-raised text-muted shadow-md transition-colors hover:bg-surface-overlay hover:text-foreground"
          title={t("transcriptJumpLatest")}
          aria-label={t("transcriptJumpLatest")}
        >
          <ArrowDown size={15} />
        </button>
      )}
      <TurnJumpRail stops={railStops} onJump={onRailJump} viewport={scrollRef} />
    </div>
  );
}

function AssistantAvatar() {
  return <PiMark className="mt-0.5 size-7" />;
}

export function DurationLabel({
  startedAt,
  endedAt,
  active = false,
  className = "",
  decodeMs,
  decodeTokens,
  ttftMs,
  ttftSteps,
}: {
  startedAt?: number;
  endedAt?: number;
  active?: boolean;
  className?: string;
  /** Live-measured per-turn decode/ttft aggregates; a dialog row when known. */
  decodeMs?: number;
  decodeTokens?: number;
  ttftMs?: number;
  ttftSteps?: number;
}) {
  const t = useT();
  const [now, setNow] = useState(() => Date.now());
  const live = active || endedAt === undefined;
  const [open, setOpen] = useState(false);
  const anchorRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (!startedAt || !live) return;
    const timer = window.setInterval(() => setNow(Date.now()), 100);
    return () => window.clearInterval(timer);
  }, [startedAt, live]);

  if (!startedAt) return null;
  const duration = formatDuration(startedAt, active ? now : (endedAt ?? now));
  const tps =
    decodeMs !== undefined && decodeMs > 0 && decodeTokens !== undefined
      ? decodeTokens / (decodeMs / 1_000)
      : null;
  const ttft =
    ttftSteps !== undefined && ttftSteps > 0 && ttftMs !== undefined ? ttftMs / ttftSteps : null;
  const hasDialog = tps !== null || ttft !== null;
  const label = (
    <span className={`tabular-nums text-[10px] text-muted ${className}`}>{duration}</span>
  );
  if (!hasDialog) return label;
  return (
    <span ref={anchorRef} className="relative">
      <button
        type="button"
        className="rounded transition-colors hover:text-foreground"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={t("turnTimeTitle")}
        onClick={() => setOpen((current) => !current)}
      >
        {label}
      </button>
      <TurnDialog
        open={open}
        onClose={() => setOpen(false)}
        anchorRef={anchorRef}
        title={t("turnTimeTitle")}
      >
        <div className="grid grid-cols-[1fr_auto] gap-x-4 gap-y-0.5">
          <span className="text-muted">{t("turnTimeDuration")}</span>
          <span className="tabular-nums">{duration}</span>
          {tps !== null && (
            <>
              <span className="text-muted">{t("turnUsageSpeed")}</span>
              <span className="tabular-nums">
                {t("statsTokensPerSecond", { tps: Math.round(tps) })}
              </span>
            </>
          )}
          {ttft !== null && (
            <>
              <span className="text-muted">{t("statsDialogTtft")}</span>
              <span className="tabular-nums">{formatDuration(ttft)}</span>
            </>
          )}
        </div>
      </TurnDialog>
    </span>
  );
}

// Memoized: with reuseStableRows keeping row references stable, only the
// actively streaming row re-renders per animation frame.
export const TranscriptRowView = memo(function TranscriptRowView({
  row,
  mode,
  showCaret,
  working,
  workingLabel,
  retryableTurn,
  retryVisible,
  goOnVisible,
  onRetry,
  navigator,
  readOnly = false,
  userCollapsible = false,
  userExpanded = false,
  onToggleUser,
  turnFold = true,
}: {
  row: TranscriptRow;
  mode: "streaming" | "static";
  showCaret: boolean;
  working: boolean;
  workingLabel?: string;
  retryableTurn?: RetryableTurn;
  retryVisible: boolean;
  goOnVisible: boolean;
  onRetry: (row: TranscriptRow) => Promise<void>;
  /** Inline branch switcher when the row has sibling alternatives. */
  navigator?: ReactNode;
  readOnly?: boolean;
  userCollapsible?: boolean;
  userExpanded?: boolean;
  onToggleUser?: () => void;
  /**
   * Turn fold: when false the settled turn renders its process in streaming
   * order without the "N tool calls · M messages" summary. Surfaces that own
   * their own process fold (the subagents panel) turn this off so the
   * process is not folded twice.
   */
  turnFold?: boolean;
}) {
  const t = useT();
  if (row.role === "user") {
    const images = row.blocks.filter(
      (block): block is Extract<TranscriptBlock, { kind: "image" }> => block.kind === "image",
    );
    const parsed = parseUserAttachments(row.copyText);
    const collapsed = userCollapsible && !userExpanded;
    if (collapsed) {
      const summary = (parsed.text || row.copyText || "").trim().split(/\r?\n/, 1)[0] ?? "";
      return (
        <div className="group relative ml-auto w-fit max-w-[92%] sm:max-w-[78%]">
          <div className="theme-user-message rounded-xl rounded-br-md bg-surface-overlay px-3.5 py-2.5 text-sm leading-6">
            <div className="line-clamp-3 max-w-full whitespace-pre-wrap break-words">{summary}</div>
            {onToggleUser && (
              <button
                type="button"
                className="mt-1 ml-auto flex h-6 items-center gap-1 text-[10px] text-muted hover:text-foreground"
                title={t("transcriptExpandMessage")}
                aria-label={t("transcriptExpandMessage")}
                onClick={onToggleUser}
              >
                <ChevronDown size={12} />
                {t("transcriptExpandMessage")}
              </button>
            )}
          </div>
          {navigator && <div className="mt-1 flex justify-end">{navigator}</div>}
        </div>
      );
    }
    return (
      <div className="group relative ml-auto w-fit max-w-[92%] sm:max-w-[78%]">
        {images.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {images.map((image, index) => (
              <img
                key={`img:${index}`}
                src={`data:${image.mimeType};base64,${image.data}`}
                alt={t("transcriptAttachmentAlt")}
                className="max-h-48 max-w-full rounded-lg border border-border object-contain"
              />
            ))}
          </div>
        )}
        {parsed.files.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {parsed.files.map((file, index) => (
              <details
                key={`file:${index}`}
                className="max-w-full rounded-md border border-border bg-surface text-xs"
              >
                <summary className="flex h-7 cursor-pointer list-none items-center gap-1.5 px-2 text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
                  <FileText size={12} className="shrink-0" />
                  <span className="max-w-48 truncate">{file.name}</span>
                </summary>
                <pre className="max-h-64 overflow-auto whitespace-pre-wrap break-words border-t border-border px-2 py-1.5 text-[11px] leading-5">
                  {file.pathOnly ? (file.path ?? "") : file.content}
                </pre>
              </details>
            ))}
          </div>
        )}
        {parsed.documents.length > 0 && (
          <div className="mb-1 flex flex-wrap justify-end gap-1.5">
            {parsed.documents.map((document) => (
              <div
                key={document.id}
                className="flex h-8 max-w-full items-center gap-1.5 rounded-md border border-border bg-surface px-2 text-xs"
                title={document.name}
              >
                <FileText size={12} className="shrink-0 text-accent" />
                <span className="max-w-48 truncate">{document.name}</span>
                <span className="shrink-0 text-[10px] text-muted">
                  {document.unit === "page"
                    ? t("composerDocumentPages", { count: document.unitCount })
                    : t("composerDocumentChunks", { count: document.unitCount })}
                </span>
              </div>
            ))}
          </div>
        )}
        {parsed.text && (
          <div className="theme-user-message whitespace-pre-wrap break-words rounded-xl rounded-br-md bg-surface-overlay px-3.5 py-2.5 text-sm leading-6">
            {parsed.text}
          </div>
        )}
        <div className="mt-1 flex h-7 items-center justify-end gap-2">
          {navigator}
          {userCollapsible && userExpanded && onToggleUser && (
            <button
              type="button"
              className="ml-auto flex h-6 items-center gap-1 text-[10px] text-muted hover:text-foreground"
              title={t("transcriptCollapseMessage")}
              aria-label={t("transcriptCollapseMessage")}
              onClick={onToggleUser}
            >
              <ChevronUp size={12} />
              {t("transcriptCollapseMessage")}
            </button>
          )}
          {!readOnly && retryVisible && retryableTurn && (
            <RetryMessageButton
              className="opacity-0 group-hover:opacity-100"
              onClick={() => onRetry(row)}
            />
          )}
          <CopyMessageButton
            text={stripAttachmentReferenceBlocks(row.copyText)}
            className="opacity-0 group-hover:opacity-100"
          />
        </div>
      </div>
    );
  }

  if (row.role === "error") {
    return (
      <div className="flex items-start gap-3">
        <CircleAlert className="mt-1 size-5 shrink-0 text-danger" />
        <div className="min-w-0 flex-1 whitespace-pre-wrap break-words rounded-md border border-danger/25 bg-danger/10 px-3 py-2 text-sm text-danger">
          {row.copyText}
        </div>
      </div>
    );
  }

  if (row.role === "custom") return <ExtensionMessageRow row={row} />;
  if (row.role === "bash") return <BashExecutionRow row={row} />;
  if (row.role === "summary") return <SummaryRow row={row} />;
  if (row.role === "event") return <SessionEventRow row={row} />;

  const sections = row.sections ?? {
    ordered: row.blocks,
    initialThinking: [],
    intro: [],
    activity: row.blocks,
    final: [],
    stepCount: row.blocks.filter((block) => block.kind === "tool").length,
  };
  const lastTextBlock = [...row.blocks]
    .reverse()
    .find((block): block is Extract<TranscriptBlock, { kind: "text" }> => block.kind === "text");

  // DSH-style turn fold: once the turn settles, its whole process — every
  // intermediate message, thinking block and tool call — collapses into one
  // summary row ("N tool calls · M messages") and only the final result
  // message stays visible. While the turn is running (or the process adds
  // nothing beyond the final message) everything renders in streaming order.
  const finalBlocks: TranscriptBlock[] = sections.final.filter(
    (block) => block.kind !== "thinking",
  );
  const canFold =
    turnFold && !working && sections.stepCount > 0 && sections.ordered.length > finalBlocks.length;
  const foldBlocks = canFold
    ? sections.ordered.filter((block) => !finalBlocks.includes(block))
    : [];
  const foldToolCount = foldBlocks.filter(
    (block) => block.kind === "tool" || block.kind === "extension",
  ).length;
  const foldMessageCount = foldBlocks.filter((block) => block.kind === "text").length;

  return (
    <div className="group/assistant relative w-full">
      <div className="flex h-7 items-center gap-2">
        <AssistantAvatar />
        {working && (
          <span className="text-[11px] text-muted">{workingLabel ?? t("transcriptPiWorking")}</span>
        )}
      </div>
      <div className="mt-2 min-w-0 space-y-3">
        {canFold ? (
          <>
            <TurnProcessFold
              blocks={foldBlocks}
              toolCount={foldToolCount}
              messageCount={foldMessageCount}
            />
            {finalBlocks.map((block, index) => (
              <AssistantBlock
                key={`turn-fold-final:${index}`}
                block={block}
                mode="static"
                showCaret={false}
              />
            ))}
          </>
        ) : (
          <AssistantOrderedContent
            blocks={sections.ordered}
            mode={mode}
            showCaret={showCaret}
            lastTextBlock={lastTextBlock}
            turnActive={working}
          />
        )}
        {row.outcome && (row.outcome.status === "error" || row.outcome.status === "aborted") && (
          <AssistantOutcome outcome={row.outcome} showGoOn={goOnVisible} />
        )}
      </div>
      <div className="mt-2 flex h-7 items-center gap-2">
        <DurationLabel
          startedAt={row.startedAt}
          endedAt={row.endedAt}
          active={working}
          decodeMs={row.decodeMs}
          decodeTokens={row.decodeTokens}
          ttftMs={row.ttftMs}
          ttftSteps={row.ttftSteps}
        />
        {navigator}
        <div className="ml-auto flex items-center gap-1">
          {!readOnly && !working && row.sourceEndId && (
            <ForkFromTurnButton
              entryId={row.sourceEndId}
              className="opacity-0 group-hover/assistant:opacity-100"
            />
          )}
          <CopyMessageButton
            text={row.copyText}
            className="opacity-0 group-hover/assistant:opacity-100"
          />
          <UsageLabel
            usage={row.usage}
            models={row.models}
            startedAt={row.startedAt}
            endedAt={row.endedAt}
            decodeMs={row.decodeMs}
            decodeTokens={row.decodeTokens}
          />
        </div>
      </div>
    </div>
  );
});

/** Fork the conversation keeping history through this assistant turn. */
function ForkFromTurnButton({ entryId, className = "" }: { entryId: string; className?: string }) {
  const t = useT();
  const idle = useAppStore((s) => s.session?.isIdle ?? false);
  const [pending, setPending] = useState(false);
  return (
    <button
      type="button"
      title={t("transcriptForkHere")}
      aria-label={t("transcriptForkHere")}
      disabled={!idle || pending}
      className={`flex size-6 items-center justify-center rounded text-muted transition-opacity hover:bg-surface-overlay hover:text-foreground disabled:opacity-40 ${className}`}
      onClick={() => {
        setPending(true);
        void requestFork(entryId, { position: "at" }).finally(() => setPending(false));
      }}
    >
      {pending ? <LoaderCircle size={13} className="animate-spin" /> : <GitFork size={13} />}
    </button>
  );
}

/**
 * Re-send a failed user message. Hidden while the retry is in flight; the
 * button (and the failed bubble) disappear once the re-prompt is accepted.
 */
function RetryMessageButton({
  onClick,
  className = "",
}: {
  onClick: () => Promise<void>;
  className?: string;
}) {
  const t = useT();
  const [pending, setPending] = useState(false);
  if (pending) return null;
  return (
    <button
      type="button"
      title={t("transcriptRetryMessage")}
      aria-label={t("transcriptRetryMessage")}
      className={`flex size-6 items-center justify-center rounded text-muted transition-opacity hover:bg-surface-overlay hover:text-foreground ${className}`}
      onClick={() => {
        setPending(true);
        void (async () => {
          try {
            await onClick();
          } finally {
            setPending(false);
          }
        })();
      }}
    >
      <RotateCcw size={13} />
    </button>
  );
}

/**
 * Keep assistant content in the order emitted by Pi. Reasoning and tool calls
 * are grouped only while they are adjacent, so a provider's text/thinking/tool
 * interleaving remains visible instead of being reclassified by position.
 */
export function AssistantOrderedContent({
  blocks,
  mode,
  showCaret,
  lastTextBlock,
  turnActive,
}: {
  blocks: TranscriptBlock[];
  mode: "streaming" | "static";
  showCaret: boolean;
  lastTextBlock?: Extract<TranscriptBlock, { kind: "text" }>;
  turnActive: boolean;
}) {
  const t = useT();
  const content: ReactNode[] = [];
  let workBlocks: TranscriptBlock[] = [];
  let workIndex = 0;

  const flushWork = (traceActive = false) => {
    if (workBlocks.length === 0) return;
    const hasActivity = workBlocks.some(
      (block) => block.kind === "tool" || block.kind === "extension",
    );
    if (hasActivity) {
      content.push(
        <ExecutionTrace
          key={`ordered-trace:${workIndex}`}
          blocks={workBlocks}
          stepCount={
            workBlocks.filter((block) => block.kind === "tool" || block.kind === "extension").length
          }
          mode={mode}
          showCaret={showCaret}
          lastTextBlock={lastTextBlock}
          turnActive={traceActive}
        />,
      );
    } else {
      workBlocks.forEach((block, index) => {
        if (block.kind === "thinking") {
          // A thought only counts as live while it is the block still
          // producing tokens in the trailing group; the moment reasoning
          // stops (its own `thinking_end`) the disclosure folds itself.
          const live = thinkingBlockIsLive(
            block,
            index === workBlocks.length - 1,
            traceActive && mode === "streaming",
          );
          content.push(
            <ThinkingBlock
              key={`ordered-thinking:${workIndex}:${index}`}
              content={block.text}
              label={t("transcriptThoughtProcess")}
              defaultOpen={live}
              streaming={live}
              ended={!live}
            />,
          );
        } else {
          content.push(
            <AssistantBlock
              key={`ordered-work:${workIndex}:${index}`}
              block={block}
              mode={mode}
              showCaret={false}
            />,
          );
        }
      });
    }
    workBlocks = [];
    workIndex += 1;
  };

  blocks.forEach((block, index) => {
    if (block.kind === "thinking" || block.kind === "tool" || block.kind === "extension") {
      workBlocks.push(block);
      return;
    }
    flushWork();
    content.push(
      <AssistantBlock
        key={`ordered-block:${index}`}
        block={block}
        mode={mode}
        showCaret={showCaret && block === lastTextBlock}
      />,
    );
  });
  // Only the trailing trace can receive more adjacent tool calls. Earlier
  // trace groups are final even while the broader assistant turn is active.
  flushWork(turnActive);

  return <>{content}</>;
}

export function ExecutionTrace({
  blocks,
  stepCount,
  mode,
  showCaret,
  lastTextBlock,
  turnActive,
}: {
  blocks: TranscriptBlock[];
  stepCount: number;
  mode: "streaming" | "static";
  showCaret: boolean;
  lastTextBlock?: Extract<TranscriptBlock, { kind: "text" }>;
  turnActive: boolean;
}) {
  const t = useT();

content.text:
import type {
  AttachmentReference,
  ExtensionMessageRenderSnapshot,
  ExtensionPresentation,
  SerializableAgentContent,
  SerializableAgentMessage,
  SerializableSessionEntry,
  SerializableUsage,
} from "@piabyss/protocol";
import {
  parseAttachmentReferences,
  parseExtensionPresentation,
  stripAttachmentReferenceBlocks,
} from "@piabyss/protocol";
import { isAbortedToolResult } from "../../lib/chat/tool-result-status";
import { withFriendlyErrorHint } from "./error-hints";

export type ToolTraceStatus = "waiting" | "running" | "done" | "error" | "aborted";

export type ToolTrace = {
  id: string;
  name: string;
  args?: unknown;
  result?: unknown;
  resultBlocks?: TranscriptContentBlock[];
  details?: unknown;
  status: ToolTraceStatus;
  startedAt?: number;
  endedAt?: number;
};

export function executionTraceIsActive(
  tools: readonly Pick<ToolTrace, "status">[],
  turnActive: boolean,
): boolean {
  return turnActive || tools.some((tool) => tool.status === "running" || tool.status === "waiting");
}

/**
 * Reasoning is "live" only while it is the block still producing tokens: it
 * belongs to the active (trailing) group and no other block has followed it
 * yet. `endedAt` is stamped by the provider's `thinking_end`, so a thought can
 * fold the instant reasoning stops instead of waiting for the next tool call or
 * answer text to arrive. Providers that never emit `thinking_end` simply fall
 * back to the positional rule: the fold lands as soon as anything else does.
 */
export function thinkingBlockIsLive(
  block: Extract<TranscriptBlock, { kind: "thinking" }>,
  isLastInGroup: boolean,
  groupActive: boolean,
): boolean {
  return groupActive && isLastInGroup && block.endedAt === undefined;
}

export type TranscriptContentBlock =
  | { kind: "text"; text: string }
  | { kind: "thinking"; text: string; startedAt?: number; endedAt?: number }
  | { kind: "image"; data: string; mimeType: string }
  | { kind: "unknown"; type: string; value: unknown };

export type TranscriptBlock =
  | TranscriptContentBlock
  | { kind: "tool"; tool: ToolTrace }
  | { kind: "extension"; row: TranscriptRow };

type AssistantOutcome = {
  status: "streaming" | "complete" | "error" | "aborted";
  stopReason?: string;
  errorMessage?: string;
};

type BashExecution = {
  command: string;
  output: string;
  exitCode?: number;
  cancelled: boolean;
  truncated: boolean;
  fullOutputPath?: string;
  excludeFromContext: boolean;
};

type TranscriptSummary = {
  kind: "compaction" | "branch";
  text: string;
  tokensBefore?: number;
  fromId?: string;
  details?: unknown;
  fromHook?: boolean;
};

type TranscriptEvent = {
  kind: "model" | "thinkingLevel" | "unknown";
  label: string;
  details?: unknown;
};

type AssistantTurnSections = {
  ordered: TranscriptBlock[];
  initialThinking: Extract<TranscriptBlock, { kind: "thinking" }>[];
  intro: TranscriptBlock[];
  activity: TranscriptBlock[];
  final: TranscriptBlock[];
  stepCount: number;
};

export type TranscriptRow = {
  key: string;
  role: "user" | "assistant" | "error" | "custom" | "bash" | "summary" | "event";
  blocks: TranscriptBlock[];
  copyText: string;
  sections?: AssistantTurnSections;
  outcome?: AssistantOutcome;
  customType?: string;
  extensionPresentation?: ExtensionPresentation;
  extensionMessageRender?: ExtensionMessageRenderSnapshot;
  display?: boolean;
  details?: unknown;
  bash?: BashExecution;
  summary?: TranscriptSummary;
  event?: TranscriptEvent;
  sourceId?: string;
  /** Last persisted entry id contributing to the row — an assistant turn can
   * merge several session entries; forking "at" the turn targets this one. */
  sourceEndId?: string;
  timestamp?: number;
  startedAt?: number;
  endedAt?: number;
  usage?: SerializableUsage;
  /** Unique `provider/model` labels of the assistant messages in this turn. */
  models?: string[];
  /** Live-measured first-delta latency sum over streamed messages (ms). */
  ttftMs?: number;
  /** Streamed messages carrying a first-delta timestamp. */
  ttftSteps?: number;
  /** Live-measured decode wall time over streamed messages with output (ms). */
  decodeMs?: number;
  /** Output tokens over the same live-measured messages. */
  decodeTokens?: number;
};

export type BuildTranscriptOptions = {
  entries?: readonly SerializableSessionEntry[];
  leafId?: string | null;
  extensionMessageRenders?: Readonly<Record<string, ExtensionMessageRenderSnapshot>>;
  /** Authoritative Host state used to settle tool calls left open by an interrupted run. */
  turnActive?: boolean;
  /** Provider id -> display name used to render historical `model_change` rows
   *  with the Provider name instead of its raw service id. */
  providerNames?: ReadonlyMap<string, string>;
};

export function findStreamingAssistantKey(
  rows: readonly TranscriptRow[],
  messages: readonly SerializableAgentMessage[],
  isStreaming: boolean,
): string | undefined {
  if (!isStreaming) return undefined;
  const tailRow = rows[rows.length - 1];
  if (tailRow?.role !== "assistant") return undefined;

  const lastMessage = messages[messages.length - 1];
  if (
    !lastMessage ||
    lastMessage.role !== "assistant" ||
    numberField(lastMessage, "endedAt") !== undefined
  ) {
    return undefined;
  }

  // Pi provider partials can carry stopReason="stop" from message_start.
  // Runtime timing, not stopReason, distinguishes an open partial here.
  return tailRow.key;
}

type WorkingTranscriptRow = TranscriptRow & {
  rounds?: TranscriptBlock[][];
};

type ToolResultRecord = {
  id: string;
  name: string;
  result?: unknown;
  resultBlocks: TranscriptContentBlock[];
  details?: unknown;
  isError: boolean;
  aborted: boolean;
};

type MessageSource = {
  kind: "message";
  message: SerializableAgentMessage;
  key: string;
  sourceId?: string;
  timestamp?: number;
  extensionMessageRender?: ExtensionMessageRenderSnapshot;
};

type RowSource = {
  kind: "row";
  row: TranscriptRow;
};

type TranscriptSource = MessageSource | RowSource;

function deferSettingEventsUntilUserMessage(sources: TranscriptSource[]): TranscriptSource[] {
  const projected: TranscriptSource[] = [];
  let modelEvent: RowSource | undefined;
  let thinkingLevelEvent: RowSource | undefined;

  for (const source of sources) {
    if (source.kind === "row" && source.row.event?.kind === "model") {
      modelEvent = source;
      continue;
    }
    if (source.kind === "row" && source.row.event?.kind === "thinkingLevel") {
      thinkingLevelEvent = source;
      continue;
    }

    if (source.kind === "message" && source.message.role === "user") {
      if (modelEvent) projected.push(modelEvent);
      if (thinkingLevelEvent) projected.push(thinkingLevelEvent);
      modelEvent = undefined;
      thinkingLevelEvent = undefined;
    }
    projected.push(source);
  }

  // Unconsumed changes remain persisted and will appear once a user message follows.
  return projected;
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

function numberField(value: unknown, key: string): number | undefined {
  const candidate = asRecord(value)[key];
  return typeof candidate === "number" && Number.isFinite(candidate) ? candidate : undefined;
}

function stringField(value: unknown, key: string): string | undefined {
  const candidate = asRecord(value)[key];
  return typeof candidate === "string" ? candidate : undefined;
}

function timestampField(value: unknown): number | undefined {
  const timestamp = asRecord(value).timestamp;
  if (typeof timestamp === "number" && Number.isFinite(timestamp)) return timestamp;
  if (typeof timestamp !== "string") return undefined;
  const parsed = Date.parse(timestamp);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function mergeUsage(
  left: SerializableUsage | undefined,
  right: SerializableUsage | undefined,
): SerializableUsage | undefined {
  if (!left) return right;
  if (!right) return left;
  return {
    input: left.input + right.input,
    output: left.output + right.output,
    cacheRead: left.cacheRead + right.cacheRead,
    cacheWrite: left.cacheWrite + right.cacheWrite,
    ...(left.cacheWrite1h !== undefined || right.cacheWrite1h !== undefined
      ? { cacheWrite1h: (left.cacheWrite1h ?? 0) + (right.cacheWrite1h ?? 0) }
      : {}),
    ...(left.reasoning !== undefined || right.reasoning !== undefined
      ? { reasoning: (left.reasoning ?? 0) + (right.reasoning ?? 0) }
      : {}),
    totalTokens: left.totalTokens + right.totalTokens,
    cost: {
      input: left.cost.input + right.cost.input,
      output: left.cost.output + right.cost.output,
      cacheRead: left.cost.cacheRead + right.cost.cacheRead,
      cacheWrite: left.cost.cacheWrite + right.cost.cacheWrite,
      total: left.cost.total + right.cost.total,
    },
  };
}

function contentParts(
  message: Pick<SerializableAgentMessage, "content">,
): SerializableAgentContent[] {
  if (!Array.isArray(message.content)) return [];
  return message.content.filter((part): part is SerializableAgentContent =>
    Boolean(
      part &&
      typeof part === "object" &&
      !Array.isArray(part) &&
      typeof (part as { type?: unknown }).type === "string",
    ),
  );
}

export function messageText(message: Pick<SerializableAgentMessage, "content">): string {
  if (typeof message.content === "string") return message.content;
  if (!Array.isArray(message.content)) return "";
  return contentParts(message)
    .map((part) => (typeof part.text === "string" ? part.text : ""))
    .filter(Boolean)
    .join("\n");
}

function thinkingText(part: SerializableAgentContent): string {
  const record = asRecord(part);
  return typeof record.thinking === "string"
    ? record.thinking
    : typeof record.reasoning === "string"
      ? record.reasoning
      : "";
}

function contentBlockFromPart(part: SerializableAgentContent): TranscriptContentBlock | null {
  if (part.type === "text" && typeof part.text === "string") {
    return part.text ? { kind: "text", text: part.text } : null;
  }
  if (part.type === "thinking" || part.type === "reasoning") {
    const text = thinkingText(part);
    return text
      ? {
          kind: "thinking",
          text,
          startedAt: numberField(part, "startedAt"),
          endedAt: numberField(part, "endedAt"),
        }
      : null;
  }
  if (part.type === "image") {
    const record = asRecord(part);
    if (typeof record.data === "string" && record.data) {
      return {
        kind: "image",
        data: record.data,
        mimeType:
          typeof record.mimeType === "string" && record.mimeType
            ? record.mimeType
            : typeof record.mediaType === "string" && record.mediaType
              ? record.mediaType
              : "image/png",
      };
    }
  }
  return {
    kind: "unknown",
    type: typeof part.type === "string" && part.type ? part.type : "unknown",
    value: part,
  };
}

function contentBlocksForValue(value: unknown): TranscriptContentBlock[] {
  if (typeof value === "string") {
    return value ? [{ kind: "text", text: value }] : [];
  }
  if (!Array.isArray(value)) {
    return value === undefined || value === null
      ? []
      : [{ kind: "unknown", type: "content", value }];
  }
  return value.flatMap((part) => {
    if (!part || typeof part !== "object") {
      return [{ kind: "unknown", type: "unknown", value: part } satisfies TranscriptContentBlock];
    }
    const block = contentBlockFromPart(part as SerializableAgentContent);
    return block ? [block] : [];
  });
}

function toolResultForMessage(message: SerializableAgentMessage): ToolResultRecord | null {
  if (message.role !== "toolResult") return null;
  const record = asRecord(message);
  const id = typeof record.toolCallId === "string" ? record.toolCallId : "";
  if (!id) return null;
  const resultBlocks = contentBlocksForValue(message.content);
  const result = messageText(message);
  const isError = record.isError === true;
  return {
    id,
    name: typeof record.toolName === "string" ? record.toolName : "tool",
    ...(result ? { result } : {}),
    resultBlocks,
    details: record.details,
    isError,
    aborted: isAbortedToolResult(message, isError),
  };
}

function toolTraceFromPart(part: SerializableAgentContent, index: number): ToolTrace | null {
  if (!["toolCall", "tool_use", "functionCall"].includes(part.type)) return null;
  const record = asRecord(part);
  const id = typeof record.id === "string" ? record.id : `tool:${index}`;
  const rawStatus = typeof record.status === "string" ? record.status : undefined;
  const status: ToolTraceStatus =
    rawStatus === "done" || rawStatus === "error" || rawStatus === "aborted"
      ? rawStatus
      : rawStatus === "running"
        ? "running"
        : "waiting";
  const inlineResult = record.result;
  const resultBlocks = Array.isArray(record.resultBlocks)
    ? contentBlocksForValue(record.resultBlocks)
    : contentBlocksForValue(inlineResult);
  const details = record.details;
  return {
    id,
    name: typeof record.name === "string" ? record.name : "tool",
    args: record.arguments ?? record.input,
    result: inlineResult,
    ...(resultBlocks.length > 0 ? { resultBlocks } : {}),
    ...(details !== undefined && details !== null ? { details } : {}),
    status,
    startedAt: typeof record.startedAt === "number" ? record.startedAt : undefined,
    endedAt: typeof record.endedAt === "number" ? record.endedAt : undefined,
  };
}

function blocksForMessage(
  message: SerializableAgentMessage,
  sourceIndex: number,
): TranscriptBlock[] {
  if (typeof message.content === "string") {
    return message.content ? [{ kind: "text", text: message.content }] : [];
  }
  const blocks: TranscriptBlock[] = [];
  for (const [partIndex, part] of contentParts(message).entries()) {
    const tool = toolTraceFromPart(part, sourceIndex * 1000 + partIndex);
    if (tool) {
      blocks.push({ kind: "tool", tool });
      continue;
    }
    const block = contentBlockFromPart(part);
    if (block) blocks.push(block);
  }
  return blocks;
}

function applyToolResult(trace: ToolTrace, result: ToolResultRecord): void {
  trace.status = result.aborted ? "aborted" : result.isError ? "error" : "done";
  if (trace.name === "tool") trace.name = result.name;
  if ((trace.result === undefined || trace.result === null) && result.result !== undefined) {
    trace.result = result.result;
  }
  if (result.resultBlocks.length > 0) trace.resultBlocks = result.resultBlocks;
  if (trace.details === undefined && result.details !== undefined) trace.details = result.details;
}

function extendRowTiming(row: WorkingTranscriptRow, startedAt?: number, endedAt?: number) {
  if (startedAt !== undefined) {
    row.startedAt = row.startedAt === undefined ? startedAt : Math.min(row.startedAt, startedAt);
  }
  if (endedAt !== undefined) {
    row.endedAt = row.endedAt === undefined ? endedAt : Math.max(row.endedAt, endedAt);
  }
}

function blockTiming(block: TranscriptBlock): { startedAt?: number; endedAt?: number } {
  return block.kind === "tool"
    ? { startedAt: block.tool.startedAt, endedAt: block.tool.endedAt }
    : block.kind === "thinking"
      ? { startedAt: block.startedAt, endedAt: block.endedAt }
      : {};
}

/**
 * Fold one assistant message's provider/model and live-measured timing into
 * its turn row — the per-turn usage dialog's model list plus the turn-time
 * dialog's TTFT and decode speed. Historical (persisted) messages carry no
 * timing fields, so only genuinely streamed turns contribute.
 */
function extendRowTurnMetrics(row: WorkingTranscriptRow, message: SerializableAgentMessage): void {
  const provider = stringField(message, "provider");
  const model = stringField(message, "model");
  if (provider && model) {
    const label = `${provider}/${model}`;
    if (!row.models?.includes(label)) {
      row.models = row.models ? [...row.models, label] : [label];
    }
  }
  const startedAt = numberField(message, "startedAt");
  const firstTokenAt = numberField(message, "firstTokenAt");
  const endedAt = numberField(message, "endedAt");
  if (startedAt !== undefined && firstTokenAt !== undefined && firstTokenAt > startedAt) {
    row.ttftMs = (row.ttftMs ?? 0) + (firstTokenAt - startedAt);
    row.ttftSteps = (row.ttftSteps ?? 0) + 1;
  }
  const output = message.usage?.output;
  if (
    firstTokenAt !== undefined &&
    endedAt !== undefined &&
    endedAt > firstTokenAt &&
    output !== undefined &&
    output > 0
  ) {
    row.decodeMs = (row.decodeMs ?? 0) + (endedAt - firstTokenAt);
    row.decodeTokens = (row.decodeTokens ?? 0) + output;
  }
}

function copyTextForBlocks(blocks: TranscriptBlock[]): string {
  return blocks
    .filter((block): block is Extract<TranscriptBlock, { kind: "text" }> => block.kind === "text")
    .map((block) => block.text)
    .join("\n\n");
}

function assistantSections(rounds: TranscriptBlock[][]): AssistantTurnSections {
  const isExecutionActivity = (block: TranscriptBlock) =>
    block.kind === "tool" || block.kind === "extension";
  const firstActivityRound = rounds.findIndex((round) => round.some(isExecutionActivity));

  if (firstActivityRound < 0) {
    const blocks = rounds.flat();
    return {
      ordered: blocks,
      initialThinking: blocks.filter(
        (block): block is Extract<TranscriptBlock, { kind: "thinking" }> =>
          block.kind === "thinking",
      ),
      intro: [],
      activity: [],
      // Keep image/unknown blocks instead of silently dropping provider or
      // extension content from turns without tool calls.
      final: blocks.filter((block) => block.kind !== "thinking"),
      stepCount: 0,
    };
  }

  let lastActivityRound = firstActivityRound;
  rounds.forEach((round, index) => {
    if (round.some(isExecutionActivity)) lastActivityRound = index;
  });

  const initialThinking: AssistantTurnSections["initialThinking"] = [];
  const intro: AssistantTurnSections["intro"] = [];
  const activity: TranscriptBlock[] = [];
  const final: AssistantTurnSections["final"] = [];

  rounds.forEach((round, roundIndex) => {
    if (roundIndex < firstActivityRound) {
      for (const block of round) {
        if (block.kind === "thinking") initialThinking.push(block);
        if (block.kind !== "tool") intro.push(block);
      }
      return;
    }

    if (roundIndex === firstActivityRound) {
      const firstActivityIndex = round.findIndex(isExecutionActivity);
      round.forEach((block, blockIndex) => {
        if (blockIndex < firstActivityIndex) {
          if (block.kind === "thinking") initialThinking.push(block);
          if (block.kind !== "tool") intro.push(block);
        } else {
          activity.push(block);
        }
      });
      return;
    }

    if (roundIndex <= lastActivityRound) {
      activity.push(...round);
      return;
    }

    for (const block of round) {
      if (block.kind !== "tool" && block.kind !== "thinking") final.push(block);
      else activity.push(block);
    }
  });

  return {
    ordered: rounds.flat(),
    initialThinking,
    intro,
    activity,
    final,
    stepCount: activity.filter(isExecutionActivity).length,
  };
}

function assistantOutcome(message: SerializableAgentMessage): AssistantOutcome | undefined {
  const stopReason = stringField(message, "stopReason");
  const errorMessage = stringField(message, "errorMessage");
  if (!stopReason && !errorMessage) return undefined;
  if (stopReason === "aborted") {
    return { status: "aborted", stopReason, ...(errorMessage ? { errorMessage } : {}) };
  }
  if (stopReason === "error" || errorMessage) {
    return {
      status: "error",
      ...(stopReason ? { stopReason } : {}),
      // Real provider failures get a friendly explanation appended; the raw
      // text is preserved so logs/copy still carry the original detail.
      ...(errorMessage ? { errorMessage: withFriendlyErrorHint(errorMessage) } : {}),
    };
  }
  return {
    status: stopReason === "toolUse" ? "streaming" : "complete",
    stopReason,
  };
}

function applyAssistantOutcomeToBlocks(
  blocks: TranscriptBlock[],
  outcome: AssistantOutcome | undefined,
): TranscriptBlock[] {
  if (!outcome || (outcome.status !== "error" && outcome.status !== "aborted")) return blocks;
  const fallback =
    outcome.errorMessage ?? (outcome.status === "aborted" ? "Operation aborted" : "Error");
  return blocks.map((block) => {
    if (block.kind !== "tool") return block;
    if (block.tool.status !== "waiting" && block.tool.status !== "running") return block;
    return {
      ...block,
      tool: {
        ...block.tool,
        status: outcome.status as "error" | "aborted",
        ...(block.tool.result === undefined ? { result: fallback } : {}),
      },
    };
  });
}

function customMessageVisible(message: SerializableAgentMessage): boolean {
  // SDK treats missing/false display as hidden. Do not leak extension state into
  // the transcript merely because it happens to contain text or JSON.
  return asRecord(message).display === true;
}

function extensionPresentationForCustomMessage(
  message: SerializableAgentMessage,
  sourceKey: string,
): ExtensionPresentation | undefined {
  const record = asRecord(message);
  const details = asRecord(record.details);
  const declared =
    parseExtensionPresentation(record.presentation) ??
    parseExtensionPresentation(details.presentation);
  if (declared) return declared;

  if (stringField(message, "customType") !== "subagent_supervisor_request") return undefined;
  const legacyId =
    (typeof details.id === "string" && details.id.trim()) ||
    (typeof details.runId === "string" && details.runId.trim()) ||
    sourceKey;
  return {
    version: 1,
    extensionId: "pi-subagents",
    sourceLabel: "Subagents",
    audience: "agent",
    kind: "activity",
    correlationId: legacyId.slice(0, 256),
    severity: "neutral",
  };
}

function bashFromMessage(message: SerializableAgentMessage): BashExecution {
  const record = asRecord(message);
  return {
    command: typeof record.command === "string" ? record.command : "",
    output: typeof record.output === "string" ? record.output : messageText(message),
    ...(numberField(message, "exitCode") !== undefined
      ? { exitCode: numberField(message, "exitCode") }
      : {}),
    cancelled: record.cancelled === true,
    truncated: record.truncated === true,
    ...(typeof record.fullOutputPath === "string" ? { fullOutputPath: record.fullOutputPath } : {}),
    excludeFromContext: record.excludeFromContext === true,
  };
}

function summaryFromMessage(message: SerializableAgentMessage): TranscriptSummary {
  const record = asRecord(message);
  const kind = message.role === "branchSummary" ? "branch" : "compaction";
  return {
    kind,
    text: typeof record.summary === "string" ? record.summary : "",
    ...(numberField(message, "tokensBefore") !== undefined
      ? { tokensBefore: numberField(message, "tokensBefore") }
      : {}),
    ...(typeof record.fromId === "string" ? { fromId: record.fromId } : {}),
    ...(record.details !== undefined ? { details: record.details } : {}),
    ...(record.fromHook === true ? { fromHook: true } : {}),
  };
}

function rowForNonAssistantMessage(
  message: SerializableAgentMessage,
  sourceKey: string,
  sourceId: string | undefined,
  timestamp: number | undefined,
  sourceIndex: number,
  extensionMessageRender?: ExtensionMessageRenderSnapshot,
): TranscriptRow | null {
  const role = message.role;
  if (role === "custom") {
    if (!customMessageVisible(message)) return null;
    const blocks = contentBlocksForValue(message.content);
    const extensionPresentation = extensionPresentationForCustomMessage(message, sourceKey);
    return {
      key: `custom:${sourceKey}`,
      role: "custom",
      blocks,
      copyText: copyTextForBlocks(blocks),
      customType: stringField(message, "customType") ?? "custom",
      ...(extensionPresentation ? { extensionPresentation } : {}),
      ...(extensionMessageRender ? { extensionMessageRender } : {}),
      display: true,
      ...(asRecord(message).details !== undefined ? { details: asRecord(message).details } : {}),
      ...(sourceId ? { sourceId } : {}),
      ...(timestamp !== undefined ? { timestamp } : {}),
    };
  }
  if (role === "bashExecution") {
    const bash = bashFromMessage(message);
    const blocks: TranscriptBlock[] = bash.output ? [{ kind: "text", text: bash.output }] : [];
    return {
      key: `bash:${sourceKey}`,
      role: "bash",
      blocks,
      copyText: bash.output,
      bash,
      ...(sourceId ? { sourceId } : {}),
      ...(timestamp !== undefined ? { timestamp } : {}),
    };
  }
  if (role === "branchSummary" || role === "compactionSummary") {
    const summary = summaryFromMessage(message);
    const blocks: TranscriptBlock[] = summary.text ? [{ kind: "text", text: summary.text }] : [];
    return {
      key: `summary:${sourceKey}`,
      role: "summary",
      blocks,
      copyText: summary.text,
      summary,
      ...(sourceId ? { sourceId } : {}),
      ...(timestamp !== undefined ? { timestamp } : {}),
    };
  }
  const blocks = blocksForMessage(message, sourceIndex);
  const copyText = copyTextForBlocks(blocks);
  if (role === "user" || role === "error") {
    if (blocks.length === 0 && role !== "error") return null;
    const errorText =
      role === "error" && blocks.length === 0
        ? withFriendlyErrorHint(stringField(message, "errorMessage") ?? "Agent error")
        : undefined;
    const finalBlocks = errorText
      ? [{ kind: "text", text: errorText } satisfies TranscriptBlock]
      : blocks;
    return {
      key: `${role}:${sourceKey}`,
      role,
      blocks: finalBlocks,
      copyText: copyTextForBlocks(finalBlocks),
      ...(sourceId ? { sourceId } : {}),
      ...(timestamp !== undefined ? { timestamp } : {}),
    };
  }
  if (role === "tool" || role === "toolResult" || role === "assistant") return null;
  // Preserve unknown roles as a visible diagnostic row instead of silently
  // presenting them as assistant prose.
  const details = asRecord(message);
  return {
    key: `event:${sourceKey}`,
    role: "event",
    blocks,
    copyText,
    event: {
      kind: "unknown",
      label: `Unknown message role: ${role || "(missing)"}`,
      details,
    },
    ...(sourceId ? { sourceId } : {}),
    ...(timestamp !== undefined ? { timestamp } : {}),
  };
}

function sourceMessages(
  messages: readonly SerializableAgentMessage[],
  options: BuildTranscriptOptions | undefined,
): { sources: TranscriptSource[]; projectedMessageCount: number } {
  const entries = options?.entries;
  const rendersByMessageIndex = new Map<number, ExtensionMessageRenderSnapshot>();
  for (const render of Object.values(options?.extensionMessageRenders ?? {})) {
    if (render.messageIndex !== undefined) rendersByMessageIndex.set(render.messageIndex, render);
  }
  if (!entries) {
    return {
      sources: messages.map((message, index) => ({
        kind: "message" as const,
        message,
        key: String(index),
        timestamp: timestampField(message),
        ...(rendersByMessageIndex.get(index)
          ? { extensionMessageRender: rendersByMessageIndex.get(index) }
          : {}),
      })),
      projectedMessageCount: 0,
    };
  }

  const sources: TranscriptSource[] = [];
  let projectedMessageCount = 0;
  for (const entry of entries) {
    const record = asRecord(entry);
    const type = typeof record.type === "string" ? record.type : "unknown";
    const sourceId = typeof record.id === "string" ? record.id : undefined;
    const sourceKey = sourceId ?? `${type}:${sources.length}`;
    const timestamp = timestampField(record);
    if (type === "message") {
      projectedMessageCount += 1;
      const message = asAgentMessage(record.message);
      if (message) {
        sources.push({
          kind: "message",
          message,
          key: sourceKey,
          sourceId,
          timestamp,
          ...(sourceId && options?.extensionMessageRenders?.[sourceId]
            ? { extensionMessageRender: options.extensionMessageRenders[sourceId] }
            : {}),
        });
      }
      continue;
    }
    if (type === "custom_message") {
      projectedMessageCount += 1;
      const message = {
        role: "custom",
        customType: typeof record.customType === "string" ? record.customType : "custom",
        content: (record.content as SerializableAgentContent[] | string) ?? "",
        display: record.display === true,
        ...(record.details !== undefined ? { details: record.details } : {}),
        ...(record.presentation !== undefined ? { presentation: record.presentation } : {}),
      } as SerializableAgentMessage;
      sources.push({
        kind: "message",
        message,
        key: sourceKey,
        sourceId,
        timestamp,
        ...(sourceId && options?.extensionMessageRenders?.[sourceId]
          ? { extensionMessageRender: options.extensionMessageRenders[sourceId] }
          : {}),
      });
      continue;
    }
    if (type === "compaction") {
      projectedMessageCount += 1;
      sources.push({
        kind: "message",
        message: {
          role: "compactionSummary",
          content: "",
          summary: typeof record.summary === "string" ? record.summary : "",
          tokensBefore: record.tokensBefore as number | undefined,
          details: record.details,
          fromHook: record.fromHook,
        } as SerializableAgentMessage,
        key: sourceKey,
        sourceId,
        timestamp,
      });
      continue;
    }
    if (type === "branch_summary") {
      const summary = typeof record.summary === "string" ? record.summary : "";
      // Match Pi's sessionEntryToContextMessages(): an empty branch summary
      // remains an entry but does not consume a position in session.messages.
      if (summary) projectedMessageCount += 1;
      sources.push({
        kind: "message",
        message: {
          role: "branchSummary",
          content: "",
          summary,
          fromId: record.fromId as string | undefined,
          details: record.details,
          fromHook: record.fromHook,
        } as SerializableAgentMessage,
        key: sourceKey,
        sourceId,
        timestamp,
      });
      continue;
    }
    if (type === "model_change") {
      const providerId = String(record.provider ?? "");
      const providerLabel = options?.providerNames?.get(providerId) ?? providerId;
      sources.push({
        kind: "row",
        row: {
          key: `event:${sourceKey}`,
          role: "event",
          blocks: [],
          copyText: "",
          event: {
            kind: "model",
            label: `Model: ${providerLabel}/${String(record.modelId ?? "")}`,
            details: record,
          },
          ...(sourceId ? { sourceId } : {}),
          ...(timestamp !== undefined ? { timestamp } : {}),
        },
      });
      continue;
    }
    if (type === "thinking_level_change") {
      sources.push({
        kind: "row",
        row: {
          key: `event:${sourceKey}`,
          role: "event",
          blocks: [],
          copyText: "",
          event: {
            kind: "thinkingLevel",
            label: `Thinking level: ${String(record.thinkingLevel ?? "off")}`,
            details: record,
          },
          ...(sourceId ? { sourceId } : {}),
          ...(timestamp !== undefined ? { timestamp } : {}),
        },
      });
      continue;
    }
    // Plain custom entries, labels and session metadata are intentionally not
    // rendered. Their data is for extension/session state, not conversation UI.
  }

  const tailStart = Math.min(projectedMessageCount, messages.length);
  for (let index = tailStart; index < messages.length; index += 1) {
    const message = messages[index];
    sources.push({
      kind: "message",
      message,
      key: `stream:${index}`,
      timestamp: timestampField(message),
      ...(rendersByMessageIndex.get(index)
        ? { extensionMessageRender: rendersByMessageIndex.get(index) }
        : {}),
    });
  }
  return {
    sources: deferSettingEventsUntilUserMessage(sources),
    projectedMessageCount,
  };
}

function asAgentMessage(value: unknown): SerializableAgentMessage | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  if (typeof record.role !== "string") return null;
  return {
    ...(record as SerializableAgentMessage),
    role: record.role,
    content: (record.content as SerializableAgentMessage["content"]) ?? "",
  };
}

export function buildTranscriptRows(
  messages: readonly SerializableAgentMessage[],
  options?: BuildTranscriptOptions,
): TranscriptRow[];
export function buildTranscriptRows(
  input: { messages: readonly SerializableAgentMessage[] } & BuildTranscriptOptions,
): TranscriptRow[];
export function buildTranscriptRows(
  inputOrMessages:
    | readonly SerializableAgentMessage[]
    | ({ messages: readonly SerializableAgentMessage[] } & BuildTranscriptOptions),
  options?: BuildTranscriptOptions,
): TranscriptRow[] {
  const input: { messages: readonly SerializableAgentMessage[] } & BuildTranscriptOptions =
    Array.isArray(inputOrMessages)
      ? { messages: inputOrMessages, ...(options ?? {}) }
      : (inputOrMessages as {
          messages: readonly SerializableAgentMessage[];
        } & BuildTranscriptOptions);
  const messages = input.messages;
  const { sources } = sourceMessages(messages, input);
  const rows: WorkingTranscriptRow[] = [];
  let activeAssistant: WorkingTranscriptRow | null = null;
  // Tool-call ids are provider-owned and may repeat. Track unresolved call
  // occurrences only inside the assistant turn currently being projected.
  const pendingToolTraces = new Map<string, ToolTrace[]>();
  const registerToolTrace = (trace: ToolTrace) => {
    const pending = pendingToolTraces.get(trace.id);
    if (pending) pending.push(trace);
    else pendingToolTraces.set(trace.id, [trace]);
  };
  const firstPendingToolTrace = (id: string): ToolTrace | undefined =>
    pendingToolTraces.get(id)?.[0];
  const takePendingToolTrace = (id: string): ToolTrace | undefined => {
    const pending = pendingToolTraces.get(id);
    const trace = pending?.shift();
    if (pending?.length === 0) pendingToolTraces.delete(id);
    return trace;
  };
  const resetAssistant = () => {
    activeAssistant = null;
    pendingToolTraces.clear();
  };

  sources.forEach((source, sourceIndex) => {
    if (source.kind === "row") {
      rows.push(source.row);
      resetAssistant();
      return;
    }
    const { message, key: sourceKey, sourceId, timestamp, extensionMessageRender } = source;
    const role = message.role;
    if (role === "toolResult") {
      const result = toolResultForMessage(message);
      if (!result) return;
      const linkedTrace = takePendingToolTrace(result.id);
      if (linkedTrace) {
        applyToolResult(linkedTrace, result);
        return;
      }
      const block: TranscriptBlock = {
        kind: "tool",
        tool: {
          id: result.id,
          name: result.name,
          result: result.result,
          ...(result.resultBlocks.length > 0 ? { resultBlocks: result.resultBlocks } : {}),
          details: result.details,
          status: result.aborted ? "aborted" : result.isError ? "error" : "done",
        },
      };
      const row: WorkingTranscriptRow = {
        key: `assistant:${sourceKey}`,
        role: "assistant",
        blocks: [block],
        copyText: "",
        rounds: [[block]],
        ...(sourceId ? { sourceId, sourceEndId: sourceId } : {}),
        ...(timestamp !== undefined ? { timestamp } : {}),
      };
      rows.push(row);
      activeAssistant = row;
      return;
    }
    if (role === "tool") {
      const toolBlocks = blocksForMessage(message, sourceIndex).filter(
        (block): block is Extract<TranscriptBlock, { kind: "tool" }> => block.kind === "tool",
      );
      if (toolBlocks.length === 0) return;
      if (activeAssistant?.role === "assistant") {
        for (const block of toolBlocks) {
          const pending = firstPendingToolTrace(block.tool.id);
          if (pending) {
            Object.assign(pending, block.tool);
          } else {
            activeAssistant.blocks.push(block);
            const lastRound = activeAssistant.rounds?.[activeAssistant.rounds.length - 1];
            if (lastRound) lastRound.push(block);
            else activeAssistant.rounds = [[block]];
            registerToolTrace(block.tool);
          }
          extendRowTiming(activeAssistant, block.tool.startedAt, block.tool.endedAt);
        }
        activeAssistant.copyText = copyTextForBlocks(activeAssistant.blocks);
        if (sourceId) activeAssistant.sourceEndId = sourceId;
      } else {
        const row: WorkingTranscriptRow = {
          key: `assistant:${sourceKey}`,
          role: "assistant",
          blocks: [...toolBlocks],
          copyText: "",
          rounds: [[...toolBlocks]],
          ...(sourceId ? { sourceId, sourceEndId: sourceId } : {}),
          ...(timestamp !== undefined ? { timestamp } : {}),
        };
        for (const block of toolBlocks) registerToolTrace(block.tool);
        rows.push(row);
        activeAssistant = row;
      }
      return;
    }
    if (role === "assistant") {
      const outcome = assistantOutcome(message);
      const blocks = applyAssistantOutcomeToBlocks(blocksForMessage(message, sourceIndex), outcome);
      for (const block of blocks) {
        if (block.kind === "tool") registerToolTrace(block.tool);
      }
      const messageStartedAt = numberField(message, "startedAt");
      const messageEndedAt = numberField(message, "endedAt");
      if (activeAssistant?.role === "assistant") {
        activeAssistant.blocks.push(...blocks);
        activeAssistant.copyText = copyTextForBlocks(activeAssistant.blocks);
        activeAssistant.rounds = [...(activeAssistant.rounds ?? []), blocks];
        activeAssistant.usage = mergeUsage(activeAssistant.usage, message.usage);
        if (sourceId) activeAssistant.sourceEndId = sourceId;
        if (outcome) activeAssistant.outcome = outcome;
        extendRowTiming(activeAssistant, messageStartedAt, messageEndedAt);
        extendRowTurnMetrics(activeAssistant, message);
        for (const block of blocks) {
          const timing = blockTiming(block);
          extendRowTiming(activeAssistant, timing.startedAt, timing.endedAt);
        }
        return;
      }
      if (blocks.length === 0 && !outcome) {
        resetAssistant();
        return;
      }
      const row: WorkingTranscriptRow = {
        key: `assistant:${sourceKey}`,
        role: "assistant",
        blocks: [...blocks],
        copyText: copyTextForBlocks(blocks),
        rounds: [[...blocks]],
        ...(outcome ? { outcome } : {}),
        ...(sourceId ? { sourceId, sourceEndId: sourceId } : {}),
        ...(timestamp !== undefined ? { timestamp } : {}),
        ...(messageStartedAt !== undefined ? { startedAt: messageStartedAt } : {}),
        ...(messageEndedAt !== undefined ? { endedAt: messageEndedAt } : {}),
        ...(message.usage ? { usage: message.usage } : {}),
      };
      rows.push(row);
      activeAssistant = row;
      extendRowTurnMetrics(row, message);
      for (const block of blocks) {
        const timing = blockTiming(block);
        extendRowTiming(row, timing.startedAt, timing.endedAt);
      }
      return;
    }

    const special = rowForNonAssistantMessage(
      message,
      sourceKey,
      sourceId,
      timestamp,
      sourceIndex,
      extensionMessageRender,
    );
    if (special?.role === "custom") {
      const block: TranscriptBlock = { kind: "extension", row: special };
      if (activeAssistant?.role === "assistant") {
        activeAssistant.blocks.push(block);
        activeAssistant.rounds = [...(activeAssistant.rounds ?? []), [block]];
        activeAssistant.copyText = copyTextForBlocks(activeAssistant.blocks);
        if (sourceId) activeAssistant.sourceEndId = sourceId;
      } else {
        const row: WorkingTranscriptRow = {
          key: `assistant:${sourceKey}`,
          role: "assistant",
          blocks: [block],
          copyText: "",
          rounds: [[block]],
          ...(sourceId ? { sourceId, sourceEndId: sourceId } : {}),
          ...(timestamp !== undefined ? { timestamp } : {}),
        };
        rows.push(row);
        activeAssistant = row;
      }
      return;
    }
    if (special) rows.push(special);
    // Hidden custom messages are intentionally absent but still represent a
    // context boundary; this prevents unrelated assistant turns from merging.
    resetAssistant();
  });

  if (input.turnActive === false) {
    for (const row of rows) {
      for (const block of row.blocks) {
        if (
          block.kind !== "tool" ||
          (block.tool.status !== "waiting" && block.tool.status !== "running")
        ) {
          continue;
        }
        block.tool = {
          ...block.tool,
          status: "aborted",
          ...(block.tool.result === undefined ? { result: "Operation aborted" } : {}),
        };
      }
    }
  }

  return rows.map(({ rounds, ...row }) => ({
    ...row,
    ...(row.role === "assistant" ? { sections: assistantSections(rounds ?? [row.blocks]) } : {}),
  }));
}

function blockEquivalent(a: TranscriptBlock, b: TranscriptBlock): boolean {
  if (a.kind !== b.kind) return false;
  if (a.kind === "text" && b.kind === "text") return a.text === b.text;
  if (a.kind === "image" && b.kind === "image") {
    return a.mimeType === b.mimeType && a.data === b.data;
  }
  if (a.kind === "unknown" && b.kind === "unknown") {
    return a.type === b.type && valuesEquivalent(a.value, b.value);
  }
  if (a.kind === "thinking" && b.kind === "thinking") {
    return a.text === b.text && a.startedAt === b.startedAt && a.endedAt === b.endedAt;
  }
  if (a.kind === "tool" && b.kind === "tool") {
    const x = a.tool;
    const y = b.tool;
    return (
      x.id === y.id &&
      x.name === y.name &&
      x.status === y.status &&
      x.startedAt === y.startedAt &&
      x.endedAt === y.endedAt &&
      x.args === y.args &&
      x.result === y.result &&
      blockListEquivalent(x.resultBlocks ?? [], y.resultBlocks ?? []) &&
      x.details === y.details
    );
  }
  if (a.kind === "extension" && b.kind === "extension") {
    return rowEquivalent(a.row, b.row);
  }
  return false;
}

function valuesEquivalent(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (a === undefined || b === undefined || a === null || b === null) return false;
  if (typeof a !== "object" || typeof b !== "object") return false;
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return false;
  }
}

function blockListEquivalent(a: TranscriptBlock[], b: TranscriptBlock[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (!blockEquivalent(a[i], b[i])) return false;
  }
  return true;
}

function usageEquivalent(
  a: SerializableUsage | undefined,
  b: SerializableUsage | undefined,
): boolean {
  if (!a || !b) return a === b;
  return (
    a.input === b.input &&
    a.output === b.output &&
    a.cacheRead === b.cacheRead &&
    a.cacheWrite === b.cacheWrite &&
    a.cacheWrite1h === b.cacheWrite1h &&
    a.reasoning === b.reasoning &&
    a.totalTokens === b.totalTokens &&
    a.cost.input === b.cost.input &&
    a.cost.output === b.cost.output &&
    a.cost.cacheRead === b.cost.cacheRead &&
    a.cost.cacheWrite === b.cost.cacheWrite &&
    a.cost.total === b.cost.total
  );
}

function rowEquivalent(a: TranscriptRow, b: TranscriptRow): boolean {
  if (
    a.key !== b.key ||
    a.role !== b.role ||
    a.copyText !== b.copyText ||
    a.startedAt !== b.startedAt ||
    a.endedAt !== b.endedAt ||
    a.sourceId !== b.sourceId ||
    a.sourceEndId !== b.sourceEndId ||
    a.timestamp !== b.timestamp ||
    !valuesEquivalent(a.outcome, b.outcome) ||
    a.customType !== b.customType ||
    !valuesEquivalent(a.extensionPresentation, b.extensionPresentation) ||
    !valuesEquivalent(a.extensionMessageRender, b.extensionMessageRender) ||
    a.display !== b.display ||
    !valuesEquivalent(a.details, b.details) ||
    !valuesEquivalent(a.bash, b.bash) ||
    !valuesEquivalent(a.summary, b.summary) ||
    !valuesEquivalent(a.event, b.event) ||
    !usageEquivalent(a.usage, b.usage) ||
    !blockListEquivalent(a.blocks, b.blocks)
  ) {
    return false;
  }
  if (!a.sections !== !b.sections) return false;
  if (a.sections && b.sections) {
    return (
      a.sections.stepCount === b.sections.stepCount &&
      blockListEquivalent(a.sections.ordered, b.sections.ordered) &&
      blockListEquivalent(a.sections.initialThinking, b.sections.initialThinking) &&
      blockListEquivalent(a.sections.intro, b.sections.intro) &&
      blockListEquivalent(a.sections.activity, b.sections.activity) &&
      blockListEquivalent(a.sections.final, b.sections.final)
    );
  }
  return true;
}

/**
 * Text-file attachments travel inside the prompt text as tagged blocks so any
 * model (and the CLI) sees them; the transcript folds them back into chips.
 */
export function buildAttachedFileBlock(name: string, content: string, sourcePath?: string): string {
  const safeName = name.replace(/"/g, "'");
  const safePath = sourcePath ? ` path="${sourcePath.replace(/"/g, "'")}"` : "";
  const body = content.endsWith("\n") ? content.slice(0, -1) : content;
  return `<attached-file name="${safeName}"${safePath}>\n${body}\n</attached-file>`;
}

/** Path-only attachment: the file is not read or parsed, only its absolute path is injected. */
export function buildAttachedPathBlock(name: string, sourcePath: string): string {
  const safeName = name.replace(/"/g, "'");
  const safePath = sourcePath.replace(/"/g, "'");
  return `<attached-path name="${safeName}" path="${safePath}"/>`;
}

/** Image attachment path marker: content travels via the images channel, the path is injected as text. */
export function buildAttachedImageBlock(name: string, sourcePath: string): string {
  const safeName = name.replace(/"/g, "'");
  const safePath = sourcePath.replace(/"/g, "'");
  return `<attached-image name="${safeName}" path="${safePath}"/>`;
}

type ParsedFileAttachment = {
  name: string;
  content: string;
  /** Absolute path of the original source file carried by the block, when present. */
  path?: string;
  /** True for <attached-path> blocks: content was not read; the agent operates on the source file. */
  pathOnly?: boolean;
};

export type ParsedUserText = {
  text: string;
  files: ParsedFileAttachment[];
  documents: AttachmentReference[];
};

// Builders always emit `name` first, then an optional `path="..."` attribute.
const ATTACHED_FILE_PATTERN =
  /<attached-file name="([^"]*)"(?: path="([^"]*)")?>\n?([\s\S]*?)\n?<\/attached-file>/g;
const ATTACHED_PATH_PATTERN = /<attached-path name="([^"]*)"(?: path="([^"]*)")?\/>/g;
const ATTACHED_IMAGE_PATTERN = /<attached-image name="([^"]*)"(?: path="([^"]*)")?\/>/g;

export function parseUserAttachments(raw: string): ParsedUserText {
  const files: ParsedUserText["files"] = [];
  const documents = parseAttachmentReferences(raw);
  const text = stripAttachmentReferenceBlocks(raw)
    .replace(
      ATTACHED_FILE_PATTERN,
      (_match, name: string, path: string | undefined, content: string) => {
        files.push({ name, content, ...(path ? { path } : {}) });
        return "";
      },
    )
    .replace(ATTACHED_PATH_PATTERN, (_match, name: string, path: string | undefined) => {
      files.push({ name, content: "", pathOnly: true, ...(path ? { path } : {}) });
      return "";
    })
    // Image content travels via the images channel; the marker is display-only.
    .replace(ATTACHED_IMAGE_PATTERN, () => "")
    .trim();
  return { text, files, documents };
}

/**
 * Streaming hot path: the reducer rebuilds `messages` on every agent event,
 * so every derived row is a fresh object even when its content is unchanged.
 * Substituting the previous row object for content-equivalent rows lets a
 * memoized row component skip re-rendering the stable transcript prefix —
 * only the actively streaming row reconciles per frame. Row keys remain the
 * identity boundary: this optimization must never alias a live key to a
 * persisted row or rewrite a persisted key.
 */
export function reuseStableRows(
  previous: TranscriptRow[] | null,
  next: TranscriptRow[],
): TranscriptRow[] {
  if (!previous || previous.length === 0) return next;
  const byKey = new Map(previous.map((row) => [row.key, row]));
  let reusedAll = previous.length === next.length;
  const merged = next.map((row, index) => {
    const prior = byKey.get(row.key);
    if (prior && rowEquivalent(prior, row)) {
      if (reusedAll && previous[index] !== prior) reusedAll = false;
      return prior;
    }
    reusedAll = false;
    return row;
  });
  return reusedAll ? previous : merged;
}

/** The assistant/error row a user row failed into, when a retry is offered. */
export type RetryableTurn = { assistantKey: string };

const EMPTY_SKIPPED: ReadonlySet<string> = new Set();

