function optimisticMessageFingerprint(message: { role: string; content: unknown }): string {
  const content = message.content;
  // Host-injected attachment blocks must not make an otherwise identical
  // authoritative message look different from the pending optimistic row.
  if (typeof content === "string") {
    return JSON.stringify({
      role: message.role,
      text: stripAttachmentReferenceBlocks(content).trim(),
      images: [],
    });
  }
  if (Array.isArray(content)) {
    const text: string[] = [];
    const images: Array<{ data: unknown; mimeType: unknown }> = [];
    for (const part of content) {
      if (!part || typeof part !== "object") continue;
      const value = part as Record<string, unknown>;
      if (typeof value.text === "string") text.push(value.text);
      if (value.type === "image") {
        images.push({ data: value.data, mimeType: value.mimeType ?? value.mediaType });
      }
    }
    return JSON.stringify({
      role: message.role,
      text: stripAttachmentReferenceBlocks(text.join("\n")).trim(),
      images,
    });
  }
  try {
    return JSON.stringify({ role: message.role, content });
  } catch {
    return `${message.role}:${String(content)}`;
  }
}

/**
 * Keep local optimistic rows across an authoritative snapshot until a matching
 * SDK message has arrived. Snapshots are authoritative for persisted state,
 * but they cannot know about a desktop-only row created after the snapshot was
 * built.
 */
function mergeOptimisticMessages(
  current: SessionSnapshot | null,
  incoming: SessionSnapshot | null,
): SessionSnapshot | null {
  const sameSession =
    current !== null && incoming !== null && current.sessionId === incoming.sessionId;
  const sameGeneration = sameSession && current.revision === incoming.revision;
  const activeOptimisticSend =
    sameSession &&
    (current.isIdle === false || incoming.isIdle === false) &&
    current.messages.some((message) => typeof message._optimisticKey === "string");
  if (!sameSession || (!sameGeneration && !activeOptimisticSend)) {
    return incoming;
  }

  const pending = current.messages
    .map((message, index) => ({ message, index }))
    .filter(({ message }) => typeof message._optimisticKey === "string");
  if (pending.length === 0) return incoming;

  const committedCounts = new Map<string, number>();
  for (const message of current.messages) {
    if (message._optimisticKey !== undefined) continue;
    const key = optimisticMessageFingerprint(message);
    committedCounts.set(key, (committedCounts.get(key) ?? 0) + 1);
  }
  const incomingCounts = new Map<string, number>();
  for (const message of incoming.messages) {
    const key = optimisticMessageFingerprint(message);
    incomingCounts.set(key, (incomingCounts.get(key) ?? 0) + 1);
  }

  const preserved = pending.filter(({ message }) => {
    if (
      incoming.messages.some((candidate) => candidate._optimisticKey === message._optimisticKey)
    ) {
      return false;
    }
    const key = optimisticMessageFingerprint(message);
    // A matching additional authoritative message means the SDK has already
    // accepted this turn even if the start event was missed by the renderer.
    return (incomingCounts.get(key) ?? 0) <= (committedCounts.get(key) ?? 0);
  });
  if (preserved.length === 0) return incoming;

  const messages = [...incoming.messages];
  let inserted = 0;
  for (const { message, index } of preserved) {
    messages.splice(Math.min(index + inserted, messages.length), 0, message);
    inserted += 1;
  }
  return { ...incoming, messages };
}

/**
 * Desktop-local live-timing fields (stamped onto assistant messages by the
 * transcript reducer during streaming) must survive authoritative snapshots:
 * the host rebuilds messages from persisted entries and cannot know about
 * them, so the run-end snapshot would otherwise wipe the stats pills' TTFT
 * and decode-speed data the moment a reply settles.
 */
function mergeLiveTiming(
  current: SessionSnapshot | null,
  incoming: SessionSnapshot | null,
): SessionSnapshot | null {
  if (!current || !incoming || current.sessionId !== incoming.sessionId) return incoming;
  if (current.messages.length === 0 || incoming.messages.length === 0) return incoming;
  const currentFingerprints = current.messages.map(optimisticMessageFingerprint);
  const timingKeys = ["startedAt", "firstTokenAt", "endedAt"] as const;
  let changed = false;
  const messages = incoming.messages.map((message, index) => {
    const previous = current.messages[index];
    if (!previous) return message;
    // Same position, same role, same text: the authoritative message IS the
    // streamed row, so its desktop-local timing fields still apply. A
    // rewritten history (compaction, fork, edit) has different text and
    // carries nothing over.
    if (currentFingerprints[index] !== optimisticMessageFingerprint(message)) return message;
    const previousRecord = previous as Record<string, unknown>;
    const next: Record<string, unknown> = { ...message };
    let touched = false;
    for (const key of timingKeys) {
      if (next[key] !== undefined) continue;
      const value = previousRecord[key];
      if (typeof value === "number" && Number.isFinite(value)) {
        next[key] = value;
        touched = true;
      }
    }
    if (!touched) return message;
    changed = true;
    return next as SessionSnapshot["messages"][number];
  });
  return changed ? { ...incoming, messages } : incoming;
}

