/**
 * Epoch helpers for Host/Workspace/Session rehydrate (R7).
 */
import type {
  HostStatusSnapshot,
  PackageSnapshot,
  SessionSnapshot,
  ToolSnapshot,
  WorkspaceSnapshot,
} from "@piabyss/protocol";

export type EpochState = {
  host: HostStatusSnapshot | null;
  workspace: WorkspaceSnapshot | null;
  session: SessionSnapshot | null;
  packages: PackageSnapshot | null;
  tools: ToolSnapshot | null;
  desynchronized: boolean;
  desyncReason?: string;
  lastSequence: number;
};

export function emptyEpoch(): EpochState {
  return {
    host: null,
    workspace: null,
    session: null,
    packages: null,
    tools: null,
    desynchronized: false,
    lastSequence: 0,
  };
}

export function beginHostEpoch(_prev: EpochState, status: HostStatusSnapshot): EpochState {
  return {
    ...emptyEpoch(),
    host: status,
    lastSequence: 0,
  };
}

/**
 * Recovery-era epoch anchoring: adopt the freshly handshaken Host identity
 * and reset the sequence watermark WITHOUT clearing the visible workspace/
 * session/packages/tools snapshots. The renderer keeps painting the old —
 * possibly briefly stale — state until completeRehydrate atomically replaces
 * it, so a recovery pass never flashes an empty shell at the user.
 */
export function anchorHostEpoch(state: EpochState, host: HostStatusSnapshot): EpochState {
  return {
    ...state,
    host,
    lastSequence: 0,
  };
}

export function clearWorkspaceEpoch(state: EpochState): EpochState {
  return {
    ...state,
    workspace: null,
    session: null,
    packages: null,
    tools: null,
  };
}

export function applyWorkspaceSnapshot(
  state: EpochState,
  workspace: WorkspaceSnapshot,
): EpochState {
  if (
    state.workspace &&
    (state.workspace.id !== workspace.id || state.workspace.revision !== workspace.revision)
  ) {
    return {
      ...state,
      workspace,
      session: null,
      packages: null,
      tools: null,
    };
  }
  return { ...state, workspace };
}

export function applySessionSnapshot(
  state: EpochState,
  session: SessionSnapshot | null,
): EpochState {
  const sessionId = session?.sessionId ?? null;
  const sessionRevision = session?.revision ?? 0;
  // Agent events are flushed once per animation frame while streaming, so
  // keep the previous host reference when only the session payload moved.
  // Identity-stable host prevents every host-scoped effect/subscription
  // (for example the Git watcher in ChangesPanel) from tearing down and
  // re-arming for every streamed token.
  const host =
    state.host &&
    state.host.sessionId === sessionId &&
    state.host.sessionRevision === sessionRevision
      ? state.host
      : state.host
        ? { ...state.host, sessionId, sessionRevision }
        : null;
  return {
    ...state,
    // session.snapshot advances the active generation before any following
    // session-scoped event (for example agent.toolsChanged) is validated.
    host,
    session,
    tools: session?.tools ?? null,
  };
}

export function applyPackageSnapshot(
  state: EpochState,
  packages: PackageSnapshot | null,
): EpochState {
  return { ...state, packages };
}

export function markDesynchronized(state: EpochState, reason: string): EpochState {
  return { ...state, desynchronized: true, desyncReason: reason };
}

export function noteSequence(
  state: EpochState,
  sequence: number,
): { state: EpochState; action: "apply" | "drop" | "gap" } {
  if (state.lastSequence > 0 && sequence <= state.lastSequence) {
    return { state, action: "drop" };
  }
  if (state.lastSequence > 0 && sequence > state.lastSequence + 1) {
    // Advance lastSequence to the seen gap seq so later events do not re-gap forever.
    // Rehydrate will still run; completeRehydrate may also set lastSequence from hostClient.
    return {
      state: {
        ...markDesynchronized(state, `sequence gap ${state.lastSequence} -> ${sequence}`),
        lastSequence: sequence,
      },
      action: "gap",
    };
  }
  return { state: { ...state, lastSequence: sequence }, action: "apply" };
}

import type { SessionRuntimeState, SessionSnapshot, SessionSummary } from "@piabyss/protocol";

export type { SessionRuntimeState } from "@piabyss/protocol";

export type SessionCatalogEntry = SessionSummary & {
  runtimeState: SessionRuntimeState;
  lastError?: string;
};

export type SessionCatalogState = {
  workspaceId: string | null;
  entries: Record<string, SessionCatalogEntry>;
  order: string[];
  loaded: boolean;
};

export function emptySessionCatalog(): SessionCatalogState {
  return {
    workspaceId: null,
    entries: {},
    order: [],
    loaded: false,
  };
}

export function replaceSessionCatalog(
  current: SessionCatalogState,
  workspaceId: string,
  items: SessionSummary[],
): SessionCatalogState {
  const sameWorkspace = current.workspaceId === workspaceId;
  const entries: Record<string, SessionCatalogEntry> = {};

  for (const item of items) {
    const previous = sameWorkspace ? current.entries[item.sessionId] : undefined;
    entries[item.sessionId] = {
      ...item,
      runtimeState: item.runtimeState ?? previous?.runtimeState ?? "inactive",
      ...(previous?.lastError ? { lastError: previous.lastError } : {}),
    };
  }

  if (sameWorkspace) {
    for (const id of current.order) {
      const runtimeState = current.entries[id]?.runtimeState;
      if (
        !entries[id] &&
        runtimeState !== undefined &&
        runtimeState !== "inactive" &&
        runtimeState !== "error"
      ) {
        entries[id] = current.entries[id];
      }
    }
  }

  return {
    workspaceId,
    entries,
    order: sortSessionIds(entries),
    loaded: true,
  };
}

export function upsertSessionSnapshot(
  current: SessionCatalogState,
  workspaceId: string,
  snapshot: SessionSnapshot,
  now = Date.now(),
): SessionCatalogState {
  const base = current.workspaceId === workspaceId ? current : emptySessionCatalog();
  const previous = base.entries[snapshot.sessionId];
  // SessionManager assigns a future file path immediately, but does not write
  // the JSONL file until the first message. Keep that blank Session out of the
  // sidebar; the first user-message snapshot will insert it normally.
  if (!previous && snapshot.messages.length === 0) return base;
  const runtimeState = runtimeStateFromSnapshot(snapshot);
  const entry: SessionCatalogEntry = {
    sessionId: snapshot.sessionId,
    sessionPath: snapshot.sessionPath ?? previous?.sessionPath ?? "",
    name: snapshot.name,
    cwd: snapshot.cwd,
    // Creation time is set once and never changes. For fresh entries use now
    // as an approximation; the real value arrives from session.list.
    createdAt: previous ? previous.createdAt : now,
    // Merely opening/rehydrating a session yields an idle snapshot and is not
    // activity: keep the listed timestamp so the entry does not jump to the
    // top of the recency sort and then snap back on the next session.list.
    updatedAt: runtimeState === "idle" && previous ? previous.updatedAt : now,
    messageCount: snapshot.messages.length,
    sessionRevision: snapshot.revision,
    runtimeState,
  };
  const entries = { ...base.entries, [snapshot.sessionId]: entry };
  return {
    workspaceId,
    entries,
    order: sortSessionIds(entries),
    loaded: base.loaded,
  };
}

export function updateSessionCatalogInfo(
  current: SessionCatalogState,
  sessionId: string,
  name: string | undefined,
): SessionCatalogState {
  const entry = current.entries[sessionId];
  if (!entry) return current;
  return {
    ...current,
    entries: {
      ...current.entries,
      [sessionId]: { ...entry, name },
    },
  };
}

export function setSessionRuntimeState(
  current: SessionCatalogState,
  sessionId: string,
  runtimeState: SessionRuntimeState,
  lastError?: string,
  updatedAt?: number,
): SessionCatalogState {
  const entry = current.entries[sessionId];
  if (!entry) return current;
  const entries = {
    ...current.entries,
    [sessionId]: {
      ...entry,
      runtimeState,
      // Recency policy (matches upsertSessionSnapshot): only genuine activity
      // reorders the list. The host stamps idle announcements with Date.now()
      // right after session.open, and local optimistic transitions
      // (starting/inactive/error rollback) carry no timestamp — neither may
      // jump the entry to the top of the recency sort.
      updatedAt:
        updatedAt !== undefined && (runtimeState === "running" || runtimeState === "queued")
          ? updatedAt
          : entry.updatedAt,
      ...(lastError ? { lastError } : { lastError: undefined }),
    },
  };
  return {
    ...current,
    entries,
    order: sortSessionIds(entries),
  };
}

export function runtimeStateFromSnapshot(
  snapshot: Pick<
    SessionSnapshot,
    "isIdle" | "isStreaming" | "isCompacting" | "isRetrying" | "pending"
  >,
): SessionRuntimeState {
  if (snapshot.isStreaming || snapshot.isCompacting || snapshot.isRetrying || !snapshot.isIdle) {
    return "running";
  }
  if (snapshot.pending.steering.length > 0 || snapshot.pending.followUp.length > 0) {
    return "queued";
  }
  return "idle";
}

export function sessionCatalogItems(catalog: SessionCatalogState): SessionCatalogEntry[] {
  return catalog.order.flatMap((id) => {
    const entry = catalog.entries[id];
    return entry ? [entry] : [];
  });
}

function sortTime(entry: SessionCatalogEntry): number {
  return entry.createdAt ?? entry.updatedAt;
}

function sortSessionIds(entries: Record<string, SessionCatalogEntry>): string[] {
  return Object.values(entries)
    .sort((a, b) => sortTime(b) - sortTime(a) || a.sessionId.localeCompare(b.sessionId))
    .map((entry) => entry.sessionId);
}

/** Atomic Host snapshot and recovery-period event buffering (R2/R7). */
import type { HostEventEnvelope, RehydrateSnapshot } from "@piabyss/protocol";
import { hostClient } from "./host-client";

export type RehydrateResult = RehydrateSnapshot;

const DEFAULT_RECOVERY_EVENT_LIMIT = 10_000;

export class RecoveryEventBuffer {
  private hostInstanceId: string | null = null;
  private events: HostEventEnvelope[] = [];
  private overflowed = false;

  constructor(private readonly limit = DEFAULT_RECOVERY_EVENT_LIMIT) {}

  begin(hostInstanceId: string): void {
    this.hostInstanceId = hostInstanceId;
    this.events = [];
    this.overflowed = false;
  }

  capture(event: HostEventEnvelope): boolean {
    if (
      this.hostInstanceId === null ||
      event.hostInstanceId !== this.hostInstanceId ||
      event.event === "host.ready" ||
      event.event === "host.fatal"
    ) {
      return false;
    }
    if (this.events.length < this.limit) {
      this.events.push(event);
    } else {
      this.overflowed = true;
    }
    return true;
  }

  finish(
    hostInstanceId: string,
    watermark: number,
  ): { events: HostEventEnvelope[]; overflowed: boolean } {
    const sameHost = this.hostInstanceId === hostInstanceId;
    const events = sameHost ? this.events.filter((event) => event.sequence > watermark) : [];
    const overflowed = !sameHost || this.overflowed;
    this.cancel();
    return { events, overflowed };
  }

  cancel(): void {
    this.hostInstanceId = null;
    this.events = [];
    this.overflowed = false;
  }
}

export function resolveRehydrateHostInstanceId(
  expectedHostInstanceId: string | undefined,
  observedHostInstanceId: string | null,
): string | null {
  return expectedHostInstanceId ?? observedHostInstanceId;
}

export async function fullRehydrate(expectedHostInstanceId?: string): Promise<RehydrateResult> {
  const hostId = resolveRehydrateHostInstanceId(
    expectedHostInstanceId,
    hostClient.getHostInstanceId(),
  );
  if (!hostId) {
    throw new Error("No hostInstanceId — call hello first");
  }

  const response = await hostClient.request(
    "system.rehydrate",
    { expectedHostInstanceId: hostId },
    null,
    15_000,
  );
  if (!response.ok) {
    // Preserve the Host error classification: runFullRehydrate must be able to
    // tell transient retryable rejections (e.g. the graph lock briefly held by
    // an in-flight workspace switch) apart from terminal failures.
    const error = Object.assign(new Error(response.error?.message ?? "system.rehydrate failed"), {
      code: response.error?.code,
      retryable: response.error?.retryable === true,
    });
    throw error;
  }
  return response.result;
}

import type { HostEventEnvelope, SessionRuntimeState } from "@piabyss/protocol";

export type EventIdentityState = {
  hostInstanceId: string | null;
  workspaceId: string | null;
  workspaceRevision: number | undefined;
  sessionId: string | null;
  sessionRevision: number | undefined;
};

/**
 * Authoritative snapshot events are allowed to advance their own generation.
 * Sequence ordering plus payload/envelope validation guards those transitions;
 * unrelated business events must still match the full active identity.
 */
export function expectedIdentityForEvent(
  event: HostEventEnvelope,
  state: EventIdentityState,
): {
  hostInstanceId: string | null;
  workspaceId?: string | null;
  workspaceRevision?: number;
  sessionId?: string | null;
  sessionRevision?: number;
} {
  const host = { hostInstanceId: state.hostInstanceId };

  switch (event.event) {
    case "host.ready":
    case "host.statusChanged":
    case "host.fatal":
    case "workspace.changed":
    case "provider.loginEvent":
    case "extensionUi.request":
    case "extensionUi.closed":
    case "extensionUi.groupClosed":
    case "extensionUi.customStarted":
    case "extensionUi.customFrame":
    case "extensionUi.customClosed":
      return host;
    case "session.snapshot":
    case "session.infoChanged":
    case "session.runtimeChanged":
    case "agent.event":
    case "package.diagnostic":
    case "extensionUi.statusChanged":
    case "extensionUi.widgetChanged":
    case "extensionUi.widgetAttentionRequested":
    case "extensionUi.notification":
    case "package.progress":
    case "package.snapshot":
    case "package.resourcesChanged":
      return {
        ...host,
        workspaceId: state.workspaceId,
        workspaceRevision: state.workspaceRevision,
      };
    default:
      return {
        ...host,
        workspaceId: state.workspaceId,
        workspaceRevision: state.workspaceRevision,
        sessionId: state.sessionId,
        sessionRevision: state.sessionRevision,
      };
  }
}

export type ExtensionUiRequestDelivery = "active" | "background" | "candidate";

export function extensionUiRequestDelivery(args: {
  eventSessionId: string;
  activeSessionId: string | null;
  catalogRuntimeState?: SessionRuntimeState;
}): ExtensionUiRequestDelivery {
  if (args.eventSessionId === args.activeSessionId) return "active";
  if (args.catalogRuntimeState === "running" || args.catalogRuntimeState === "queued") {
    return "background";
  }
  return "candidate";
}

