          }
          isAnimating={showCaret}
          caret={mode === "streaming" ? "block" : undefined}
          shikiTheme={["github-light", "github-dark"]}
          mermaid={{ config: mermaidConfig, errorComponent: MermaidError }}
          controls={{
            code: false,
            table: false,
            mermaid: {
              copy: true,
              download: false,
              fullscreen: true,
              panZoom: true,
            },
          }}
          lineNumbers={false}
          urlTransform={urlTransform}
        >
          {normalized}
        </Streamdown>
      </MarkdownRenderBoundary>
    </div>
  );
});

export type ParsedUserText = {
  text: string;
  files: ParsedFileAttachment[];
  documents: AttachmentReference[];
};

// Builders always emit `name` first, then an optional `path="..."` attribute.
const ATTACHED_FILE_PATTERN =
  /<attached-file name="([^"]*)"(?: path="([^"]*)")?>\n?([\s\S]*?)\n?<\/attached-file>/g;
const ATTACHED_PATH_PATTERN = /<attached-path name="([^"]*)"(?: path="([^"]*)")?\/>/g;
const ATTACHED_IMAGE_PATTERN = /<attached-image name="([^"]*)"(?: path="([^"]*)")?\/>/g;

export function parseUserAttachments(raw: string): ParsedUserText {
  const files: ParsedUserText["files"] = [];
  const documents = parseAttachmentReferences(raw);
  const text = stripAttachmentReferenceBlocks(raw)
    .replace(
      ATTACHED_FILE_PATTERN,
      (_match, name: string, path: string | undefined, content: string) => {
        files.push({ name, content, ...(path ? { path } : {}) });
        return "";
      },
    )
    .replace(ATTACHED_PATH_PATTERN, (_match, name: string, path: string | undefined) => {
      files.push({ name, content: "", pathOnly: true, ...(path ? { path } : {}) });
      return "";
    })
    // Image content travels via the images channel; the marker is display-only.
    .replace(ATTACHED_IMAGE_PATTERN, () => "")
    .trim();
  return { text, files, documents };
}

/**
 * Streaming hot path: the reducer rebuilds `messages` on every agent event,
 * so every derived row is a fresh object even when its content is unchanged.
 * Substituting the previous row object for content-equivalent rows lets a
 * memoized row component skip re-rendering the stable transcript prefix —
 * only the actively streaming row reconciles per frame. Row keys remain the
 * identity boundary: this optimization must never alias a live key to a
 * persisted row or rewrite a persisted key.
 */
export function reuseStableRows(
  previous: TranscriptRow[] | null,
  next: TranscriptRow[],
): TranscriptRow[] {
  if (!previous || previous.length === 0) return next;
  const byKey = new Map(previous.map((row) => [row.key, row]));
  let reusedAll = previous.length === next.length;
  const merged = next.map((row, index) => {
    const prior = byKey.get(row.key);
    if (prior && rowEquivalent(prior, row)) {
      if (reusedAll && previous[index] !== prior) reusedAll = false;
      return prior;
    }
    reusedAll = false;
    return row;
  });
  return reusedAll ? previous : merged;
}

/** The assistant/error row a user row failed into, when a retry is offered. */
export type RetryableTurn = { assistantKey: string };

const EMPTY_SKIPPED: ReadonlySet<string> = new Set();

/**
 * Which user rows can be retried. A user row is retryable when its answer did
 * not complete: the next non-decorative row (skipping event/summary/custom/
 * bash rows, which can interleave between a user prompt and its response) is
 * either an assistant row that errored or was aborted, or a standalone error
 * row. A user row followed by another user row never got an answer, so it is
 * not retryable. Rows in `skipped` (e.g. a failed bubble already hidden by a
 * previous retry) are treated as absent so a second failure on the same turn
 * stays retryable.
 */
export function computeRetryableTurns(
  rows: readonly TranscriptRow[],
  skipped: ReadonlySet<string> = EMPTY_SKIPPED,
): Map<string, RetryableTurn> {
  const retryable = new Map<string, RetryableTurn>();
  for (let index = 0; index < rows.length; index += 1) {
    const row = rows[index];
    if (!row || row.role !== "user") continue;
    for (let next = index + 1; next < rows.length; next += 1) {
      const candidate = rows[next];
      if (!candidate || skipped.has(candidate.key)) continue;
      if (candidate.role === "custom" || candidate.role === "bash" || candidate.role === "event") {
        continue;
      }
      if (candidate.role === "summary") continue;
      if (candidate.role === "user") break;
      if (
        candidate.role === "assistant" &&
        (candidate.outcome?.status === "error" || candidate.outcome?.status === "aborted")
      ) {
        retryable.set(row.key, { assistantKey: candidate.key });
      } else if (candidate.role === "error") {
        retryable.set(row.key, { assistantKey: candidate.key });
      }
      break;
    }
  }
  return retryable;
}

