import { describe, expect, it } from "vitest";
import { buildAttachmentReferenceBlock, type SerializableAgentMessage } from "@piabyss/protocol";
import {
  buildAttachedFileBlock,
  buildTranscriptRows,
  computeRetryableTurns,
  executionTraceIsActive,
  findStreamingAssistantKey,
  messageText,
  parseUserAttachments,
  reuseStableRows,
  thinkingBlockIsLive,
  type TranscriptRow,
} from "./transcript-model";

describe("attached file blocks", () => {
  it("round-trips build and parse", () => {
    const raw = [
      "please review",
      buildAttachedFileBlock("main.rs", "fn main() {}\n"),
      buildAttachedFileBlock('we"ird.txt', "content"),
    ].join("\n\n");
    const parsed = parseUserAttachments(raw);
    expect(parsed.text).toBe("please review");
    expect(parsed.files).toEqual([
      { name: "main.rs", content: "fn main() {}" },
      { name: "we'ird.txt", content: "content" },
    ]);
  });

  it("folds attached-file blocks carrying a source path back into chips", () => {
    const raw = `查看这个文件\n\n${buildAttachedFileBlock("123.md", "你好\n", "C:\\Users\\liu\\Desktop\\123.md")}`;
    const parsed = parseUserAttachments(raw);
    expect(parsed.text).toBe("查看这个文件");
    expect(parsed.files).toEqual([
      { name: "123.md", content: "你好", path: "C:\\Users\\liu\\Desktop\\123.md" },
    ]);
  });

  it("folds path-only attachments into chips without reading content", () => {
    const raw = `打开这个\n\n<attached-path name="CC Switch.lnk" path="C:\\Users\\liu\\Desktop\\CC Switch.lnk"/>`;
    const parsed = parseUserAttachments(raw);
    expect(parsed.text).toBe("打开这个");
    expect(parsed.files).toEqual([
      {
        name: "CC Switch.lnk",
        content: "",
        pathOnly: true,
        path: "C:\\Users\\liu\\Desktop\\CC Switch.lnk",
      },
    ]);
  });

  it("hides attached-image markers (content travels via the images channel)", () => {
    const raw = `看图\n\n<attached-image name="photo.png" path="D:\\pics\\photo.png"/>`;
    const parsed = parseUserAttachments(raw);
    expect(parsed.text).toBe("看图");
    expect(parsed.files).toEqual([]);
  });

  it("passes through plain text untouched", () => {
    const parsed = parseUserAttachments("just a message");
    expect(parsed).toEqual({ text: "just a message", files: [], documents: [] });
  });

  it("hides managed attachment markers and returns document cards", () => {
    const marker = buildAttachmentReferenceBlock([
      {
        id: "11111111-1111-4111-8111-111111111111",
        name: "manual.pdf",
        mediaType: "application/pdf",
        sizeBytes: 1024,
        status: "ready",
        unit: "page",
        unitCount: 12,
      },
    ]);
    const parsed = parseUserAttachments(`review this\n\n${marker}`);
