          },
        ],
      },
      {
        role: "toolResult",
        toolCallId: "live-persisted",
        toolName: "read",
        isError: false,
        content: [{ type: "text", text: "persisted result" }],
        details: { source: "persisted" },
      },
    ]);
    const tools = rows[0]?.blocks.filter((block) => block.kind === "tool") ?? [];

