import { join } from "node:path";
import {
  createHostError,
  stripAttachmentReferenceBlocks,
  toJsonValue,
  type HostError,
  type JsonValue,
} from "@piabyss/protocol";
import type { HandlerContext, MethodHandler } from "./server.js";
import type { WorkspaceGraphFactory } from "./workspace-graph-factory.js";
import { TIMING_ENTRY_CUSTOM_TYPE } from "./agent-timing.js";
import { buildSessionUsageReport } from "./session-usage-report.js";
import { searchSessions } from "./session-search.js";
import { invalidateSessionListProjection } from "./session-list-projection.js";
import { isObject, readModelsConfig } from "./provider-models-config.js";
import { postSubagentApi, type SubagentHttpControlResponse } from "./subagent-api.js";
import {
  mapSubagentRunState,
  readSubagentRunStatus,
  readSubagentRunTitle,
  readSubagentRunTranscript,
  resolveSubagentRunId,
  subagentRunExists,
} from "./subagent-runs.js";

type SdkSessionTreeNode = {
  entry: unknown;
  children: SdkSessionTreeNode[];
  label?: string;
  labelTimestamp?: string;
};

/**
 * SDK tree nodes carry `label: undefined` keys; toJsonValue would turn those
 * into nulls, which the wire contract rejects — optional keys must be absent.
 */
function toWireTreeNode(node: SdkSessionTreeNode): JsonValue {
  return {
    entry: toJsonValue(node.entry),
    children: node.children.map(toWireTreeNode),
    ...(node.label !== undefined ? { label: node.label } : {}),
    ...(node.labelTimestamp !== undefined ? { labelTimestamp: node.labelTimestamp } : {}),
  };
}

/** Timestamp of one session message entry: the message's own epoch time when
 * numeric, else the parsed ISO entry timestamp, else null. */
function sessionEntryTimestamp(
  entry: Record<string, unknown>,
  message: Record<string, unknown>,
): number | null {
  const messageTime = message.timestamp;
  if (typeof messageTime === "number" && Number.isFinite(messageTime) && messageTime >= 0) {
    return messageTime;
  }
  const entryTime = entry.timestamp;
  if (typeof entryTime === "string") {
    const parsed = Date.parse(entryTime);
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

/**
 * Approximate wall-clock timings folded from persisted session entry
 * timestamps — the same entry stream `getSessionStats()` reads, so the two
 * stay consistent, and compaction-rewritten history is included the same way.
 *
 * Each assistant step's request wall time runs from the triggering message
 * entry (the user prompt or the preceding tool result) to the assistant
 * message completion; each tool batch's wall time runs from the assistant
 * message carrying its calls to the appended tool result. Only positive
 * deltas count, so clock skew between entries contributes nothing.
 *
 * First-token and decode timing ride the persisted `piabyss.timing` custom
 * entries the runtime cache writes when a message settles; only timings whose
 * assistant message is still on the branch fold in.
 */
function deriveSessionTiming(entries: readonly unknown[]): {
  timing: {
    llmMs: number;
    toolMs: number;
    ttftMs?: number;
    ttftSteps?: number;
    decodeMs?: number;
    decodeTokens?: number;
  };
} {
  let llmMs = 0;
  let toolMs = 0;
  let prevRole: string | null = null;
  let prevTime: number | null = null;
  const assistantEntryIds = new Set<string>();
  const timingEntries: Array<Record<string, unknown>> = [];
  for (const entry of entries) {
    if (!entry || typeof entry !== "object") continue;
    const record = entry as Record<string, unknown>;
    if (record.type === "custom" && record.customType === TIMING_ENTRY_CUSTOM_TYPE) {
      if (record.data && typeof record.data === "object" && !Array.isArray(record.data)) {
        timingEntries.push(record.data as Record<string, unknown>);
      }
      continue;
    }
    if (record.type !== "message") continue;
    const message = record.message;
    if (!message || typeof message !== "object") continue;
    const messageRecord = message as Record<string, unknown>;
    const role = typeof messageRecord.role === "string" ? messageRecord.role : null;
    if (role === "assistant" && typeof record.id === "string") {
      assistantEntryIds.add(record.id);
    }
    const time = role ? sessionEntryTimestamp(record, messageRecord) : null;
    if (
      time !== null &&
      prevTime !== null &&
      time > prevTime &&
      ((role === "assistant" && (prevRole === "user" || prevRole === "toolResult")) ||
        (role === "toolResult" && prevRole === "assistant"))
    ) {
      const delta = time - prevTime;
      if (role === "assistant") llmMs += delta;
      else toolMs += delta;
    }
    prevRole = role;
    prevTime = time;
  }
  let ttftMs = 0;
  let ttftSteps = 0;
  let decodeMs = 0;
  let decodeTokens = 0;
  for (const data of timingEntries) {
    const messageEntryId = data.messageEntryId;
    if (typeof messageEntryId !== "string" || !assistantEntryIds.has(messageEntryId)) continue;
    const entryTtft = nonNegativeNumber(data.firstTokenMs);
    if (entryTtft !== null) {
      ttftMs += entryTtft;
      ttftSteps += 1;
    }
    const entryDecode = nonNegativeNumber(data.decodeMs);
    const entryOutput = nonNegativeNumber(data.outputTokens);
    if (entryDecode !== null && entryOutput !== null && entryOutput > 0) {
      decodeMs += entryDecode;
      decodeTokens += entryOutput;
    }
  }
  return {
    timing: {
      llmMs,
      toolMs,
      ...(ttftSteps > 0 ? { ttftMs, ttftSteps } : {}),
      ...(decodeMs > 0 ? { decodeMs, decodeTokens } : {}),
    },
  };
}

function nonNegativeNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
}

/** Forward a subagent control action to the pi-subagent HTTP API. */
async function controlSubagentRun(
  factory: WorkspaceGraphFactory,
  ctx: HandlerContext,
  action: "stop" | "pause" | "continue" | "resume",
  resultKey: "stopped" | "paused" | "continued" | "resumed",
): Promise<{ result: unknown } | { error: HostError }> {
  const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
  if (stale) return { error: stale };
  const { nodeId } = ctx.params as { nodeId: string };
  const runId = resolveSubagentRunId(nodeId);
  const outcome = await postSubagentApi<SubagentHttpControlResponse>(
    `/api/runs/${encodeURIComponent(runId)}/${action}`,
  );
  if (!outcome) {
    return {
      error: createHostError("HOST_NOT_READY", "pi-subagent API unavailable", {
        retryable: true,
      }),
    };
  }
  if (!outcome.ok) {
    return {
      error: createHostError("AGENT_BUSY", outcome.error ?? `Unable to ${action} subagent`, {
        retryable: true,
      }),
    };
  }
  return { result: { [resultKey]: true } };
}

export function createSessionHandlers(
  factory: WorkspaceGraphFactory,
): Partial<Record<string, MethodHandler>> {
  return {
    "session.list": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () => factory.checkIdentity(ctx.context, { requireWorkspace: true }),
        run: async () => {
          const g = factory.getGraph();
          if (!g) throw new Error("No workspace");
          const items = await factory.listSessions();
          return {
            workspaceId: g.workspaceId,
            items: items.map((s) => {
              const runtime = factory.getSessionRuntimeInfo(s.id, s.path);
              return {
                sessionId: s.id,
                sessionPath: s.path,
                name: s.name,
                cwd: s.cwd,
                createdAt: s.created?.getTime?.() ?? s.modified?.getTime?.() ?? Date.now(),
                updatedAt: s.modified?.getTime?.() ?? Date.now(),
                messageCount: s.messageCount,
                archived: s.archived,
                ...(runtime ?? {}),
              };
            }),
          };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.create": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, {
        requireWorkspace: true,
        allowNullSession: true,
      });
      if (stale) return { error: stale };
      const params = (ctx.params ?? {}) as { name?: string };
      const result = await factory.createSession(ctx.id, params.name);
      if (result && typeof result === "object" && "error" in result) {
        return { error: result.error };
      }
      return { result };
    },

    "session.open": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, {
        requireWorkspace: true,
        allowNullSession: true,
      });
      if (stale) return { error: stale };
      const params = ctx.params as { sessionPath: string };
      let result = await factory.openSession(ctx.id, params.sessionPath);
      if (
        result &&
        typeof result === "object" &&
        "error" in result &&
        result.error.code === "SESSION_NOT_FOUND"
      ) {
        const { resolveManagedSessionWorkspace } = await import("./session-lifecycle.js");
        const targetCwd = await resolveManagedSessionWorkspace(factory, params.sessionPath);
        const currentCwd = factory.getGraph()?.canonicalCwd;
        if (targetCwd && !factory.sessionPathsEqual(currentCwd, targetCwd)) {
          const switched = await factory.setCurrent(targetCwd, ctx.id);
          if ("error" in switched) return { error: switched.error };
          result = await factory.openSession(ctx.id, params.sessionPath);
        }
      }
      if (result && typeof result === "object" && "error" in result) {
        return { error: result.error };
      }
      return { result };
    },

    "session.reload": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, {
        requireWorkspace: true,
        requireSession: true,
      });
      if (stale) return { error: stale };
      const result = await factory.reloadSession(ctx.id);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.archive": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const params = ctx.params as { sessionId: string; sessionPath: string };
      const result = await factory.archiveSession(ctx.id, params.sessionId, params.sessionPath);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.restore": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const params = ctx.params as { sessionId: string; sessionPath: string };
      const result = await factory.restoreSession(ctx.id, params.sessionId, params.sessionPath);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.delete": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const params = ctx.params as { sessionId: string; sessionPath: string };
      const result = await factory.deleteSession(ctx.id, params.sessionId, params.sessionPath);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.cleanupArchived": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const result = await factory.cleanupArchivedSessions(ctx.id);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "subagents.getSession": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const { nodeId } = ctx.params as { nodeId: string };
      const runId = resolveSubagentRunId(nodeId);
      if (!subagentRunExists(runId)) {
        return {
          error: createHostError("SESSION_NOT_FOUND", "Subagent run transcript is not available", {
            retryable: true,
          }),
        };
      }
      const title = readSubagentRunTitle(runId);
      const state = mapSubagentRunState(readSubagentRunStatus(runId));
      const transcript = readSubagentRunTranscript(runId);
      if (!transcript) {
        // The run exists but its pi session file has not been flushed yet
        // (child still starting, or the run never produced an assistant turn).
        // Return an empty snapshot instead of an error so the panel renders
        // the no-conversation state rather than a load failure.
        return {
          result: {
            nodeId,
            sessionId: `sub-${runId}`,
            ...(title ? { name: title } : {}),
            state,
            entries: [],
            truncated: false,
            updatedAt: Date.now(),
          },
        };
      }
      return {
        result: {
          nodeId,
          sessionId: transcript.sessionId,
          ...(transcript.name || title ? { name: transcript.name ?? title } : {}),
          state,
          entries: transcript.entries,
          truncated: transcript.truncated,
          updatedAt: transcript.updatedAt,
        },
      };
    },

    "subagents.stop": async (ctx) => controlSubagentRun(factory, ctx, "stop", "stopped"),
    "subagents.pause": async (ctx) => controlSubagentRun(factory, ctx, "pause", "paused"),
    "subagents.continue": async (ctx) => controlSubagentRun(factory, ctx, "continue", "continued"),
    "subagents.resume": async (ctx) => controlSubagentRun(factory, ctx, "resume", "resumed"),

    "session.getSnapshot": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () => factory.checkIdentity(ctx.context, { requireWorkspace: true }),
        run: async () => {
          const g = factory.getGraph();
          return g?.sessionSnapshot ?? null;
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.setName": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      if (
        !server.serviceGraphLock.tryAcquire({
          operationKind: "session.setName",
          requestId: ctx.id,
        })
      ) {
        return {
          error: createHostError("SERVICE_GRAPH_BUSY", "Service graph busy", {
            retryable: true,
          }),
        };
      }

      try {
        const stale = factory.checkIdentity(ctx.context, {
          requireWorkspace: true,
          requireSession: true,
        });
        if (stale) return { error: stale };
        const g = factory.getGraph();
        if (!g?.sessionManager || !g.agentSession) {
          return { error: createHostError("AGENT_NOT_READY", "No active session") };
        }
        // Renaming only updates Session metadata. It does not alter the
        // running model request, tools, resource graph, or conversation tree;
        // the graph lock above is sufficient serialization for this mutation.
        const params = ctx.params as { name: string };
        const snapshot = factory.setActiveSessionName(params.name);
        if (!snapshot) {
          return { error: createHostError("AGENT_NOT_READY", "No active session") };
        }
        return { result: snapshot };
      } finally {
        server.serviceGraphLock.release(ctx.id);
      }
    },

    "session.rename": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const params = ctx.params as {
        sessionId: string;
        sessionPath: string;
        name: string;
      };
      const result = await factory.renameSession(
        ctx.id,
        params.sessionId,
        params.sessionPath,
        params.name,
      );
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.getEntries": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () =>
          factory.checkIdentity(ctx.context, {
            requireWorkspace: true,
            requireSession: true,
          }),
        run: async () => {
          const g = factory.getGraph();
          if (!g?.sessionManager) throw new Error("No active session");
          const entries = g.sessionManager.getEntries().map((e) => toJsonValue(e));
          return {
            entries,
            leafId: g.sessionManager.getLeafId(),
          };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.getTree": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () =>
          factory.checkIdentity(ctx.context, {
            requireWorkspace: true,
            requireSession: true,
          }),
        run: async () => {
          const g = factory.getGraph();
          if (!g?.sessionManager) throw new Error("No active session");
          return {
            tree: (g.sessionManager.getTree() as SdkSessionTreeNode[]).map(toWireTreeNode),
            leafId: g.sessionManager.getLeafId(),
          };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.getStats": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () =>
          factory.checkIdentity(ctx.context, {
            requireWorkspace: true,
            requireSession: true,
          }),
        run: async () => {
          const g = factory.getGraph();
          if (!g?.agentSession) throw new Error("No active session");
          const stats = g.agentSession.getSessionStats();
          return {
            messageCount: stats.totalMessages,
            toolCallCount: stats.toolCalls,
            userMessageCount: stats.userMessages,
            assistantMessageCount: stats.assistantMessages,
            toolResultCount: stats.toolResults,
            tokens: {
              input: stats.tokens.input,
              output: stats.tokens.output,
              cacheRead: stats.tokens.cacheRead,
              cacheWrite: stats.tokens.cacheWrite,
              total: stats.tokens.total,
            },
            ...deriveSessionTiming(g.sessionManager?.getEntries?.() ?? []),
            cost: stats.cost,
            ...(stats.sessionFile ? { sessionFile: stats.sessionFile } : {}),
          };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.getForkPoints": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () =>
          factory.checkIdentity(ctx.context, {
            requireWorkspace: true,
            requireSession: true,
          }),
        run: async () => {
          const g = factory.getGraph();
          if (!g?.agentSession) throw new Error("No active session");
          return {
            items: g.agentSession.getUserMessagesForForking().map(({ entryId, text }) => ({
              entryId,
              text: stripAttachmentReferenceBlocks(text),
            })),
          };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.fork": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, {
        requireWorkspace: true,
        requireSession: true,
      });
      if (stale) return { error: stale };
      const g = factory.getGraph();
      const server = factory.getServer();
      if (!g?.agentSession || !g.sessionManager || !server) {
        return { error: createHostError("AGENT_NOT_READY", "No active session") };
      }
      if (!g.agentSession.isIdle || factory.getSessionOperationLock(g.agentSession).isHeld()) {
        return { error: createHostError("AGENT_BUSY", "Agent busy", { retryable: true }) };
      }
      const params = ctx.params as { entryId: string; position?: "before" | "at" };
      const { prepareForkFile } = await import("./session-lifecycle.js");
      const prepared = prepareForkFile({
        sessionFile: g.sessionManager.getSessionFile(),
        canonicalCwd: g.canonicalCwd,
        entryId: params.entryId,
        ...(params.position ? { position: params.position } : {}),
      });
      if ("error" in prepared) return { error: prepared.error };
      // openSession owns graph-operation locking and identity advancement.
      const opened = await factory.openSession(ctx.id, prepared.forkedPath);
      if (opened && typeof opened === "object" && "error" in opened) {
        return { error: opened.error };
      }
      // The fork writes a brand-new JSONL outside withSessionFileMutation;
      // drop the projection cache so session.list sees it immediately.
      invalidateSessionListProjection();
      return {
        result: {
          session: opened,
          ...(prepared.selectedText !== undefined ? { selectedText: prepared.selectedText } : {}),
        },
      };
    },

    "session.export": async (ctx) => {
      const stale = factory.checkIdentity(ctx.context, { requireWorkspace: true });
      if (stale) return { error: stale };
      const params = ctx.params as {
        format: "html" | "jsonl";
        sessionId?: string;
        sessionPath?: string;
        path?: string;
      };
      const result = params.sessionId
        ? await factory.exportSession(
            ctx.id,
            params.format,
            params.sessionId,
            params.sessionPath ?? "",
            params.path,
          )
        : await factory.exportActiveSession(ctx.id, params.format, params.path);
      if ("error" in result) return { error: result.error };
      return { result };
    },

    "session.usageReport": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () => factory.checkIdentity(ctx.context, { requireWorkspace: true }),
        run: async () => {
          const g = factory.getGraph();
          if (!g) throw new Error("No workspace");
          const providerNames = new Map(
            factory.deps.modelRuntime
              .getProviders()
              .map((provider) => [provider.id, provider.name]),
          );
          const modelsConfig = await readModelsConfig(join(factory.deps.agentDir, "models.json"));
          for (const [providerId, rawProvider] of Object.entries(modelsConfig.providers)) {
            if (isObject(rawProvider) && typeof rawProvider.name === "string") {
              providerNames.set(providerId, rawProvider.name);
            }
          }
          return buildSessionUsageReport({
            agentDir: factory.deps.agentDir,
            canonicalCwd: g.canonicalCwd,
            workspaceId: g.workspaceId,
            providerNames,
          });
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },

    "session.searchAll": async (ctx) => {
      // Host-scoped read of session files on disk: no workspace graph or lock
      // is involved, so search works across every workspace at any time.
      const params = ctx.params as {
        query: string;
        limit?: number;
        includeArchived?: boolean;
      };
      try {
        const report = await searchSessions({
          agentDir: factory.deps.agentDir,
          query: params.query,
          ...(params.limit !== undefined ? { limit: params.limit } : {}),
          ...(params.includeArchived !== undefined
            ? { includeArchived: params.includeArchived }
            : {}),
        });
        return { result: report };
      } catch (err) {
        return {
          error: createHostError(
            "INTERNAL_ERROR",
            err instanceof Error ? err.message : "Session search failed",
          ),
        };
      }
    },

    "session.getCommands": async (ctx) => {
      const server = factory.getServer();
      if (!server) {
        return { error: createHostError("HOST_NOT_READY", "Server not bound") };
      }
      const { withStableGraphRead } = await import("./stable-graph-read.js");
      const out = await withStableGraphRead({
        requestId: ctx.id,
        identity: server.identity,
        serviceGraphLock: server.serviceGraphLock,
        precheck: () =>
          factory.checkIdentity(ctx.context, {
            requireWorkspace: true,
            requireSession: true,
          }),
        run: async () => {
          const g = factory.getGraph();
          if (!g?.agentSession) throw new Error("No active session");
          const commands: {
            invocation: string;
            description: string;
            argumentHint?: string;
            kind: "template" | "command" | "skill";
          }[] = [];
          for (const template of g.agentSession.promptTemplates) {
            commands.push({
              invocation: template.name,
              description: template.description,
              ...(template.argumentHint ? { argumentHint: template.argumentHint } : {}),
              kind: "template",
            });
          }
          try {
            for (const command of g.agentSession.extensionRunner.getRegisteredCommands()) {
              commands.push({
                invocation: command.invocationName,
                description: command.description ?? "",
                kind: "command",
              });
            }
          } catch {
            /* runner may be unavailable mid-reload */
          }
          if (g.resourceLoader) {
            for (const skill of g.resourceLoader.getSkills().skills) {
              commands.push({
                invocation: `skill:${skill.name}`,
                description: skill.description,
                kind: "skill",
              });
            }
          }
          return { commands };
        },
      });
      if (!out.ok) return { error: out.error, identity: out.identity };
      return { result: out.result, identity: out.identity };
    },
  };
}

#!/usr/bin/env node
/**
 * PiAbyss Host entry — owns all Pi SDK services.
 * Transport: JSONL on stdin/stdout; logs on stderr.
 */
import { mkdirSync } from "node:fs";
import { randomUUID } from "node:crypto";
import { homedir } from "node:os";
import { join } from "node:path";
import {
  ModelRegistry,
  ModelRuntime,
  VERSION as SDK_VERSION,
  DefaultPackageManager,
} from "@earendil-works/pi-coding-agent";
import {
  createFauxCore,
  fauxAssistantMessage,
  fauxText,
  fauxToolCall,
} from "@earendil-works/pi-ai";
import { createHostError, type HostCapabilities, type ModelConfigHealth } from "@piabyss/protocol";
import { buildDegradedModelConfigHealth, buildModelConfigHealth } from "./model-health.js";
import { recoverProviderJournals } from "./provider-journal.js";
import { logger } from "./logger.js";
import { PiHostServer } from "./server.js";
import { createWorkspaceHandlers } from "./workspace-controller.js";
import { WorkspaceFileService } from "./workspace-files.js";
import { createSessionHandlers } from "./session-controller.js";
import { createAgentHandlers } from "./agent-controller.js";
import { createPackageHandlers } from "./package-controller.js";
import { createProviderHandlers } from "./provider-controller.js";
import { createExtensionUiHandlers } from "./extension-ui-bridge.js";
import { createTelegramHandlers } from "./telegram-controller.js";
import { createTelegramSessionHandlers } from "./telegram-sessions-controller.js";
import { WorkspaceGraphFactory } from "./workspace-graph-factory.js";
import { applyKnownThinkingProfiles } from "./model-thinking.js";
import { FileCredentialStore } from "./credential-store.js";
import { ExtensionProviderOwnership } from "./extension-provider-ownership.js";
import { refreshModelsLocal } from "./model-runtime-refresh.js";
import { ensureMigrationBackup, MIGRATION_ID } from "./migration-backup.js";
import { migrateLegacyPiAbyssData } from "./piabyss-data.js";
import { applyHostNetworkSettings, ensureGlobalSettingsFile } from "./network-bootstrap.js";
import { AttachmentStore } from "./attachment-store.js";
import { createAttachmentHandlers } from "./attachment-controller.js";
import { createGitHandlers } from "./git-controller.js";
import { GitService } from "./git-service.js";
import { refreshActiveSessionSnapshot } from "./session-snapshot.js";
import { createPiSettingsHandlers, removeSupersededPackages } from "./pi-settings-controller.js";
import { createSkillHandlers } from "./skill-controller.js";
import { createPromptHandlers } from "./prompt-controller.js";
import { createSubagentStatusBridge } from "./subagent-status-extension.js";

function resolveAgentDir(): string {
  const envDir = process.env.PI_CODING_AGENT_DIR;
  if (envDir && envDir.trim()) return envDir.trim();
  const arg = process.argv.find((a) => a.startsWith("--agent-dir="));
  if (arg) return arg.slice("--agent-dir=".length);
  return join(homedir(), ".pi", "agent");
}

function resolveInitialCwd(): string | null {
  const arg = process.argv.find((a) => a.startsWith("--initial-cwd="));
  const value = arg?.slice("--initial-cwd=".length).trim();
  return value ? value : null;
}

/**
 * C1: how many workspace graphs the host may keep bound for instant return.
 * Parse int, clamp to 1..20, ignore anything non-numeric — absent or invalid
 * env keeps the lifecycle's built-in default.
 */
function resolveMaxBoundWorkspaces(): number | undefined {
  const raw = process.env.PIABYSS_MAX_BOUND_WORKSPACES;
  if (!raw?.trim()) return undefined;
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed)) return undefined;
  return Math.min(20, Math.max(1, parsed));
}

/**
 * Deterministic core-release model. It is opt-in and never enabled for a
 * normal Host process; the desktop E2E runner sets PIABYSS_TEST_FAUX=1.
 */
function installTestFauxProvider(modelRegistry: ModelRegistry): void {
  if (process.env.PIABYSS_TEST_FAUX !== "1") return;

  const faux = createFauxCore({
    api: "piabyss-faux-api",
    provider: "piabyss-faux",
    models: [
      {
        id: "piabyss-core",
        name: "PiAbyss Core Test Model",
        reasoning: false,
        input: ["text"],
        contextWindow: 128_000,
        maxTokens: 16_384,
      },
    ],
    tokensPerSecond: 24,
    tokenSize: { min: 1, max: 4 },
  });

  // prompt: tool call -> tool result turn -> final answer -> title refinement
  // abort: a deliberately long response that remains observable while stopping
  faux.setResponses([
    fauxAssistantMessage(fauxToolCall("read", { path: "piabyss-core-e2e.txt" }), {
      stopReason: "toolUse",
    }),
    fauxAssistantMessage(
      [
        fauxText(
          "PIABYSS_STREAM_START Core chat stream completed after a deterministic tool call. PIABYSS_CORE_CHAT_COMPLETE",
        ),
      ],
      { stopReason: "stop" },
    ),
    fauxAssistantMessage(fauxText("Core chat smoke"), { stopReason: "stop" }),
    fauxAssistantMessage(
      fauxText(
        "PIABYSS_ABORT_STREAM " +
          "This deterministic response is intentionally long enough to exercise the Stop action and abort recovery. ".repeat(
            24,
          ),
      ),
      { stopReason: "stop" },
    ),
    fauxAssistantMessage(fauxText("PIABYSS_ABORT_RECOVERED"), {
      stopReason: "stop",
    }),
  ]);

  modelRegistry.registerProvider("piabyss-faux", {
    name: "PiAbyss Core Test Model",
    api: faux.api,
    apiKey: "piabyss-e2e",
    baseUrl: "http://piabyss-faux.invalid",
    streamSimple: faux.streamSimple,
    models: faux.models.map((model) => ({
      id: model.id,
      name: model.name,
      api: model.api,
      reasoning: model.reasoning,
      input: model.input,
      cost: model.cost,
      contextWindow: model.contextWindow,
      maxTokens: model.maxTokens,
    })),
  });
  logger.info("Installed deterministic faux provider for core E2E");
}

async function main(): Promise<void> {
  const agentDir = resolveAgentDir();
  const maxBoundWorkspaces = resolveMaxBoundWorkspaces();
  mkdirSync(agentDir, { recursive: true });

  // Synchronous, before any network activity: proxy/idle-timeout from global
  // settings (never applied by the SDK on the library path) and a guaranteed
  // settings file for the desktop "Open settings.json" affordance.
  ensureGlobalSettingsFile(agentDir);
  applyHostNetworkSettings(agentDir);

  logger.info("Starting Pi Host", {
    agentDir,
    sdkVersion: SDK_VERSION,
    node: process.version,
  });

  // Keep the shared Pi directory native-compatible: adopt PiAbyss-owned data
  // into one private namespace before recovery reads any persisted state.
  // Best-effort: a migration failure degrades to a warning (the next start
  // retries; recovery paths handle missing adoptions safely) — it must never
  // brick Host startup.
  try {
    const migration = await migrateLegacyPiAbyssData(agentDir, MIGRATION_ID);
    if (migration.quarantined.length > 0) {
      logger.warn("Quarantined conflicting legacy PiAbyss data", {
        quarantined: migration.quarantined,
      });
    }
  } catch (err) {
    logger.warn("Legacy PiAbyss data migration failed; continuing with existing state", {
      error: err instanceof Error ? err.message : String(err),
    });
  }
  const attachmentStore = new AttachmentStore({ agentDir });
  await attachmentStore.initialize();

  // Before anything can rewrite user data. The 0.82.1 runtime introduces
  // models-store.json and recomposes providers, so a downgrade is only safe
  // while the pre-migration bytes still exist.
  const migrationBackup = await ensureMigrationBackup(agentDir);

  // PiAbyss now ships its own `ask_user_question` tool, so the third-party
  // package that used to provide it is dropped from the package list before
  // any resource loader reads settings. Runs after the migration backup so the
  // pre-removal bytes are always recoverable.
  removeSupersededPackages(agentDir);

  // Cwd-independent services (PROJECT_SPEC §8.1)
  const credentialStore = FileCredentialStore.forAgentDir(agentDir);

  // Resolve any provider mutation the previous run did not finish, before the
  // runtime reads models.json or auth.json. An unresolved journal means the two
  // files may disagree, which no amount of refreshing can detect.
  const unresolvedRecovery = await recoverProviderJournals(agentDir, credentialStore);

  // The single authoritative runtime. `allowModelNetwork: false` keeps startup
  // offline; only an explicit user refresh may reach the network later.
  const modelRuntime = await ModelRuntime.create({
    credentials: credentialStore,
    modelsPath: join(agentDir, "models.json"),
    modelsStorePath: join(agentDir, "models-store.json"),
    allowModelNetwork: false,
  });
  await migrationBackup?.recordMilestone("runtimeCreate");
  const modelRegistry = new ModelRegistry(modelRuntime);

  // Wraps the runtime's provider registration before anything registers:
  // startup registrations (faux provider) become host-owned; workspace
  // extension registrations become suspendable per graph.
  const providerOwnership = new ExtensionProviderOwnership(modelRuntime);

  installTestFauxProvider(modelRegistry);
  // Degraded outranks a parse check and is sticky: the Host cannot re-derive
  // whether the configuration became coherent, so it stops claiming health
  // until a restart finds no journal.
  const resolveModelConfigHealth = () =>
    unresolvedRecovery
      ? buildDegradedModelConfigHealth(unresolvedRecovery)
      : buildModelConfigHealth(modelRuntime.getError());
  let modelConfigHealth = resolveModelConfigHealth();

  // B1: the deferred startup refresh broadcasts through the same channel as
  // the controllers. A no-op until `graphFactory.onModelHealthChanged` is
  // bound below (after bindServer): before that there is no transport to
  // notify — the desktop reads full status on connect, so skipping is safe.
  let broadcastModelHealth: () => void = () => {};

  // Shared local reconcile pass (B1): exactly what the controllers'
  // refreshModelHealth dep runs, extracted so the deferred startup refresh
  // produces identical state. Reconciliation only — a network catalog fetch is
  // a separate, explicitly authorised call and must never happen here.
  const runRefreshModelHealth = async (signal?: AbortSignal): Promise<ModelConfigHealth> => {
    await refreshModelsLocal(modelRuntime, { signal });
    // Neutral: the profile pass re-registers existing providers and must
    // not become a co-owner that pins another workspace's provider alive.
    await providerOwnership.runNeutral(() =>
      applyKnownThinkingProfiles(modelRegistry, modelRuntime, join(agentDir, "models.json")),
    );
    modelConfigHealth = resolveModelConfigHealth();
    return modelConfigHealth;
  };

  // Serialized: refresh and the thinking-profile pass both re-register
  // providers on the same runtime, so concurrent invocations (startup IIFE vs
  // a controller-triggered health refresh) would expose a mid-state. Calls
  // queue behind each other instead of interleaving; each keeps its own
  // abort signal and rejection.
  let refreshChain: Promise<unknown> = Promise.resolve();
  const refreshModelHealthNow = (signal?: AbortSignal): Promise<ModelConfigHealth> => {
    const run = refreshChain.then(() => runRefreshModelHealth(signal));
    refreshChain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  };

  // Inline neutral profile pass FIRST: it must land before the first graph
  // reads the registry, and it must complete before the deferred refresh
  // below starts — both re-register providers on the same runtime, so
  // running them concurrently would expose a mid-state to the first graph.
  await providerOwnership.runNeutral(() =>
    applyKnownThinkingProfiles(modelRegistry, modelRuntime, join(agentDir, "models.json")),
  );

  // B1: the local model refresh is off the critical path. Startup no longer
  // waits for it. The IIFE serializes refresh → profiles → health so its own
  // steps can never interleave. The localRefresh milestone may now land after
  // server start — allowed, because a late or lost milestone only retains the
  // migration backup longer.
  void (async () => {
    await refreshModelHealthNow();
    await migrationBackup?.recordMilestone("localRefresh");
    broadcastModelHealth();
  })().catch((err: unknown) => {
    // Never trip the unhandledRejection fatal path: a failed local reconcile
    // only leaves the startup health snapshot stale until the next refresh.
    logger.warn("Deferred startup model refresh failed", {
      error: err instanceof Error ? err.message : String(err),
    });
  });

  // Capability detection — check prototype without constructing full PackageManager
  const packageUpdateCheck =
    typeof (DefaultPackageManager.prototype as { checkForAvailableUpdates?: unknown })
      .checkForAvailableUpdates === "function";

  const capabilities: HostCapabilities = {
    packageUpdateCheck,
    extensionUi: true,
    sessionExport: true,
  };

  const graphFactory = new WorkspaceGraphFactory({
    agentDir,
    subagentStatusBridgeFactory: (emit, options) => createSubagentStatusBridge(emit, options),
    attachmentStore,
    credentialStore,
    modelRuntime,
    modelRegistry,
    providerOwnership,
    getModelConfigHealth: () => modelConfigHealth,
    refreshModelHealth: (signal) => refreshModelHealthNow(signal),
    ...(maxBoundWorkspaces !== undefined ? { maxBoundWorkspaces } : {}),
    ...(migrationBackup
      ? {
          recordMigrationMilestone: (milestone) => migrationBackup.recordMilestone(milestone),
        }
      : {}),
    packageUpdateCheck,
  });
  // Late Path-B registrations (an extension calling pi.registerProvider in
  // the middle of an agent turn) are attributed to the active workspace.
  providerOwnership.setFallbackOwnerSource(() => graphFactory.getGraph()?.providerOwner ?? null);
  const workspaceFiles = new WorkspaceFileService();
  const gitService = new GitService();

  const handlers = {
    ...createWorkspaceHandlers(graphFactory, workspaceFiles, gitService),
    ...createGitHandlers(graphFactory, gitService),
    ...createAttachmentHandlers(graphFactory),
    ...createSessionHandlers(graphFactory),
    ...createAgentHandlers(graphFactory),
    ...createProviderHandlers(graphFactory),
    ...createPackageHandlers(graphFactory),
    ...createExtensionUiHandlers(graphFactory),
    ...createTelegramHandlers(agentDir),
    ...createTelegramSessionHandlers(agentDir),
    ...createPiSettingsHandlers(graphFactory, agentDir),
    ...createSkillHandlers(graphFactory),
    ...createPromptHandlers(graphFactory),
  };

  const server = new PiHostServer({
    agentDir,
    sdkVersion: SDK_VERSION,
    getModelConfigHealth: () => modelConfigHealth,
    capabilities,
    handlers,
    getRehydrateState: () => {
      const graph = graphFactory.getGraph();
      const session = graph ? refreshActiveSessionSnapshot(graph) : null;
      return {
        workspace: graph ? graphFactory.buildWorkspaceSnapshot(graph) : null,
        session,
        tools: session?.tools ?? null,
        packages: graph?.packageSnapshot ?? null,
      };
    },
    onShutdown: async () => {
      workspaceFiles.dispose();
      gitService.dispose();
      const { cancelAllPending } = await import("./extension-ui-bridge.js");
      cancelAllPending("Host shutdown");
      const g = graphFactory.getGraph();
      if (g) {
        await graphFactory.disposeGraph(g);
      }
      await graphFactory.disposeRetainedGraphs();
      await attachmentStore.waitForIdle();
      // Last milestone: only a clean teardown proves the migrated runtime did
      // not leave the agent directory in a state that needs the backup.
      await migrationBackup?.recordMilestone("cleanShutdown");
    },
  });

  graphFactory.bindServer(server);

  // Re-emit status when model health is refreshed by controllers
  graphFactory.onModelHealthChanged = () => {
    server.emit("host.statusChanged", server.buildStatus());
  };
  // Now the deferred startup refresh (B1) can broadcast like a controller.
  broadcastModelHealth = () => graphFactory.onModelHealthChanged?.();

  // Unknown detached-task failures invalidate Host authority. Publish fatal,
  // perform bounded cleanup, and let the desktop apply its restart policy.
  process.on("unhandledRejection", (reason) => {
    const message = reason instanceof Error ? reason.message : String(reason);
    logger.error("Unhandled promise rejection in Pi Host", {
      error: message,
      stack: reason instanceof Error ? reason.stack : undefined,
    });
    void server.requestFatalShutdown(
      createHostError("INTERNAL_ERROR", `Unhandled asynchronous failure: ${message}`),
      "unhandled promise rejection",
    );
  });
  process.on("uncaughtException", (err) => {
    logger.error("Uncaught exception in Pi Host", {
      error: err instanceof Error ? err.message : String(err),
      stack: err instanceof Error ? err.stack : undefined,
    });
    process.exit(1);
  });
  process.once("SIGINT", () => {
    void server.requestShutdown("SIGINT");
  });
  process.once("SIGTERM", () => {
    void server.requestShutdown("SIGTERM");
  });

  // Preload the last-used workspace BEFORE the server starts reading stdin
  // and announces ready: the expensive first graph build (user packages,
  // extensions) overlaps WebView/frontend startup, and early client requests
  // simply wait in the stdin buffer — no identity races. Failures are
  // non-fatal: the frontend falls back to its own workspace.setCurrent.
  const initialCwd = resolveInitialCwd();
  // B1 opt-in switch (PIABYSS_DEFER_PRELOAD=1): skip the blocking preload so
  // host.ready lands before any graph is built and the frontend drives
  // workspace.setCurrent itself. Unset — the default — keeps today's
  // overlap-preload behaviour exactly.
  const deferPreload = process.env.PIABYSS_DEFER_PRELOAD === "1";
  if (initialCwd && deferPreload) {
    logger.info("initial workspace preload deferred", {
      cwd: initialCwd,
      phase: "waitingForWorkspace",
    });
  } else if (initialCwd) {
    const preloadStarted = Date.now();
    try {
      const preload = await graphFactory.setCurrent(initialCwd, randomUUID());
      if ("error" in preload) {
        logger.warn("initial workspace preload failed", {
          cwd: initialCwd,
          error: preload.error.message,
        });
      } else {
        logger.info("initial workspace preloaded", {
          cwd: initialCwd,
          ms: Date.now() - preloadStarted,
        });
      }
    } catch (err) {
      logger.warn("initial workspace preload crashed", {
        cwd: initialCwd,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  const serverStartStarted = Date.now();
  await server.start();
  logger.info("host server started", {
    ms: Date.now() - serverStartStarted,
    initialWorkspace: initialCwd ? (deferPreload ? "deferred" : "preloaded") : "none",
  });
  await migrationBackup?.recordMilestone("serverStart");
