import { useState } from "react";
import { ChevronDown, Pencil, Play, Trash2, ArrowUp, Check, Paperclip, X } from "lucide-react";
import { useAppStore } from "../../lib/stores/app-store";
import { hostClient } from "../../lib/bridge/host-client";
import { hostErrorLevel, localizeHostError } from "../../lib/bridge/localize-host-error";
import { activeSessionContext } from "../../lib/bridge/host-context";
import { useImeComposition } from "../../lib/use-ime-composition";
import {
  parseAttachmentReferences,
  preserveAttachmentReferenceBlocks,
  stripAttachmentReferenceBlocks,
  type ActiveSessionContext,
} from "@piabyss/protocol";
import { useT } from "../../lib/i18n/use-t";
import {
  appendOptimisticUserMessage,
  removeOptimisticUserMessage,
} from "../../lib/chat/optimistic-echo";

/**
 * Waiting queue above the composer. Backed by the SDK queue (visible to the
 * CLI too); reorder/edit/delete use revisioned agent.setQueue transactions.
 * "Run now" is one Host-owned interrupt/start/restore transaction.
 */

/** Transient conditions worth a short retry — e.g. the operation lock of an
 * aborted run releases a beat after agent.abort responds. */
const RETRYABLE_CODES = new Set(["AGENT_BUSY", "SERVICE_GRAPH_BUSY", "PACKAGE_MUTATION_BUSY"]);

function QueueText({ raw }: { raw: string }) {
  const t = useT();
  const visible = stripAttachmentReferenceBlocks(raw).trim();
  const attachments = parseAttachmentReferences(raw);
  return (
    <span className="flex min-w-0 flex-1 items-center gap-1.5 text-xs leading-4" title={visible}>
      <span className="min-w-0 flex-1 truncate">{visible || t("queueAttachmentOnly")}</span>
      {attachments.length > 0 && (
        <span className="flex shrink-0 items-center gap-0.5 text-[10px] text-muted">
          <Paperclip size={10} />
          {attachments.length}
        </span>
      )}
    </span>
  );
}

async function setQueueWithRetry(
  context: ActiveSessionContext,
  params: { expectedRevision: number; steering: string[]; followUp: string[] },
) {
  for (let attempt = 0; ; attempt += 1) {
    const res = await hostClient.request("agent.setQueue", context, params);
    if (res.ok || attempt >= 3 || !RETRYABLE_CODES.has(res.error?.code ?? "")) {
      return res;
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
}

export function QueuePanel() {
  const t = useT();
  const host = useAppStore((s) => s.host);
  const workspace = useAppStore((s) => s.workspace);
  const session = useAppStore((s) => s.session);
  const setSession = useAppStore((s) => s.applySessionSnapshot);
  const pushNotification = useAppStore((s) => s.pushNotification);
  const [collapsed, setCollapsed] = useState(false);
  const [busyOp, setBusyOp] = useState(false);
  const [editing, setEditing] = useState<{
    index: number;
    text: string;
    original: string;
  } | null>(null);
  const ime = useImeComposition();

  const steering = session?.pending.steering ?? [];
  const followUp = session?.pending.followUp ?? [];
  const total = steering.length + followUp.length;
  if (!session || total === 0) return null;

  async function applyQueue(nextSteering: string[], nextFollowUp: string[]) {
    if (!host || !workspace || !session || busyOp) return;
    setBusyOp(true);
    try {
      const res = await setQueueWithRetry(activeSessionContext(host, workspace, session), {
        expectedRevision: session.pending.revision,
        steering: nextSteering,
        followUp: nextFollowUp,
      });
      if (!res.ok) {
        pushNotification(localizeHostError(res.error, t), hostErrorLevel(res.error));
      }
    } finally {
      setBusyOp(false);
    }
  }

  async function runNow(kind: "followUp" | "steering", index: number) {
    if (!host || !workspace || !session || busyOp) return;
    const queuedText = kind === "followUp" ? followUp[index] : (steering[index] ?? undefined);
    if (queuedText === undefined) return;
    const targetSessionId = session.sessionId;
    const targetSessionRevision = session.revision;
    // The queued item starts a real turn immediately; echo it into the
    // transcript without waiting for the Host's message_start (which can lag
    // behind SDK preflight). A rejected/failed start rolls the row back; the
    // authoritative message then claims it in place.
    const optimisticKey = appendOptimisticUserMessage(queuedText, session.sessionId);
    setBusyOp(true);
    try {
      const context = activeSessionContext(host, workspace, session);
      const response = await hostClient.request("agent.runNow", context, {
        expectedRevision: session.pending.revision,
        ...(kind === "followUp" ? { followUpIndex: index } : { steeringIndex: index }),
      });
      if (!response.ok) {
        removeOptimisticUserMessage(optimisticKey);
        pushNotification(localizeHostError(response.error, t), hostErrorLevel(response.error));
        return;
      }
      if (response.result.started !== true) {
        // The item could not start (lock/abort race) — roll the echo back.
        removeOptimisticUserMessage(optimisticKey);
      }
      const current = useAppStore.getState().session;
      if (
        current?.sessionId === targetSessionId &&
        current.revision === targetSessionRevision &&
        response.result.queue.revision >= current.pending.revision
      ) {
        setSession({
          ...current,
          pending: response.result.queue,
        });
      }
      if (response.result.error) {
        pushNotification(response.result.error.message, "error");
      }
    } finally {
      setBusyOp(false);
    }
  }

  const itemButton =
    "flex size-6 items-center justify-center rounded text-muted hover:bg-surface-overlay hover:text-foreground disabled:opacity-30";

  return (
    <div className="conversation-content-width mx-auto mb-1.5 w-full rounded-lg border border-border bg-surface-raised/80">
      <button
        type="button"
        className="flex h-8 w-full items-center gap-2 px-3 text-xs text-muted hover:text-foreground"
        onClick={() => setCollapsed((c) => !c)}
        aria-expanded={!collapsed}
      >
        <span className="font-medium">{t("queueTitle", { count: total })}</span>
        <ChevronDown
          size={13}
          className={`ml-auto transition-transform ${collapsed ? "-rotate-90" : ""}`}
        />
      </button>
      {!collapsed && (
        <ul className="border-t border-border px-1.5 py-1">
          {steering.map((text, index) => (
            <li
              key={`steer:${index}`}
              className="group flex items-start gap-2 rounded px-1.5 py-1 hover:bg-surface-overlay/50"
            >
              <span className="mt-0.5 shrink-0 rounded bg-warning/15 px-1 text-[10px] font-medium leading-none text-warning">
                {t("queueSteering")}
              </span>
              <QueueText raw={text} />
              <span className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100">
                {session.isIdle && (
                  <button
                    type="button"
                    title={t("queueRunNowSteering")}
                    aria-label={t("queueRunNowSteering")}
                    className={itemButton}
                    disabled={busyOp}
                    onClick={() => void runNow("steering", index)}
                  >
                    <Play size={12} />
                  </button>
                )}
                <button
                  type="button"
                  title={t("queueRemove")}
                  aria-label={t("queueRemove")}
                  className={itemButton}
                  disabled={busyOp}
                  onClick={() =>
                    void applyQueue(
                      steering.filter((_, i) => i !== index),
                      [...followUp],
                    )
                  }
                >
                  <Trash2 size={12} />
                </button>
              </span>
            </li>
          ))}
          {followUp.map((text, index) =>
            editing?.index === index ? (
              <li key={`edit:${index}`} className="flex items-start gap-1.5 rounded px-1.5 py-1">
                <textarea
                  autoFocus
                  aria-label={t("queueEditMessage")}
                  className="min-h-[52px] flex-1 rounded border border-accent bg-surface px-2 py-1 text-xs outline-none"
                  value={editing.text}
                  onChange={(event) => setEditing({ ...editing, text: event.target.value })}
                  onCompositionStart={ime.onCompositionStart}
                  onCompositionEnd={ime.onCompositionEnd}
                  onKeyDown={(event) => {
                    if (ime.isImeKey(event)) return;
                    if (event.key === "Enter" && !event.shiftKey) {
                      event.preventDefault();
                      const next = [...followUp];
                      if (editing.text.trim()) {
                        next[index] = preserveAttachmentReferenceBlocks(
                          editing.original,
                          editing.text,
                        );
                      }
                      void applyQueue([...steering], next);
                      setEditing(null);
                    }
                    if (event.key === "Escape") setEditing(null);
                  }}
                />
                <button
                  type="button"
                  title={t("queueSave")}
                  aria-label={t("queueSave")}
                  className={itemButton}
                  onClick={() => {
                    const next = [...followUp];
                    if (editing.text.trim()) {
                      next[index] = preserveAttachmentReferenceBlocks(
                        editing.original,
                        editing.text,
                      );
                    }
                    void applyQueue([...steering], next);
                    setEditing(null);
                  }}
                >
                  <Check size={13} />
                </button>
                <button
                  type="button"
                  title={t("queueCancel")}
                  aria-label={t("queueCancel")}
                  className={itemButton}
                  onClick={() => setEditing(null)}
                >
                  <X size={13} />
                </button>
              </li>
            ) : (
              <li
                key={`fu:${index}`}
                className="group flex items-start gap-2 rounded px-1.5 py-1 hover:bg-surface-overlay/50"
              >
                <span className="mt-1 size-1 shrink-0 rounded-full bg-muted" />
                <QueueText raw={text} />
                <span className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100">
                  <button
                    type="button"
                    title={t("queueMoveUp")}
                    aria-label={t("queueMoveUp")}
                    className={itemButton}
                    disabled={busyOp || index === 0}
                    onClick={() => {
                      const next = [...followUp];
                      [next[index - 1], next[index]] = [next[index]!, next[index - 1]!];
                      void applyQueue([...steering], next);
                    }}
                  >
                    <ArrowUp size={12} />
                  </button>
                  <button
                    type="button"
                    title={t("queueEdit")}
                    aria-label={t("queueEdit")}
                    className={itemButton}
                    disabled={busyOp}
                    onClick={() =>
                      setEditing({
                        index,
                        text: stripAttachmentReferenceBlocks(text).trim(),
                        original: text,
                      })
                    }
                  >
                    <Pencil size={12} />
                  </button>
                  <button
                    type="button"
                    title={t("queueRunNow")}
                    aria-label={t("queueRunNow")}
                    className={itemButton}
                    disabled={busyOp}
                    onClick={() => void runNow("followUp", index)}
                  >
                    <Play size={12} />
                  </button>
                  <button
                    type="button"
                    title={t("queueRemove")}
                    aria-label={t("queueRemove")}
                    className={itemButton}
                    disabled={busyOp}
                    onClick={() =>
                      void applyQueue(
                        [...steering],
                        followUp.filter((_, i) => i !== index),
                      )
                    }
                  >
                    <Trash2 size={12} />
                  </button>
                </span>
              </li>
            ),
          )}
        </ul>
      )}
    </div>
  );
}

function reconcilePromptCache(
  session: AgentSession,
  sessionId: string | null,
  runId: string,
): void {
  const fingerprint = collectPromptCacheFingerprint(session);
  const previous = promptCacheStates.get(session);
  promptCacheStates.set(session, { hash: fingerprint.hash, parts: fingerprint.parts, runId });
  if (!previous) {
    logger.debug("Prompt cache fingerprint baseline", {
      sessionId,
      runId,
      hash: fingerprint.hash,
    });
  } else if (previous.hash !== fingerprint.hash) {
    logger.warn(
      "Prompt cache prefix drift: provider prompt cache will be invalidated for this run",
      {
        sessionId,
        runId,
        changed: diffPromptCacheFingerprints(previous.parts, fingerprint.parts),
        prevHash: previous.hash,
        nextHash: fingerprint.hash,
      },
    );
  } else {
    logger.debug("Prompt cache fingerprint unchanged", {
      sessionId,
      runId,
      hash: fingerprint.hash,
    });
  }
}

export function summarizeModel(model: Model<any>, providerName?: string): ModelSummary {
  return {
    provider: model.provider,
    providerName,
    modelId: model.id,
    name: model.name ?? model.id,
    thinkingLevels: getSupportedThinkingLevels(model).map(String),
  };
}

function startDetachedPrompt(args: {
  requestId: string;
  factory: WorkspaceGraphFactory;
  server: PiHostServer;
  session: AgentSession;
  operationLock: AgentOperationLock;
  text: string;
  images?: ImageContent[];
  streamingBehavior?: "steer" | "followUp";
}): string {
  let runStatePublished = false;
  let detachedTaskStarted = false;
  const cleanup = (settled: boolean) => {
    args.operationLock.release(args.requestId);
    if (runStatePublished) {
      // agent_settled fires before AgentSession.prompt() resolves. Until this
      // lock is released, isSessionBusy() still reports running and suppresses
      // the idle edge. Publish once more after release so completion reaches
      // the desktop and the cross-workspace activity tracker. The publication
      // resolves the owning graph's CURRENT bound identity: a run can outlive
      // the identity captured at start (park + re-activation bump
      // workspaceRevision), and emitting under the captured one would throw on
      // the stale-revision check — losing the terminal idle edge and sticking
      // the session's dot on "running" forever.
      if (settled) {
        args.factory.publishCurrentRuntimeStateForSession(args.session);
      }
      args.factory.clearSessionRunId(args.session);
      // Host-wide: a parked workspace graph may still be mid-run, and the
      // phase must stay agentBusy until the LAST bound session settles.
      if (args.server.getPhase() === "agentBusy" && !args.factory.hasAnyBusySessions()) {
        args.server.setPhase("ready");
      }
      args.factory.currentRunId = null;
    }
  };

  try {
    const runId = randomUUID();
    // C1: attribute every provider registration inside this turn to the graph
    // that started it, not to whichever graph happens to be active when a late
    // pi.registerProvider fires. Captured synchronously: the detached task
    // below may run after the active graph changed.
    const initiatingOwner = args.factory.getGraph()?.providerOwner ?? null;
    const runIdentity = args.server.getIdentity();
    const visibleText = stripAttachmentReferenceBlocks(args.text);
    const provisionalTitle =
      args.session.sessionName?.trim() || !visibleText.trim()
        ? null
        : createProvisionalSessionTitle(visibleText);
    const titleSessionId = args.server.identity.sessionId;
    const extensionCommandInvocation = resolveExtensionCommandInvocation(args.session, args.text);

    reconcilePromptCache(args.session, titleSessionId, runId);

    runStatePublished = true;
    args.factory.currentRunId = runId;
    args.factory.setSessionRunId(args.session, runId);
    args.server.setPhase("agentBusy");
    if (provisionalTitle) args.factory.setActiveSessionName(provisionalTitle);

    void (async () => {
      let completed = false;
      try {
        const runPrompt = () =>
          args.session.prompt(args.text, {
            streamingBehavior: args.streamingBehavior,
            ...(args.images ? { images: args.images } : {}),
          });
        // Outermost wrap (C1): withExtensionCommandOrigin stays inside the
        // ownership scope so the whole turn — extension-command invocations
        // included — registers against the initiating graph's owner.
        const runTurn = () =>
          extensionCommandInvocation
            ? withExtensionCommandOrigin(args.session, runId, extensionCommandInvocation, runPrompt)
            : runPrompt();
        if (initiatingOwner) {
          await args.factory.deps.providerOwnership.runAsOwner(initiatingOwner, runTurn);
        } else {
          // No owner (e.g. failed graph): keep the ambient fallback behaviour.
          await runTurn();
        }
        completed = true;
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        // The graph may have been parked or re-activated while the run was in
        // flight (workspaceRevision moved); emitForIdentity with the captured
        // identity would throw on the stale-revision check and lose the
        // failure signal entirely — no error event, no error dot, runtime
        // stuck on "running". Attribute via the owning graph's current bound
        // identity instead; fall back to the captured one when no bound graph
        // owns the session (disposed mid-run).
        const identity = args.factory.currentSessionIdentity(args.session) ?? runIdentity;
        // agent.event is validated by the desktop against the FOREGROUND
        // workspace identity: an error emitted under a parked graph's bound
        // identity is dropped as an identity mismatch and tears the whole
        // renderer epoch down (recovery churn). Parked failures therefore
        // signal through session.runtimeChanged alone — the desktop's
        // parked-event bypass accepts it and the cross-workspace activity
        // snapshot turns it into a terminal marker + system notification.
        const currentIdentity = args.server.getIdentity();
        const isForegroundIdentity =
          identity.workspaceId !== null &&
          identity.workspaceId === currentIdentity.workspaceId &&
          identity.workspaceRevision === currentIdentity.workspaceRevision;
        if (isForegroundIdentity) {
          try {
            args.server.emitForBoundIdentity(identity, "agent.event", {
              runId,
              event: {
                type: "error",
                message,
              },
            });
          } catch {
            // Identity lapsed between the check and the emit (mid-run unbind).
            // The runtime event below still carries the failure.
          }
        }
        try {
          args.server.emitForBoundIdentity(identity, "session.runtimeChanged", {
            sessionId: identity.sessionId!,
            sessionRevision: identity.sessionRevision,
            state: "error",
            updatedAt: Date.now(),
            error: message,
          });
        } catch {
          // No bound graph owns the session any more (disposed mid-run): the
          // pool's busy bookkeeping is cleared by cleanup() below; nothing
          // further can attribute this failure. Never let the throw escape
          // the catch block — it would skip cleanup() bookkeeping and reject
          // the detached task with an unhandled rejection.
        }
      } finally {
        cleanup(completed);
      }
      if (completed && provisionalTitle && titleSessionId) {
        await args.factory.refineActiveSessionName({
          session: args.session,
          sessionId: titleSessionId,
          provisionalTitle,
          userPrompt: args.text,
        });
      }
    })().catch((err: unknown) => {
      logger.error("Detached agent prompt task failed", {
        runId,
        error: err instanceof Error ? err.message : String(err),
      });
    });

    detachedTaskStarted = true;
    return runId;
  } finally {
    if (!detachedTaskStarted) cleanup(false);
  }
}

/** Hidden OCR instructions injected alongside attachments that need OCR. */
function buildOcrGuideText(attachments: readonly AttachmentSnapshot[]): string | null {
  const scanned = attachments.filter((attachment) => attachment.status === "needs_ocr");
  if (scanned.length === 0) return null;
  const list = scanned
    .map((attachment) => {
      const pages = attachment.unitCount !== undefined ? `（共 ${attachment.unitCount} 页）` : "";
      return `- ${attachment.name}${pages}`;
    })
    .join("\n");
