const fs=require("fs");
const f=process.argv[1];
const lines=fs.readFileSync(f,"utf8").split("\n").filter(Boolean);
console.log("total lines",lines.length);
let idx=0;
for(const line of lines){
  let e; try{e=JSON.parse(line)}catch{continue}
  idx++;
  const t=e.type;
  let role="", text="";
  if(t==="message"){
    role=e.message?.role||"?";
    const c=e.message?.content;
    if(typeof c==="string") text=c;
    else if(Array.isArray(c)) text=c.map(p=>p.type==="text"?p.text:(p.type==="image"?"[img]":"["+p.type+"]")).join("");
    else text=JSON.stringify(c||"").slice(0,80);
  } else if(t==="custom_message"){ role="custom:"+(e.customType||""); text=typeof e.content==="string"?e.content:JSON.stringify(e.content).slice(0,80);}
  else if(t==="session"){ role="header"; text=(e.cwd||"")+" v"+e.version; }
  else if(t==="session_info"){ role="session_info"; text=e.name||""; }
  else if(t==="model_change"){ role="model"; text=(e.provider||"")+"/"+(e.modelId||""); }
  else if(t==="thinking_level_change"){ role="thinking"; text=String(e.thinkingLevel); }
  else if(t==="compaction"){ role="compaction"; text="tokensBefore="+e.tokensBefore+" kept="+e.firstKeptEntryId; }
  else if(t==="branch_summary"){ role="branch_summary"; text=(e.summary||"").slice(0,60); }
  else if(t==="label"){ role="label"; text=(e.label||""); }
  else { role=t; text=JSON.stringify(e).slice(0,80); }
  console.log(String(idx).padStart(4), (e.id||"-").padEnd(10), t.padEnd(18), String(role).padEnd(20), (e.timestamp||"").toString().slice(0,24).padEnd(25), JSON.stringify(text.slice(0,110)));
}
